-- DSM-5-TR (curso="DSM-5-TR"), parte 2 de 3: 154 preguntas.
-- Ejecutar en Supabase (Dashboard -> SQL Editor -> New query -> Run). Las tres partes
-- son independientes y da igual el orden.
--
-- Fuente: "DSM-5-TR. Preguntas de autoevaluación. Exámenes tipo test sobre los
-- criterios diagnósticos" (Muskin y cols., Editorial Médica Panamericana),
-- Parte II "Guía de respuestas", que repite cada pregunta con su respuesta correcta,
-- su explicación y la referencia al DSM-5-TR. Transcrito por OCR de un escaneo y
-- generado por un script que valida cada fila antes de escribir (4 opciones,
-- correcta 0-3, enunciado acabado en ? : o ., sin restos de maquetación ni el
-- "punto + número suelto" de supabase-detectar-basura-preguntas.sql).
--
-- tema = el capítulo del libro. explicacion = la del libro + "Referencia: DSM-5-TR, ..."
-- con el apartado y la página del manual.
--
-- Se puede volver a ejecutar sin duplicar nada: cada fila solo entra si no hay ya
-- una pregunta DSM-5-TR con el mismo enunciado y las mismas opciones.
--
-- Capítulos de esta parte: Trastornos obsesivo-compulsivos y trastornos relacionados; Trastornos relacionados con traumas y factores de estrés; Trastornos disociativos; Trastorno de síntomas somáticos y trastornos relacionados; Trastornos de la conducta alimentaria y de la ingesta de alimentos; Trastornos de la excreción; Trastornos del sueño-vigilia; Disfunciones sexuales; Disforia de género; Trastornos disruptivos, del control de los impulsos y de la conducta.

insert into public.preguntas (curso, tema, pregunta, opciones, correcta, explicacion, inventada)
select v.curso, v.tema, v.pregunta, v.opciones::jsonb, v.correcta, v.explicacion, false
from (values
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', '¿Cómo se definen las compulsiones en el trastorno obsesivo-compulsivo (TOC)?', '["Las compulsiones en el TOC suelen ir dirigidas a un objetivo, cumpliendo un propósito realista.", "Las compulsiones incluyen parafilias (compulsiones sexuales) y comportamientos adictivos como el juego o el consumo de sustancias.", "Las compulsiones implican pensamientos, imágenes o impulsos repetitivos y persistentes.", "Las compulsiones en el TOC están destinadas a reducir la angustia desencadenada por las obsesiones."]', 3, 'Las obsesiones son pensamientos (por ejemplo, de contaminación), imágenes (por ejemplo, de escenas violentas u horribles) o impulsos (por ejemplo, de apuñalar a alguien) repetitivos y persistentes. Las compulsiones (o rituales) son comportamientos repetitivos (por ejemplo, lavado, comprobación) o actos mentales (por ejemplo, contar, repetir palabras en silencio) que la persona se siente impulsada a realizar en respuesta a una obsesión o según reglas que deben aplicarse de manera rígida. La mayoría de las personas con TOC tienen tanto obsesiones como compulsiones. Las compulsiones se realizan típicamente en respuesta a una obsesión (por ejemplo, pensamientos de contaminación que llevan a rituales de lavado o de que algo está incorrecto que conducen a rituales de repetición hasta sentir que que se sienta "ya vale"). El objetivo es reducir la angustia desencadenada por las obsesiones o prevenir un evento temido (por ejemplo, enfermar). Sin embargo, estas compulsiones bien no están conectadas de manera realista con el suceso temido (por ejemplo, ordenar objetos simétricamente para prevenir el daño a un ser querido) o bien son excesivas (por ejemplo, ducharse durante horas cada día). Las compulsiones no se realizan por placer, aunque algunas personas experimentan alivio de la ansiedad o la angustia. Ciertos comportamientos a veces se describen como "compulsivos", incluyendo el comportamiento sexual (en el caso de las parafilias), el juego (es decir, en el trastorno del juego) y el consumo de sustancias (por ejemplo, en el trastorno por consumo de alcohol). Sin embargo, estos comportamientos difieren de las compulsiones del TOC en que la persona generalmente obtiene placer de la actividad y puede desear resistirse a ella solo por sus consecuencias perjudiciales. Referencia: DSM-5-TR, Trastorno obsesivo-compulsivo / Criterios diagnósticos (p. 265); Características diagnósticas (pp. 266-267); Diagnóstico diferencial (pp. 270-271).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'Un hombre de 52 años con las manos en carne viva y agrietadas es derivado a un psiquiatra por su médico de atención primaria. El hombre explica que se lava las manos repetidamente, dedicando hasta 4 horas al día a la labor y utilizando limpiadores abrasivos y agua hirviendo. Aunque admite que sus manos están mal, está completamente convencido de que si no se lava de esta manera se pondrá gravemente enfermo. Un chequeo médico no revela nada y el hombre no toma ningún medicamento. ¿Cuál es el diagnóstico más apropiado?', '["Trastorno delirante, tipo somático.", "Trastorno de ansiedad por enfermedad.", "Trastorno obsesivo-compulsivo (TOC), con ausencia de introspección.", "Trastorno facticio."]', 2, 'El trastorno obsesivo-compulsivo y trastornos relacionados que tienen un componente cognitivo (es decir, TOC, trastorno dismórfico corporal y trastorno de acumulación) incluyen un especificador para indicar el grado de introspección del individuo con respecto a las creencias relacionadas con el trastorno. Las personas con TOC varían en cuanto al grado de certeza que tienen sobre la precisión de las creencias que subyacen en sus síntomas obsesivo-compulsivos. Muchas personas tienen una introspección buena o suficiente (por ejemplo, la persona cree que la casa definitivamente no, probablemente no, o quizá no va a quemarse si no comprueba el horno como mínimo 30 veces). Algunos tienen una introspección escasa (por ejemplo, la persona cree que la casa probablemente se quemará si no comprueba el horno 30 veces) y unos pocos (4% o menos) carecen de introspección o poseen creencias delirantes (por ejemplo, la persona está convencida de que la casa se quemará si no comprueba el horno 30 veces). Algunas personas con TOC tienen una introspección escasa o incluso creencias delirantes; sin embargo, tienen obsesiones y compulsiones (lo que distingue su afección del trastorno delirante) y no tienen otras características de la esquizofrenia o el trastorno esquizoafectivo (por ejemplo, alucinaciones o habla desorganizada). En las personas con síntomas de TOC que justifican el especificador con ausencia de introspección /creencias delirantes, estos síntomas no deben diagnosticarse como un trastorno psicótico. En el DSM-5-TR, si la creencia delirante se limita a las obsesiones y compulsiones, no se requiere un diagnóstico de trastorno psicótico separado. Las personas con trastorno de ansiedad por enfermedad se preocupan por tener una enfermedad; sin embargo, no tienen las obsesiones y compulsiones clásicas que se encuentran en el TOC. La dermatitis artefacta (también conocida como dermatitis facticia) es un término utilizado en dermatología para referirse a lesiones cutáneas médicamente inexplicables, presumiblemente autoinducidas, que la persona niega haberse producido. Los casos en que hay evidencia de engaño por parte de la persona con respecto a las lesiones cutáneas pueden diagnosticarse de simulación (si el picoteo de la piel está motivado por incentivos externos) o de trastorno facticio (si el picoteo de la piel ocurre en ausencia de recompensas externas obvias). En ausencia de engaño, se puede diagnosticar el trastorno de excoriación si hay intentos repetidos de disminuir o detener el picoteo o rascado de la piel. Referencia: DSM-5-TR, Trastorno obsesivo-compulsivo / Especificadores (p. 266) y Diagnóstico diferencial (pp. 270-271); Trastorno de excoriación (rascarse la piel) / Diagnóstico diferencial (p. 287).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'En el trastorno obsesivo-compulsivo (TOC), ¿cuál de las siguientes opciones es más probable que se vea en los hombres que en las mujeres?', '["Tics comórbidos.", "Edad de inicio más tardía.", "Obsesión con la limpieza.", "Asociaciones de síntomas hormonales."]', 0, 'Los hombres tienen una edad de inicio del TOC más temprana que las mujeres, a menudo en la infancia, y es más probable que tengan trastornos de tics comórbidos. El inicio en las niñas es más típico en la adolescencia; entre los adultos, el TOC es ligeramente más común en las mujeres que en los hombres. Se han encontrado diferencias de género en el patrón relativo a las dimensiones de síntomas, siendo, por ejemplo, las mujeres más propensas a tener síntomas de la dimensión de limpieza y los hombres más propensos a tener síntomas de las dimensiones de pensamientos prohibidos y simetría. Se ha observado también la aparición o exacerbación del TOC, así como de síntomas capaces de interferir en la relación madre-lactante (por ejemplo, obsesiones agresivas como pensamientos violentos intrusivos de dañar al bebé, lo que lleva a evitarlo), en el período periparto. Algunas mujeres también refieren la exacerbación de los síntomas del TOC premenstrualmente. Referencia: DSM-5-TR, Trastorno obsesivo-compulsivo / Aspectos diagnósticos relacionados con el sexo y el género (pp. 268-269).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'Una mujer de 63 años ha estado guardando documentos y registros financieros durante décadas, colocando papeles en pilas por todo su apartamento hasta el punto de que este se ha vuelto inseguro. Reconoce que las pilas son una preocupación; sin embargo, dice que los papeles incluyen documentos importantes y tiene miedo de tirarlos. Recuerda una ocasión en la que auditaron sus impuestos y necesitó ciertos documentos para evitar la multa. Describe que se preocupa repetidamente por si llega una nueva auditoría, siendo incapaz de ignorar estas preocupaciones. Se siente algo aliviada por su creciente pila de papeleo legal, pero está preocupada porque su casero la amenaza con desalojarla a menos que retire las pilas de papeles. ¿Cuál es el diagnóstico más probable?', '["Comportamiento de recolección no patológico.", "Trastorno de acumulación.", "Trastorno obsesivo-compulsivo (TOC).", "Demencia (trastorno neurocognitivo mayor)."]', 2, 'Los síntomas del trastorno de acumulación se centran exclusivamente en la dificultad persistente de desechar o separarse de pertenencias, el malestar marcado que acompaña al hecho de desechar objetos y la acumulación excesiva de objetos. Sin embargo, si una persona tiene obsesiones que son típicas del TOC (por ejemplo, preocupaciones por lo incompleto o por el daño) y estas obsesiones conducen a una acumulación compulsiva (por ejemplo, adquirir todos los objetos de un conjunto para lograr que esté completo o no desechar los periódicos viejos porque pueden contener información que podría prevenir daños), se debe dar un diagnóstico de TOC en su lugar. El trastorno de acumulación no se diagnostica si los síntomas se juzgan como una consecuencia directa de obsesiones o compulsiones típicas, como temores de contaminación o daño, o como sentimientos de que algo está incompleto en el TOC. Los sentimientos de que algo está incompleto (por ejemplo, perder la identidad, tener que documentar y preservar todas las experiencias de vida) son los síntomas más frecuentes del TOC que se asocian a esta forma de acumulación. Referencia: DSM-5-TR, Trastorno obsesivo-compulsivo / Diagnóstico diferencial (pp. 270-271); Trastorno de acumulación / Diagnóstico diferencial (pp. 280-281).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', '¿Cuál de los siguientes es un factor protector frente al riesgo de suicidio que acompaña al trastorno obsesivo-compulsivo (TOC)?', '["Género masculino.", "Obsesiones religiosas.", "Abuso de sustancias.", "Trastorno de ansiedad comórbido."]', 3, 'Una revisión sistemática de la bibliografía sobre ideación suicida e intentos de suicidio en muestras clínicas de personas con TOC de varios países encontró una tasa promedio de intentos de suicidio durante la vida del 14,2%, una tasa promedio de ideación suicida en la vida del 44,1% y una tasa promedio de ideación suicida actual del 25,9%. Los predictores de mayor riesgo de suicidio fueron la gravedad del TOC, la dimensión de síntomas de pensamientos inaceptables, la gravedad de los síntomas depresivos y de ansiedad comórbidos, y la historia pasada de suicidio. Otra revisión sistemática internacional de 48 estudios encontró una asociación significativa, de moderada a alta, entre la ideación suicida o los intentos de suicidio y el TOC. Un estudio transversal de 582 pacientes ambulatorios con TOC en Brasil encontró que el 36% referían haber tenido pensamientos suicidas durante la vida, el 20% habían hecho planes de suicidio, el 11% ya habían intentado suicidarse y el 10% presentaban pensamientos de suicidio actuales. La dimensión sexual/religiosa del TOC y los trastornos por consumo de sustancias comórbidos se asociaron a pensamientos suicidas y planes de suicidio, los trastornos del control de los impulsos se asociaron a pensamientos suicidas actuales y a planes e intentos de suicidio, y el trastorno depresivo mayor comórbido y el trastorno de estrés postraumático durante la vida se asociaron a todos los aspectos de los comportamientos suicidas. En un estudio que utilizó datos del registro nacional sueco sobre 36.788 individuos con TOC y sujetos de control de la población general emparejados, los individuos con TOC tenían un mayor riesgo de muerte por suicidio (OR =9,8) y de intentos de suicidio (OR =5,5), y el aumento del riesgo de ambos resultados se mantuvo sustancial incluso después de ajustar las comorbilidades psiquiátricas. El trastorno de la personalidad comórbido o el trastorno por consumo de sustancias aumentaban el riesgo de suicidio, mientras que el género femenino, la mayor educación de los padres y el trastorno de ansiedad comórbido eran factores protectores. Referencia: DSM-5-TR, Trastorno obsesivo-compulsivo / Asociación a pensamientos o conductas suicidas (p. 269).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', '¿Cuál de las siguientes opciones es necesaria para el diagnóstico de trastorno dismórfico corporal (TDC)?', '["Un defecto físico aparente observable por un médico.", "Comportamientos o pensamientos repetitivos relacionados con la preocupación por la apariencia de uno.", "Pérdida de peso insalubre con el objetivo de mejorar la apariencia personal.", "Preservación de la función social, ocupacional y general de base."]', 1, 'Las personas con TDC (anteriormente conocido como dismorfofobia) están preocupadas por uno o más defectos o imperfecciones que perciben en su apariencia física (Criterio A), que creen que es fea, poco atractiva, anormal o deforme. Los defectos percibidos no son observables o parecen solo leves a otras personas. Las preocupaciones son intrusivas, no deseadas, consumen tiempo (ocurren, de media, de 3 a 8 horas por día) y generalmente son difíciles de resistir o controlar. Se realizan comportamientos o actos mentales repetitivos excesivos (por ejemplo, comparar) en respuesta a la preocupación (Criterio B). La persona se siente impulsada a realizar estos comportamientos, que no son placenteros y pueden aumentar la ansiedad y la disforia. La preocupación debe causar malestar o deterioro clínicamente significativos en el ámbito social, ocupacional o en otras áreas importantes del funcionamiento (Criterio C); generalmente están presentes tanto el malestar como el deterioro. El TDC debe diferenciarse de los trastornos alimentarios. En el TDC, la introspección puede ser buena, mala o incluso ausente/delirante. Referencia: DSM-5-TR, Trastorno dismórfico corporal / Criterios diagnósticos (pp. 271-272); Características diagnósticas (pp. 272-2753).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'Un hombre de 25 años está preocupado porque se ve "débil" y "enclenque" a pesar de que para los observadores neutrales parece muy musculoso. Cuando se le cuestiona su creencia, piensa que se le está tomando el pelo y que la gente se burla a sus espaldas de su apariencia. Ha probado varias estrategias para aumentar la masa muscular, como hacer ejercicio en exceso y usar esteroides anabólicos; sin embargo, sigue insatisfecho con su apariencia. ¿Cuál es el diagnóstico más probable?', '["Trastorno delirante, tipo somático.", "Trastorno dismórfico corporal (TDC), con dismorfia muscular.", "Trastorno de la integridad de la identidad corporal.", "Koro."]', 1, 'La dismorfia muscular, una forma de TDC que ocurre casi exclusivamente en hombres y adolescentes, consiste en la preocupación por la idea de que el cuerpo de uno es demasiado pequeño o insuficientemente delgado o musculoso. Las personas con esta forma del trastorno en realidad tienen un cuerpo de aspecto normal o incluso muy musculoso. También pueden estar preocupadas por otras áreas del cuerpo, como la piel o el cabello. La mayoría (pero no todos) hacen dieta, practican ejercicio y/o levantan pesas en exceso, a veces causando daño corporal. Algunos usan esteroides androgénicos anabolizantes potencialmente peligrosos y otras sustancias para intentar hacer su cuerpo más grande y musculoso. Las ideas o delirios de referencia relacionados con la apariencia (es decir, pensar que otras personas le prestan a uno una atención especial de connotación negativa debido a la apariencia) son comunes en el TDC. Sin embargo, a diferencia de la esquizofrenia o el trastorno esquizoafectivo, el TDC implica preocupaciones destacadas por la apariencia y comportamientos repetitivos relacionados; el comportamiento desorganizado y otros síntomas psicóticos están ausentes (excepto por las creencias acerca de la apariencia, que pueden ser delirantes). La disforia de integridad corporal (que aparece en la CIE-11 pero no en el DSM-5) implica un deseo persistente de convertirse en amputado para corregir una discrepancia entre la manera en que la persona cree que debería estar configurado el cuerpo y su configuración anatómica real. A diferencia del TDC, la persona no siente que la extremidad a ser amputada sea fea o defectuosa de ninguna manera, sino solo que no debería estar allí. El koro, un trastorno relacionado con la cultura que suele ocurrir en epidemias en el sudeste asiático, consiste en miedo a que el pene (labios, pezones o senos en las mujeres) se esté encogiendo o retrayendo y vaya a desaparecer en el abdomen, a menudo acompañado de la creencia de que esto llevará a la muerte. El koro difiere del trastorno dismórfico corporal en varios aspectos, incluido el enfoque en la muerte, en lugar de la preocupación por la fealdad percibida. Referencia: DSM-5-TR, Trastorno dismórfico corporal / Especificadores (p. 272); Diagnóstico diferencial (pp. 275-277).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'Una mujer de 19 años es remitida a un psiquiatra por su internista después de referir que se arranca el pelo de las cejas repetidamente hasta el punto de tener cicatrices y de quedarle poco o nada de pelo en las cejas. Dice que sus cejas naturales son "espesas" y "repulsivas" y que "parece una cavernícola". Una fotografía de antes de que comenzara a arrancarse el pelo de las cejas muestra que era una adolescente de aspecto normal. ¿Cuál es el diagnóstico más apropiado?', '["Tricotilomanía (trastorno de arrancarse el pelo).", "Trastorno delirante, tipo somático.", "Trastorno dismórfico corporal (TDC).", "Trastorno obsesivo-compulsivo (TOC)."]', 2, 'Las preocupaciones y comportamientos repetitivos del TDC difieren de las obsesiones y compulsiones del TOC en que los primeros se centran solo en la apariencia física. Otras diferencias son menor introspección, depresiones más frecuentes y tasas más altas de ideación suicida en el TDC. Cuando la eliminación del pelo (arrancarlo, tirar de él u otros tipos de eliminación) tiene la intención de mejorar defectos percibidos en la apariencia del pelo facial, de la cabeza o del cuerpo, se diagnostica un TDC en lugar de una tricotilomanía. Las ideas o delirios de referencia relacionados con la apariencia (es decir, pensar que otras personas le prestan a uno una atención especial de connotación negativa debido a la apariencia) son comunes en el TDC. Sin embargo, a diferencia de la esquizofrenia o el trastorno esquizoafectivo, el TDC implica preocupaciones destacadas por la apariencia y comportamientos repetitivos relacionados; el comportamiento desorganizado y otros síntomas psicóticos están ausentes (excepto por las creencias respecto a la apariencia, que pueden ser delirantes). El TDC difiere de las preocupaciones normales por la apariencia en que se caracteriza por preocupaciones excesivas relacionadas con el aspecto físico y comportamientos repetitivos que consumen tiempo, generalmente son difíciles de resistir o controlar y causan malestar o deterioro clínicamente significativos en el funcionamiento. Referencia: DSM-5-TR, Trastorno dismórfico corporal / Diagnóstico diferencial (pp. 275-277).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'Un hombre de 48 años acude a un psiquiatra con su esposo afirmando que este le ha presionado para que busque ayuda. Explica que le gusta coleccionar vinos y no ve que ello conlleve ningún problema; afirma que muchos de los vinos son bastante valiosos y una posible inversión. Al interrogarle más a fondo, admite que rara vez bebe los vinos porque "nunca parece ser el momento adecuado". Nunca ha vendido ni regalado ningún vino porque le resulta difícil desprenderse de las botellas. Ha llenado varias habitaciones de la casa almacenando vino, lo que, además de los problemas económicos, es lo que más preocupa al esposo. Este señala que, cuando intenta vender o deshacerse de alguno de los vinos, el paciente se echa a llorar. El paciente admite que muchas de las botellas de vino probablemente se han estropeado porque no puede permitirse almacenar el vino correctamente y las botellas llevan años en estanterías. ¿Cuál es el diagnóstico más apropiado?', '["Trastorno de la personalidad narcisista.", "Trastorno obsesivo-compulsivo (TOC).", "Trastorno delirante.", "Trastorno de acumulación, tipo de adquisición excesiva."]', 3, 'La característica esencial del trastorno de acumulación es la dificultad persistente para deshacerse o desprenderse de posesiones, independientemente de su valor real (Criterio A). El término persistente indica que se trata de una dificultad de larga duración, en lugar de circunstancias de vida más transitorias que pudieran llevar a cierto desorden excesivo, como heredar una propiedad. La dificultad para deshacerse de pertenencias que menciona el Criterio A se refiere a cualquier forma de descarte, como tirar, vender, regalar o reciclar. Las personas con trastorno de acumulación guardan intencionadamente objetos y experimentan malestar (por ejemplo, ansiedad, frustración, arrepentimiento, tristeza, culpa) cuando se enfrentan a la perspectiva de desecharlos. Estas personas acumulan un gran número de cosas que llenan y desordenan las áreas de vida activas hasta el punto de impedir su uso previsto (Criterio C). El Criterio C enfatiza las áreas de "vida activa" de la casa en lugar de otras áreas más periféricas, como garajes, áticos o sótanos, que a veces están desordenados en las casas de personas sin trastorno de acumulación. Los síntomas (es decir, la dificultad de descartar y/o el desorden) deben causar malestar o deterioro clínicamente significativos en las áreas social, laboral u otras importantes del funcionamiento, incluido el mantenimiento de un entorno seguro para uno mismo y para las demás personas (Criterio D). Aproximadamente el 80-90% de las personas con trastorno de acumulación también muestran una adquisición excesiva en la que coleccionan, compran o roban objetos que no son necesarios y para los que no hay espacio. En estos casos, esto se indica con un especificador. Aunque las personas con TOC pueden acumular objetos, normalmente experimentan malestar ante su incapacidad de desprenderse de ellos, o el almacenamiento de pertenencias sirve para algún otro propósito relacionado con sus obsesiones (por ejemplo, preocuparse de que van a tirar algo importante). Referencia: DSM-5-TR, Trastorno de acumulación / Especificadores; Características diagnósticas (p. 278).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'El diagnóstico de trastorno de acumulación puede darse aunque se sospeche que una de las siguientes opciones contribuye a su presentación. ¿Cuál?', '["Síndrome de Prader-Willi.", "Daño cerebral focal.", "Disfunción neurocognitiva.", "Historia familiar."]', 3, 'El comportamiento de acumulación es familiar, refiriendo alrededor del 50% de las personas que acumulan que tienen un familiar que también acumula. Los estudios de gemelos indican que aproximadamente el 50% de la variabilidad en el comportamiento de acumulación es atribuible a factores genéticos aditivos. El trastorno de acumulación no se diagnostica si los síntomas se consideran consecuencia directa de otra afección médica (Criterio E), como una lesión cerebral traumática, una resección quirúrgica para tratar un tumor o controlar crisis comiciales, una enfermedad cerebrovascular, infecciones del SNC (por ejemplo, encefalitis por herpes simple) o afecciones neurogenéticas como el síndrome de Prader-Willi. El daño de las cortezas prefrontal ventromedial anterior y cingulada se ha asociado particularmente a la acumulación excesiva de objetos. El trastorno de acumulación no se diagnostica si la acumulación de objetos se considera consecuencia directa de un trastorno degenerativo, como el trastorno neurocognitivo asociado a la degeneración frontotemporal o la enfermedad de Alzheimer. En tales casos, el inicio del comportamiento de acumulación es típicamente gradual y sigue al inicio del trastorno neurocognitivo. El comportamiento de acumulación puede ir acompañado de dejadez personal y suciedad doméstica marcada, junto con otros síntomas neuropsiquiátricos. Referencia: DSM-5-TR, Trastorno de acumulación / Factores de riesgo y pronóstico (p. 279); Diagnóstico diferencial (pp. 280-281).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', '¿En qué población tiene mayor prevalencia el trastorno de acumulación?', '["Hombres.", "Adolescentes.", "Adultos mayores.", "Mujeres en edad reproductiva."]', 2, 'No existen estudios de prevalencia representativos a nivel nacional para el trastorno de acumulación. Las encuestas comunitarias estiman que la prevalencia puntual de la acumulación clínicamente significativa en Estados Unidos y Europa oscila entre el 1,5 y el 6%. En un metaanálisis de 12 estudios en países de ingresos altos se encontró una prevalencia del 2,5%, sin diferencias identificadas por género. Esto contrasta con las muestras clínicas, que consisten predominantemente en mujeres. En un estudio basado en la población de los Países Bajos, los síntomas de acumulación parecían ser casi tres veces más prevalentes en los adultos mayores (mayores de 65 años) que en los adultos más jóvenes (entre 30 y 40 años). Referencia: DSM-5-TR, Trastorno de acumulación / Prevalencia (p. 279).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', '¿Cuál de las siguientes opciones sería incompatible con un diagnóstico de tricotilomanía (trastorno de arrancarse el pelo)?', '["Aceptación del comportamiento de arrancarse el pelo como normativo.", "Arrancarse el pelo de forma episódica.", "Intentos fallidos de reducir el arrancarse el pelo.", "Arrancarse el pelo en áreas cubiertas por la ropa."]', 0, 'La característica esencial de la tricotilomanía (trastorno de arrancarse el pelo) es arrancarse el propio pelo de forma recurrente (Criterio A). El arrancamiento del pelo puede afectar a cualquier región del cuerpo donde crezca pelo; los lugares más comunes son el cuero cabelludo, las cejas y las pestañas, y los lugares menos comunes son las regiones axilares, faciales, púbicas y perirrectales. Las áreas de donde se arranca el pelo pueden variar con el tiempo. El arrancamiento del pelo puede ocurrir en episodios breves repartidos a lo largo del día o durante períodos menos frecuentes, pero más sostenidos, que pueden durar horas, y tal comportamiento puede persistir durante meses o años. El Criterio A requiere que arrancarse el pelo conduzca a la pérdida de este, aunque las personas con este trastorno pueden arrancarse el pelo de manera ampliamente distribuida (es decir, arrancándose pelos individuales de toda una zona), de manera que la pérdida de pelo podría no ser claramente visible. Además, estas personas pueden intentar ocultar o camuflar la pérdida de pelo (por ejemplo, usando maquillaje, bufandas o pelucas). Las personas con tricotilomanía han hecho repetidos intentos de disminuir o detener el arrancamiento capilar (Criterio B). El Criterio C indica que esta conducta causa malestar o deterioro clínicamente significativos en las áreas social, laboral u otras importantes de funcionamiento. El término malestar incluye los afectos negativos que pueden experimentar las personas con tricotilomanía, como sentir pérdida de control, vergiienza y culpa. El deterioro significativo puede ocurrir en varias áreas diferentes del funcionamiento (por ejemplo, social, laboral, académica y de ocio), en parte debido a la evitación del trabajo, la escuela u otras situaciones públicas. Referencia: DSM-5-TR, Tricotilomanía (trastorno de arrancarse el pelo) / Características diagnósticas (pp. 281-282).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', '¿Cuál de las siguientes opciones no se asocia con la tricotilomanía (trastorno de arrancarse el pelo)?', '["Folículos pilosos rotos.", "Alopecia.", "Daño dental.", "Bezoar."]', 1, 'La mayoría de las personas con tricotilomanía admiten que se arrancan el pelo; por lo tanto, rara vez se requiere un diagnóstico dermatopatológico. La biopsia de piel y la dermoscopia (o tricoscopia) de la tricotilomanía son capaces de diferenciar el trastorno de otras causas de alopecia. En la tricotilomanía, la dermoscopia muestra una serie de características típicas, como disminución de la densidad del pelo, pelo velloso corto y pelos rotos con tallos de diferentes longitudes. La tricotilomanía se asocia a malestar, así como a deterioro social y ocupacional. Puede haber daño irreversible en el crecimiento y la calidad del pelo. Las consecuencias médicas infrecuentes de la tricotilomanía son la púrpura digital, las lesiones musculoesqueléticas (por ejemplo, síndrome del túnel carpiano; dolor de espalda, hombro y cuello), la blefaritis y el daño dental (por ejemplo, dientes desgastados o rotos como resultado de morder el pelo). La ingestión de pelo (tricofagia) puede llevar a tricobezoares, con posterior anemia, dolor abdominal, hematemesis, náuseas y vómitos, obstrucción intestinal e incluso perforación intestinal. Referencia: DSM-5-TR, Tricotilomanía (trastorno de arrancarse el pelo) / Marcadores diagnósticos; Consecuencias funcionales de la tricotilomanía (trastorno de arrancarse el pelo) (p. 283).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'Un hombre de 25 años es referido a un psiquiatra por su médico de atención primaria después de mencionarle que habitualmente pasa mucho tiempo arrancándose el vello facial con pinzas, incluso después de afeitarse cuidadosamente. En la evaluación, admite que se arranca frecuentemente el vello facial, consumiendo una cantidad significativa de tiempo; explica que se pone ansioso cuando se mira porque el bigote, la línea del cabello y las patillas son asimétricos. Se arranca los pelos para tratar de que el vello facial sea más simétrico, pero rara vez está satisfecho con los resultados. Esto le resulta muy molesto, pero no puede resistir el impulso de intentar "arreglarse" el vello facial. ¿Cuál es el diagnóstico más apropiado?', '["Tricotilomanía (trastorno de arrancarse el pelo).", "Trastorno dismórfico corporal (TDC).", "Trastorno delirante, tipo somático.", "Trastorno obsesivo-compulsivo (TOC)."]', 3, 'Las personas con TOC y preocupación por la simetría pueden arrancarse los pelos como parte de sus rituales de simetría, y las personas con TDC pueden eliminar el vello corporal que perciben como feo, asimétrico o anormal; en tales casos, no se lleva a cabo un diagnóstico de tricotilomanía. La tricotilomanía tampoco debe diagnosticarse cuando la eliminación del pelo se realiza únicamente por razones cosméticas (es decir, para mejorar la apariencia física). Muchas personas se retuercen el cabello o juegan con él, pero este comportamiento no suele calificar para el diagnóstico de tricotilomanía. Algunas personas pueden morder el pelo, en lugar de arrancárselo; de nuevo, esto no cumple los requisitos diagnósticos de la tricotilomanía. Finalmente, las personas con trastorno psicótico pueden eliminar el pelo en respuesta a un delirio o alucinación. Referencia: DSM-5-TR, Tricotilomanía (trastorno de arrancarse el pelo) / Diagnóstico diferencial (pp- 283-284).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'Una chica de 17 años es llevada a una clínica de psiquiatría infantil y adolescente para una evaluación. Sus padres informan que durante los últimos 3 años ha desarrollado un hábito cada vez peor de rascarse los antebrazos y las espinillas con las uñas. La paciente describe una sensación molesta, casi como una picazón, que se alivia al rascarse. Lo encuentra profundamente aliviante en el momento, pero se siente avergonzada por las cicatrices residuales, viste mangas largas en verano y se queda más a menudo en casa para evitar que otros vean sus lesiones. A pesar del apoyo de los padres, un consejero escolar y los amigos, el hábito ha empeorado en el último año. Las pruebas de laboratorio están todas dentro de los límites normales. ¿Cuál es el diagnóstico apropiado para esta paciente?', '["Parasitosis delirante.", "Dermatitis artefacta.", "Trastorno obsesivo-compulsivo (TOC).", "Trastorno de excoriación (rascarse la piel)."]', 3, 'La característica esencial del trastorno de excoriación (rascarse la piel) es el rascado recurrente de la propia piel (Criterio A). Las personas con trastorno de excoriación han hecho repetidos intentos de disminuir o detener el rascado de la piel (Criterio B). El Criterio C indica que el rascado de la piel causa malestar o deterioro clínicamente significativos en las áreas social, laboral u otras importantes de funcionamiento. El término malestar abarca los afectos negativos que pueden experimentar las personas con rascado de la piel, como sentir pérdida de control, vergiienza y culpa. El deterioro significativo puede ocurrir en varias áreas diferentes de funcionamiento (por ejemplo, social, laboral, académica y de ocio), en parte debido a la evitación de las situaciones sociales. El rascado de la piel puede ocurrir en respuesta a un delirio (es decir, parasitosis) o a una alucinación táctil (es decir, formicación) en el seno de un trastorno psicótico. Las compulsiones de lavado excesivo en respuesta a obsesiones de contaminación de las personas con TOC pueden llevar a lesiones en la piel, y el rascado de la piel puede ocurrir en personas con trastorno dismórfico corporal, que se rascan la piel debido a preocupaciones por su apariencia; en tales casos, no se debe diagnosticar el trastorno de excoriación. La dermatitis artefacta (también conocida como dermatitis facticia) es un término utilizado en dermatología para referirse a lesiones cutáneas médicamente inexplicadas, presumiblemente autoinducidas, que el individuo niega haber creado. Los casos en los que hay evidencia de engaño por parte del individuo en cuanto a las lesiones cutáneas pueden diagnosticarse de simulación (si el rascado de la piel está motivado por incentivos externos) o de trastorno facticio (si el rascado de la piel ocurre en ausencia de recompensas externas obvias). En ausencia de engaño se puede diagnosticar el trastorno de excoriación si hay intentos repetidos de disminuir o detener el rascado de la piel. Referencia: DSM-5-TR, Trastorno de excoriación (rascarse la piel) / Características diagnósticas (p. 285); Diagnóstico diferencial (pp. 286-287).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', '¿Cuál de las siguientes es una afección que acompaña con frecuencia al trastorno de tricotilomanía (arrancarse el pelo)?', '["Trastorno de la personalidad límite.", "Trastorno bipolar.", "Trastorno de excoriación (rascarse la piel).", "Trastorno de ansiedad generalizada."]', 2, 'La tricotilomanía a menudo va acompañada de otros trastornos mentales, más comúnmente el trastorno depresivo mayor y el trastorno de excoriación (rascado de la piel). Hay síntomas repetitivos centrados en el cuerpo, además de arrancarse el pelo o rascarse la piel (por ejemplo, morderse las uñas), que ocurren en la mayoría de las personas con tricotilomanía y pueden merecer un diagnóstico adicional de otro trastorno obsesivo-compulsivo o relacionado especificado (es decir, otro trastorno de comportamiento repetitivo centrado en el cuerpo). Referencia: DSM-5-TR, Tricotilomanía (trastorno de arrancarse el pelo) / Comorbilidad (p. 284).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'En el trastorno de excoriación (rascado de la piel), ¿cuál de las siguientes es la motivación más típica del comportamiento de rascarse la piel?', '["Inducir dolor.", "Preocupación por la simetría.", "Aburrimiento.", "Miedo a la infección."]', 2, 'El rascado de la piel puede ser desencadenado por sentimientos de ansiedad o aburrimiento; puede ir precedido de una creciente sensación de tensión (ya sea justo antes de rascarse la piel o cuando se intenta resistir el impulso de rascarse) y puede producir una sensación gratificante, de placer o de alivio a continuación. Algunas personas refieren que se rascan a causa de alguna irregularidad menor de la piel o para aliviar cierta sensación corporal incómoda. Los pacientes no siempre dicen que el rascado conlleve dolor. Algunas personas se rascan la piel de manera más consciente (es decir, notando la tensión previa y el alivio posterior), mientras que otras lo hacen de forma más automática (es decir, sin notar la tensión previa y sin plena conciencia). Otras muchas tienen una mezcla de ambos estilos de comportamiento. El rascado de la piel no suele ocurrir en presencia de otras personas, excepto los miembros de la familia inmediata. Referencia: DSM-5-TR, Trastorno de excoriación (rascado de la piel) / Características asociadas (p. 285).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'Un trabajador de una tienda, de 55 años de edad, cree que tiene "halitosis crónica" y teme que su mal aliento esté "espantando a los clientes". Está en peligro de perder su trabajo porque se ausenta con frecuencia del área de ventas para cepillarse los dientes y usar enjuague bucal. Constantemente mastica chicle de menta, aunque su jefe le ha pedido que no lo haga. Sus compañeros de trabajo siempre le aseguran que su aliento está bien, pero él está convencido de que lo dicen por cortesía. Aunque la posibilidad de perder el trabajo le preocupa, la preocupación por su aliento le resulta intolerable. Ha visto a su médico y a su dentista, ambos le dicen que está sano y no tiene mal aliento. ¿Cuál es el diagnóstico más apropiado?', '["Trastorno de ansiedad social (fobia social).", "Otro trastorno obsesivo-compulsivo o trastorno relacionado especificado.", "Trastorno dismórfico corporal.", "Trastorno de ansiedad por enfermedad."]', 1, 'El síndrome de referencia olfativa se caracteriza por la preocupación persistente del individuo al creer que emite un olor corporal fétido o desagradable que es imperceptible o solo ligeramente perceptible por los demás; en respuesta a esta preocupación, estas personas a menudo participan en comportamientos repetitivos y excesivos como comprobar repetidamente si tienen mal olor, ducharse en exceso o buscar que los consuelen, así como intentos excesivos de camuflar el olor percibido. Estos síntomas causan malestar o deterioro clínicamente significativos en el ámbito social, laboral o en otras áreas importantes del funcionamiento. En la psiquiatría japonesa tradicional, este trastorno se conoce como jikoshu-kyofu, una variante del taijin kyofusho. Referencia: DSM-5-TR, Otro trastorno obsesivo-compulsivo o trastorno relacionado especificado (pp. 293-294).'),
('DSM-5-TR', 'Trastornos obsesivo-compulsivos y trastornos relacionados', 'Una mujer de 44 años acude a urgencias con excoriaciones en ambos antebrazos. Dice que le abruma la preocupación de tener una infección de la piel, basándose en sensaciones de "picor" en los brazos, y afirma que encuentra cierto alivio en el rascado repetitivo. Está convencida de que el rascado y las excoriaciones resultantes le están ayudando a prevenir la propagación de la infección por todo el cuerpo. No quiere atención médica, pero un acompañante preocupado la llevó a urgencias al considerar que lo que pensaba era atípico y preocupante. Las pruebas de laboratorio son positivas para anfetaminas y la paciente dice que la última vez que las tomó fue aproximadamente 4 horas antes. ¿Cuál es el diagnóstico más apropiado para esta paciente?', '["Trastorno obsesivo-compulsivo o trastorno relacionado inducido por sustancias/medicamentos.", "Abstinencia de anfetaminas.", "Trastorno obsesivo-compulsivo.", "Trastorno delirante."]', 0, 'Las características esenciales del trastorno obsesivo-compulsivo y trastornos relacionados inducidos por sustancias/medicamentos son los síntomas prominentes de estos trastornos (Criterio A) que se consideran atribuibles a los efectos de una sustancia (por ejemplo, una droga de abuso, un medicamento). Los síntomas del trastorno obsesivo-compulsivo y trastornos relacionados deben haberse desarrollado durante o poco después de la intoxicación o la abstinencia de la sustancia, o después de la exposición a o la abstinencia de una medicación o una toxina, y la sustancia o medicamento debe ser capaz de producir los síntomas (Criterio B). El diagnóstico de trastorno obsesivo-compulsivo o trastorno relacionado inducido por sustancias/medicamentos solo debe hacerse en lugar del diagnóstico de intoxicación con sustancias o abstinencia de sustancias cuando los síntomas del Criterio A predominan en el cuadro clínico y son lo suficientemente graves como para requerir atención clínica independiente. Referencia: DSM-5-TR, Trastorno obsesivo-compulsivo y trastornos relacionados inducidos por sustancias / medicamentos / Características diagnósticas (p. 289).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', '¿Cómo difiere el DSM-5-TR del DSM-5 en los diagnósticos incluidos en la categoría de trastornos relacionados con traumas y factores de estrés?', '["En el DSM-5-TR, el trastorno de duelo prolongado se incluye como un diagnóstico dentro de los trastornos relacionados con traumas y factores de estrés.", "En el DSM-5-TR, el trastorno de estrés postraumático (TEPT) se ha colocado con los trastornos depresivos.", "En el DSM-5-TR, el TEPT se ha colocado en un capítulo recién creado.", "En el DSM-5-TR, el trastorno de duelo prolongado se ha colocado en \"Otras afecciones que pueden ser objeto de atención clínica\"."]', 2, 'Los trastornos relacionados con traumas y factores de estrés incluyen trastornos en los que la exposición a un evento traumático o estresante se enumera explícitamente como criterio diagnóstico. Estos incluyen el trastorno de apego reactivo, el trastorno de desinhibición social, el TEPT, el trastorno de estrés agudo, los trastornos de ajuste y el trastorno de duelo prolongado. La ubicación de este capítulo refleja la estrecha relación entre estos diagnósticos y trastornos en los capítulos circundantes sobre trastornos de ansiedad, trastornos obsesivo-compulsivos y relacionados, y trastornos disociativos. La angustia psicológica después de la exposición a un evento traumático o estresante es bastante variable. En algunos casos, los síntomas pueden entenderse bien dentro de un contexto basado en la ansiedad o el miedo. Sin embargo, está claro que muchas personas que han estado expuestas a un evento traumático o estresante exhiben un fenotipo en el que, en lugar de síntomas basados en la ansiedad o el miedo, las características clínicas más prominentes son síntomas anhedónicos y disfóricos, síntomas externos de ira y agresión, o síntomas disociativos. Debido a estas expresiones variables de angustia clínica después de la exposición a eventos catastróficos o aversivos, los trastornos mencionados se agrupan bajo una categoría separada: trastornos relacionados con traumas y factores de estrés. Referencia: DSM-5-TR, Introducción del capítulo (p. 295); Trastorno de duelo prolongado (pp. 322-327).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', '¿Qué dos trastornos relacionados con traumas y factores de estrés requieren el abandono social como criterio?', '["Trastorno de estrés postraumático y trastorno de pánico.", "Trastorno de estrés agudo y trastorno de estrés postraumático.", "Trastorno de apego reactivo y trastorno de desinhibición social.", "Trastorno de duelo prolongado y trastorno de apego reactivo."]', 2, 'El abandono social, es decir, la ausencia de cuidados adecuados durante la infancia, es un requisito diagnóstico tanto del trastorno de apego reactivo como del trastorno de desinhibición social. Aunque los dos trastornos comparten una etiología común, el primero se expresa como un trastorno de internalización con síntomas depresivos y comportamiento retraído, mientras que el segundo se caracteriza por la desinhibición y el comportamiento de externalización. Referencia: DSM-5-TR, Introducción del capítulo (p. 295).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', '¿Cuál de las siguientes afirmaciones sobre el trastorno de apego reactivo es verdadera?', '["Solo ocurre en niños que carecen de apegos saludables.", "Solo ocurre en niños que tienen apegos seguros.", "Solo ocurre en niños que tienen comunicación deteriorada.", "Ocurre en niños sin antecedentes de abandono social grave."]', 0, 'El trastorno de apego reactivo se caracteriza por un patrón de comportamientos de apego notablemente perturbados y no apropiados para el desarrollo, en el que el niño rara vez o mínimamente se vuelve preferentemente hacia una figura de apego para obtener consuelo, apoyo, protección y cuidado. La característica esencial es la ausencia o el subdesarrollo grave del apego entre el niño y los adultos supuestamente cuidadores. Se cree que los niños con trastorno de apego reactivo tienen la capacidad de formar apegos selectivos; sin embargo, debido a las oportunidades limitadas durante el desarrollo temprano, no muestran las manifestaciones conductuales de estos apegos selectivos. Referencia: DSM-5-TR, Trastorno de apego reactivo / Características diagnósticas (p. 296).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', 'Un niño de 4 años a menudo muestra miedo en la guardería que no parece estar relacionado con ninguna de sus actividades. Aunque a menudo está angustiado, no busca contacto con nadie del personal y no responde cuando un miembro del personal intenta consolarlo. ¿Qué información adicional obtenida del cuidador sobre este niño sería importante para decidir si sus síntomas representan un trastorno de apego reactivo o un trastorno del espectro autista?', '["Edad en la que apareció por primera vez el comportamiento.", "Historia familiar relativa a sus hermanos.", "Historia de retraso del lenguaje.", "Indicaciones de que ha experimentado un grave abandono social."]', 3, 'Si bien los comportamientos sociales aberrantes se manifiestan en los niños pequeños con trastorno de apego reactivo, también están entre las características clave del trastorno del espectro autista. Específicamente, los niños pequeños con cualquiera de estas entidades pueden manifestar una expresión atenuada de emociones positivas, retrasos cognitivos y del lenguaje, y déficits en la reciprocidad social. Como resultado, el trastorno de apego reactivo debe diferenciarse del trastorno del espectro autista. Estos dos trastornos se pueden distinguir según sus distintos antecedentes de abandono y la presencia de intereses restringidos o comportamientos ritualizados, déficits específicos de la comunicación social y comportamientos de apego selectivo. Los niños con trastorno de apego reactivo tienen antecedentes de grave abandono social, aunque no siempre es posible obtener historias detalladas sobre la naturaleza precisa de sus experiencias, especialmente en las evaluaciones iniciales. Los niños con trastorno del espectro autista rara vez tendrán antecedentes de abandono social. Los intereses restringidos y los comportamientos repetitivos característicos del trastorno del espectro autista no son característicos del trastorno de apego reactivo. Estas características clínicas se manifiestan como una adherencia excesiva a rituales y rutinas, intereses restringidos y fijos, y reacciones sensoriales inusuales. Referencia: DSM-5-TR, Trastorno de apego reactivo / Diagnóstico diferencial (trastorno del espectro autista) (pp. 297-298).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', '¿Cuál de las siguientes situaciones calificaría para usar el especificador grave en un niño diagnosticado de trastorno de apego reactivo?', '["El niño ha estado en cinco hogares de acogida.", "El niño nunca expresa emociones positivas al interactuar con los cuidadores.", "El trastorno ha estado presente durante 18 meses.", "El niño cumple todos los síntomas del trastorno, manifestándose cada síntoma a niveles relativamente altos."]', 3, 'El trastorno de apego reactivo se especifica como grave cuando un niño exhibe todos los síntomas del trastorno, con cada síntoma manifestándose a niveles relativamente altos. Referencia: DSM-5-TR, Trastorno de apego reactivo / Criterios diagnósticos (p. 296).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', 'Una niña de 6 años se ha acercado repetidamente a extraños mientras estaba en el parque con su clase. La maestra solicita una evaluación del comportamiento. La niña tiene un historial de haber pasado por varios hogares de acogida diferentes durante los últimos 3 años. ¿Qué diagnóstico sugiere este historial?', '["Trastorno de déficit de atención/hiperactividad (TDAH).", "Trastorno de desinhibición social.", "Trastorno del espectro autista.", "Trastorno bipolar I."]', 1, 'La característica esencial del trastorno de desinhibición social es un patrón de comportamiento que implica una conducta culturalmente inapropiada, excesivamente familiar con personas relativamente desconocidas (Criterio A). Este comportamiento debe exhibir al menos dos de los siguientes: 1) reducción o ausencia de la reticencia al acercarse a, e interactuar con, adultos desconocidos; 2) comportamiento verbal o físico excesivamente familiar (que no concuerda con los límites sociales sancionados culturalmente y apropiados para la edad); 3) disminución o ausencia de la comprobación de la presencia del cuidador adulto después de aventurarse, incluso en entornos desconocidos; o 4) disposición para irse con un adulto desconocido con mínima o ninguna vacilación. Estos comportamientos no se limitan a la impulsividad (como en el TDAH), sino que incluyen un comportamiento socialmente desinhibido (Criterio B). Referencia: DSM-5-TR, Trastorno de desinhibición social / Criterios diagnósticos (pp. 298-299).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', 'Una mujer de 25 años presenta una historia de haber sido asaltada en su camino a casa hace aproximadamente 2 meses. El atacante le dijo que tenía una pistola, que iba a violarla y que le dispararía si se resistía. La llevó hacia un callejón. Ella estaba segura de que la mataría después sin importar lo que hiciera, por lo que forcejeó para soltarse y siguió andando, consciente de que podía recibir un disparo. Logró escapar ilesa. Describe que no pudo dormir ni caminar por esa calle al día siguiente del incidente. Posteriormente, reanudó su actividad habitual con normalización del sueño y pudo caminar por esa calle sin ansiedad. Ahora, 4 meses después del incidente, dice que tiene mucha ansiedad a todas horas, a menudo llora y se siente incómoda al salir de casa, aunque puede caminar por esa calle para ir a trabajar. Niega tener flashbacks o pensamientos intrusivos sobre el incidente. ¿Cuál es el diagnóstico más probable?', '["Trastorno de estrés postraumático (TEPT).", "Trastorno de estrés agudo.", "Trastorno de adaptación.", "Amnesia disociativa."]', 2, 'El TEPT puede ocurrir a cualquier edad a partir del primer año de vida. Los síntomas generalmente comienzan dentro de los primeros 3 meses después del trauma, aunque puede haber un retraso de meses, o incluso años, antes de que se cumplan todos los criterios del diagnóstico. En los trastornos de adaptación, el estresor puede ser de cualquier intensidad o tipo en lugar de uno con exposición a la muerte, amenaza de muerte, lesiones graves o violencia sexual, como lo requiere el Criterio A del TEPT. El diagnóstico de trastorno de adaptación se usa cuando la respuesta a un estresor que cumple el Criterio A del TEPT no cumple todos los demás criterios del TEPT (o de otro trastorno mental). También se diagnostica el trastorno de adaptación cuando el patrón de síntomas del TEPT ocurre en respuesta a un estresor que no cumple el Criterio A del TEPT (por ejemplo, cónyuge que se va, ser despedido). La característica esencial del trastorno de estrés agudo es el desarrollo de síntomas característicos que duran de 3 días a 1 mes después de la exposición a uno o más sucesos traumáticos (Criterio A) del tipo que se describe en el Criterio A del TEPT. Referencia: DSM-5-TR, Trastorno de estrés postraumático / Características diagnósticas (pp. 305-308); Diagnóstico diferencial (pp. 312-313) y Desarrollo y curso (pp. 308-309); Trastorno de estrés agudo / Características diagnósticas (pp. 315-316).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', 'Después de una radiografía de tórax de rutina, a un hombre de 53 años con antecedentes de consumo intensivo de cigarrillos se le informa que tiene una lesión sospechosa en un pulmón. Una broncoscopia conduce a diagnosticar un tumor benigno que necesita extirparse. El hombre retrasa la programación de una cita de seguimiento con el cirujano durante más de 1 mes y describe la sensación de que "todo esto no es real". Está lloroso y teme que va a morir. Siente una intensa culpa de que su tabaquismo causó el tumor y expresa el pensamiento de que "merece" tener cáncer. ¿Qué diagnóstico se ajusta mejor a este cuadro clínico?', '["Trastorno de estrés agudo.", "Trastorno de estrés postraumático (TEPT).", "Trastorno de adaptación.", "Trastorno depresivo mayor."]', 2, 'La característica esencial del trastorno de estrés agudo es el desarrollo de síntomas característicos que duran de 3 días a 1 mes después de la exposición a uno o más sucesos traumáticos (Criterio A) del mismo tipo que se describe en el Criterio A del TEPT. Este criterio especifica la exposición a sucesos con muerte real, amenaza de muerte, lesiones graves o violencia sexual de una (o más) de las siguientes formas: 1) experimentar directamente el o los sucesos traumáticos; 2) ser testigo, en persona, del o los sucesos ocurridos a otros; 3) enterarse de que el o los sucesos ocurrieron a un miembro de la familia cercano o a un amigo íntimo (en caso de muerte real o amenaza de muerte de un familiar o amigo, los sucesos deben haber sido violentos o accidentales), o 4) experimentar repetida o extremadamente la exposición a detalles aversivos del o los sucesos traumáticos (por ejemplo, primeros auxilios recogiendo restos humanos, policías expuestos repetidamente a detalles de abuso infantil). En cambio, en los trastornos de adaptación, el estresor puede ser de cualquier intensidad, en lugar de ser de la intensidad y el tipo requeridos por el Criterio A del trastorno de estrés agudo. El diagnóstico de trastorno de adaptación se utiliza cuando la respuesta a un suceso del Criterio A no cumple los criterios del trastorno de estrés agudo (u otro trastorno mental específico) y cuando el patrón de síntomas del trastorno de estrés agudo ocurre en respuesta a un estresor que no cumple el Criterio A de exposición a un suceso con muerte real, amenaza de muerte, lesiones graves o violencia sexual (por ejemplo, cónyuge que se va, ser despedido). Por ejemplo, las reacciones de estrés graves a las enfermedades potencialmente mortales, que pueden incluir algunos síntomas del trastorno de estrés agudo, pueden describirse de forma más apropiada como un trastorno de adaptación. Algunas formas de respuesta al estrés agudo no incluyen los síntomas del trastorno de estrés agudo y pueden caracterizarse por ira, depresión o culpa. Estas respuestas se describen más adecuadamente como un trastorno de adaptación, principalmente. Referencia: DSM-5-TR, Trastorno de estrés agudo / Características diagnósticas (pp. 315-316); Diagnóstico diferencial (pp. 318-319).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', 'El Criterio B del trastorno de estrés agudo requiere la presencia de nueve (o más) de 12 síntomas de cualquiera de las cinco categorías de respuesta. ¿Cuál de las siguientes no es una de estas cinco categorías?', '["Intrusión.", "Disociación.", "Confusión.", "Evitación."]', 2, 'El Criterio B del trastorno de estrés agudo requiere la presencia de nueve (o más) de un total de 12 síntomas de cualquiera de las cinco categorías de intrusión, estado de ánimo negativo, disociación, evitación y excitación, que comienzan o empeoran después de suceder el o los sucesos traumáticos. Referencia: DSM-5-TR, Trastorno de estrés agudo / Criterios diagnósticos (pp. 313-315).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', '¿Cuál de las siguientes situaciones estresantes cumpliría el Criterio A del diagnóstico de trastorno de estrés agudo?', '["Descubrir que el cónyuge ha sido despedido.", "Suspender un examen final importante.", "Recibir un diagnóstico médico grave.", "Estar en medio de un tiroteo policial pero no resultar herido."]', 3, 'La característica esencial del trastorno de estrés agudo es el desarrollo de síntomas característicos que duran de 3 días a 1 mes después de la exposición a uno o más sucesos traumáticos (Criterio A) del mismo tipo que se describe en el Criterio A del trastorno de estrés postraumático. Referencia: DSM-5-TR, Trastorno de estrés agudo / Características diagnósticas (pp. 315-316).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', 'Tras el alta del hospital, un hombre de 22 años describe recuerdos vívidos e intrusivos de su estancia en la UCI. Durante la estancia en la UCI estuvo extremadamente agitado, requiriendo tratamiento con antipsicóticos durante unos días. Ahora, en casa, afirma que tiene recuerdos de personas torturadas en la UCI. Sueña con eso todas las noches, despertándose del sueño aterrorizado. Dice que no se siente él mismo después de la experiencia, que encuentra poco placer en la vida después de lo que le sucedió y que se enfada fácilmente con su familia; además, evita a su médico por miedo a que le diga que necesita volver a la UCI. ¿Cuál es la explicación más probable de los síntomas de este paciente?', '["Tiene un trastorno de estrés agudo porque su vida estuvo en peligro durante la estancia en la UCI.", "Tiene un trastorno de estrés postraumático porque su vida estuvo en peligro durante la estancia en la UCI.", "Tiene un delirio persistente desde la estancia en la UCI.", "Tuvo un delirio en la UCI y ahora tiene un trastorno de adaptación."]', 3, 'Los flashbacks en el trastorno de estrés agudo deben distinguirse de las ilusiones, alucinaciones y demás alteraciones perceptivas que pueden ocurrir en la esquizofrenia, otros trastornos psicóticos, el trastorno depresivo o bipolar con características psicóticas, el delirium, los trastornos inducidos por sustancias/medicamentos y los trastornos psicóticos debidos a otra afección médica. Los flashbacks del trastorno de estrés agudo se distinguen de estas otras alteraciones perceptivas por estar directamente relacionadas con la experiencia traumática y por ocurrir en ausencia de otras características psicóticas o inducidas por sustancias. Referencia: DSM-5-TR, Trastorno de estrés agudo / Diagnóstico diferencial (trastornos psicóticos) (p. 318).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', '¿Cuál de las siguientes experiencias no cumpliría los requisitos de una exposición a un suceso traumático (Criterio A) en el diagnóstico del trastorno de estrés agudo o trastorno de estrés postraumático?', '["Escuchar que un hermano resultó muerto en combate.", "Escuchar que un amigo íntimo de la infancia sobrevivió a un accidente de tráfico pero está paralítico.", "Escuchar que un hijo ha sido secuestrado.", "Escuchar que la empresa en que trabaja ha cerrado de repente."]', 3, 'Los sucesos traumáticos experimentados directamente en el Criterio A incluyen, entre otros, la exposición a la guerra como combatiente o civil, la amenaza de agresión o la agresión física real (por ejemplo, ataque físico, robo, atraco, maltrato físico en la infancia), la violencia sexual real o en forma de amenaza (por ejemplo, penetración sexual forzada, penetración sexual facilitada por alcohol/drogas, contacto sexual abusivo, abuso sexual sin contacto, tráfico sexual), ser secuestrado, ser tomado como rehén, un ataque terrorista, la tortura, el encarcelamiento como prisionero de guerra, los desastres naturales o provocados por el hombre y los accidentes graves de tráfico. Una enfermedad potencialmente mortal o una dolencia médica debilitante no se considera necesariamente un suceso traumático. Los incidentes médicos que se pueden calificar de sucesos traumáticos son aquellos repentinos de carácter catastrófico (por ejemplo, despertar durante una cirugía, shock anafiláctico). Los eventos presenciados incluyen, entre otros, observar amenazas o lesiones graves, una muerte antinatural, el maltrato físico o sexual de otra persona debido a una agresión violenta, la violencia doméstica, un accidente, una guerra o desastre, o una catástrofe médica en un hijo (por ejemplo, una hemorragia potencialmente mortal). La exposición indirecta a través de enterarse de un suceso se limita a aquellas experiencias que afectan a parientes cercanos o amigos y que son violentas o accidentales (por ejemplo, la muerte por causas naturales no cumple los requisitos). Tales sucesos incluyen la agresión violenta, el suicidio, un accidente grave y una lesión grave. El trastorno puede ser especialmente grave o duradero cuando el estresor es interpersonal e intencional (por ejemplo, tortura, violencia sexual). Referencia: DSM-5-TR, Trastorno de estrés postraumático / Características diagnósticas (pp. 305-308).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', 'Un hombre de 31 años escapa por poco (sin lesiones) de un incendio en su casa, que se produjo al caérsele el encendedor mientras intentaba encender su pipa de crack. Seis semanas después, mientras fuma crack, cree oler humo y sale corriendo del edificio presa del pánico, gritando: "¡Incendio!" ¿Cuál de los siguientes síntomas o circunstancias descartaría un diagnóstico de trastorno de estrés postraumático (TEPT) en este paciente?', '["Tener dificultad para conciliar el sueño.", "No estar interesado en volver al trabajo.", "Enfadarse inapropiadamente con los miembros de la familia.", "Experimentar síntomas solo cuando consume crack."]', 3, 'Aunque el estresor y los síntomas descritos calificarían a este hombre para un diagnóstico de TEPT, el Criterio G establece que "La alteración no es atribuible a los efectos fisiológicos de una sustancia (por ejemplo, medicación o alcohol) u otra afección médica". Referencia: DSM-5-TR, Trastorno de estrés postraumático / Criterios diagnósticos (pp. 301-304).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', 'El Criterio A4 del trastorno de estrés postraumático (TEPT) requiere "Experimentar una exposición repetida o extrema a detalles aversivos del suceso traumático". ¿Cuál de las siguientes situaciones no reuniría los requisitos de una experiencia de trauma bajo este criterio?', '["Un policía de homicidios revisando cintas de vídeo de vigilancia para identificar a unos perpetradores.", "Un trabajador social entrevistando a niños que han sido víctimas de abusos sexuales y obteniendo los detalles de los abusos.", "Un soldado removiendo los escombros de un edificio derrumbado para recuperar los restos de sus compañeros.", "Un estudiante universitario en un festival de cine viendo una serie de películas violentas que contienen escenas de violencia gráfica."]', 3, 'La exposición indirecta de los profesionales a los efectos grotescos de la guerra, la violación, el genocidio o la violencia abusiva infligida a otros, que ocurre en el contexto de sus deberes laborales, también puede dar lugar a un TEPT y, por lo tanto, se considera un trauma clasificatorio (Criterio A4). Son ejemplos los primeros intervinientes expuestos a lesiones graves o muertes y el personal militar que recoge restos humanos. La exposición indirecta también puede ocurrir a través de fotos, vídeos, relatos verbales o escritos (por ejemplo, policías revisando informes de delitos o realizando entrevistas a víctimas de delitos, operadores de drones, miembros de los medios de comunicación que cubren eventos traumáticos, psicoterapeutas expuestos a detalles de las experiencias traumáticas de sus pacientes). El Criterio A4 no se aplica a la exposición a través de medios electrónicos, televisión, películas o imágenes, a menos que esta exposición esté relacionada con el trabajo. Referencia: DSM-5-TR, Trastorno de estrés postraumático / Criterios diagnósticos (pp. 301-303).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', '¿Cuál de las siguientes afirmaciones es verdadera acerca del riesgo de desarrollar un trastorno de estrés postraumático (TEPT) en mujeres y hombres?', '["El riesgo es menor en las mujeres en las poblaciones de edad preescolar.", "El riesgo es mayor en las mujeres a lo largo de la vida.", "El riesgo es mayor en los hombres en las poblaciones de edad avanzada.", "El riesgo es menor en las mujeres de mediana edad que en los hombres de mediana edad."]', 1, 'El TEPT es más prevalente entre las mujeres que entre los hombres a lo largo de la vida. La prevalencia de por vida del TEPT oscila entre el 8,0 y el 11,0% en las mujeres y entre el 4,1 y el 5,4% en los hombres, según dos grandes estudios basados en la población de Estados Unidos que utilizan los criterios del D5M-5. Parte del mayor riesgo de TEPT de las mujeres parece atribuible a una mayor probabilidad de exposición al abuso sexual en la infancia, a la agresión sexual y a otras formas de violencia interpersonal, que conllevan el mayor riesgo de desarrollo del TEPT. Las mujeres de la población general también experimentan el TEPT durante un período más largo que los hombres. Sin embargo, otros factores que probablemente contribuyen a la mayor prevalencia en las mujeres son las diferencias de género en cuanto al procesamiento emocional y cognitivo del trauma, así como los efectos de las hormonas reproductivas. Cuando se comparan las respuestas de hombres y mujeres a estresores específicos, las diferencias de género en el riesgo de TEPT persisten. Por otro lado, los perfiles de síntomas del TEPT y las estructuras de factores son similares entre hombres y mujeres. Referencia: DSM-5-TR, Trastorno de estrés postraumático / Aspectos diagnósticos relacionados con el género y el sexo (p. 311).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', 'Una niña de 5 años estaba presente cuando su niñera fue agredida sexualmente. ¿Cuál de los siguientes síntomas sería más sugestivo de trastorno de estrés postraumático (TEPT) en esta niña?', '["Jugar normalmente con juguetes.", "Tener sueños sobre princesas y castillos.", "Desvestir a sus muñecas mientras juega.", "No expresar miedo al hablar sobre el evento."]', 2, 'La expresión clínica de la reexperimentación puede variar a lo largo del desarrollo. Las variaciones de la expresión clínica en función del desarrollo informan el uso de diferentes criterios en los niños de 6 años o menos y en los individuos mayores. Los niños pequeños pueden referir sueños aterradores sin contenido específico del suceso traumático. Los niños de 6 años o menos pueden desarrollar TEPT como resultado de un abuso emocional grave (por ejemplo, amenaza de abandono), que puede ser percibido como una amenaza para la vida. Durante el tratamiento de enfermedades potencialmente mortales (por ejemplo, cáncer, trasplante de órganos sólidos), la manera que tienen los niños pequeños de experimentar la gravedad e intensidad del tratamiento puede contribuir al riesgo de desarrollar síntomas de estrés postraumático; la autoevaluación de la amenaza también puede contribuir al riesgo de desarrollar síntomas de estrés postraumático en los adolescentes. Antes de los 6 años es más probable que los niños pequeños expresen síntomas de reexperimentación a través del juego, que se referirá directa o simbólicamente al trauma (véanse los criterios del TEPT para niños de 6 años o menos, DSM-5-TR pp. 303-304). Pueden no manifestar reacciones de miedo en el momento de la exposición o durante la reexperimentación. Los padres pueden informar de una amplia gama de cambios emocionales o de comportamiento en los niños pequeños. Los niños pueden centrarse en intervenciones imaginadas durante el juego o la narración de cuentos. Referencia: DSM-5-TR, Trastorno de estrés postraumático / Desarrollo y curso (pp. 308-309).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', '¿Cuál de las siguientes afirmaciones sobre los factores de riesgo de desarrollar trastorno de estrés postraumático (TEPT) es verdadera?', '["Sostener una lesión personal no afecta al riesgo de desarrollar TEPT.", "La gravedad del trauma influye en el riesgo de desarrollar TEPT.", "La disociación no tiene impacto en el riesgo de desarrollar TEPT.", "La percepción del peligro de muerte es el único factor de riesgo para desarrollar TEPT."]', 1, 'Los factores de riesgo del TEPT pueden operar de muchas maneras como, por ejemplo, predisponiendo a los individuos al trauma o a dar respuestas emocionales extremas cuando se exponen a sucesos traumáticos. Los factores de riesgo (y de protección) generalmente se dividen en pretraumáticos, peritraumáticos y postraumáticos. Factores temperamentales: los factores de alto riesgo son los problemas emocionales en la infancia (por ejemplo, problemas de externalización o ansiedad) a los 6 años y los trastornos mentales previos (por ejemplo, trastorno de pánico, trastorno depresivo, TEPT, trastorno obsesivo-compulsivo). Las diferencias individuales en términos de personalidad premórbida pueden influir en la trayectoria de la respuesta al trauma y en los resultados del tratamiento. Los rasgos de personalidad asociados a respuestas emocionales negativas como el estado de ánimo deprimido y la ansiedad representan factores de riesgo para el desarrollo del TEPT. Tales rasgos pueden captarse con las medidas de afectividad negativa (neuroticismo) de las escalas de personalidad estandarizadas. La impulsividad como rasgo premórbido tiende a asociarse a manifestaciones de externalización del TEPT y a comorbilidad del espectro de la externalización, como el trastorno por consumo de sustancias o el comportamiento agresivo. Factores ambientales: los factores de riesgo son la intensidad (dosis) del trauma, la percepción de una amenaza de muerte, la lesión personal, la violencia interpersonal (particularmente el trauma perpetrado por un cuidador o el que implica presenciar una amenaza a un cuidador en los niños) y, para el personal militar, ser un perpetrador, presenciar atrocidades o matar al enemigo. Otros factores de riesgo incluyen la disociación, el miedo, el pánico y otras respuestas peritraumáticas que ocurren durante el trauma y persisten después. Referencia: DSM-5-TR, Trastorno de estrés postraumático / Factores de riesgo y pronóstico / Factores pretraumáticos / Temperamentales; Factores peritraumáticos / Ambientales (pp. 309-310).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', 'Una mujer se queja de tener un estado de ánimo triste y de sentirse desesperanzada 3 meses después de que su marido le solicitara el divorcio. Le resulta difícil cuidar de su casa o preparar comidas para su familia, pero ha continuado cumpliendo con sus responsabilidades. Niega la ideación suicida, siente que fue una buena esposa que "no tiene nada de qué sentirse culpable" y desea poder "olvidar todo el asunto". No puede dejar de pensar en su situación. ¿Qué diagnóstico se ajusta mejor a este cuadro de síntomas?', '["Trastorno de adaptación, con estado de ánimo deprimido.", "Trastorno de adaptación, con alteración de la conducta.", "Trastorno de adaptación, con ansiedad.", "Trastorno de adaptación, con alteración mixta de las emociones y la conducta."]', 0, 'La presencia de síntomas emocionales o conductuales en respuesta a un estresor identificable es la característica esencial de los trastornos de adaptación (Criterio A). El estresor puede ser un solo suceso (por ejemplo, la terminación de una relación romántica) o puede haber múltiples estresores (por ejemplo, problemas laborales serios y problemas matrimoniales). Los estresores pueden ser recurrentes (por ejemplo, los asociados a las crisis empresariales estacionales o a las relaciones sexuales insatisfactorias) o continuos (por ejemplo, una enfermedad persistente y dolorosa con discapacidad creciente, vivir en un barrio con mucha delincuencia). Los estresores (por ejemplo, un desastre natural) pueden afectar a un solo individuo, a toda una familia o a un grupo o comunidad más grande. Algunos estresores pueden acompañar a determinados hitos del desarrollo (por ejemplo, ir a la escuela, dejar el hogar parental, regresar al hogar parental, casarse, convertirse en padre, no alcanzar las metas ocupacionales, jubilarse). Cuando el estado de ánimo bajo, el llanto o los sentimientos de desesperanza son predominantes, se debe incluir el especificador con estado de ánimo deprimido. Referencia: DSM-5-TR, Trastornos de adaptación / Criterios diagnósticos / Características diagnósticas (pp. 319-320).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', 'Doce meses después de la muerte de su marido, una mujer de 70 años es evaluada por síntomas de tristeza abrumadora, ira por la muerte inesperada de su marido debido a un ataque al corazón, anhelo intenso de que él vuelva y repetidos intentos infructuosos de comenzar a mudarse de su gran casa (que ya no puede permitirse) debido a incapacidad para ordenar y deshacerse de las pertenencias de su marido. No puede creer que él haya muerto y expresa el sentimiento de que "una parte de mí murió ese día". ¿Cuál es el diagnóstico más apropiado?', '["Trastorno depresivo mayor.", "Trastorno de estrés postraumático.", "Trastorno de adaptación, con estado de ánimo deprimido.", "Trastorno de duelo prolongado."]', 3, 'El trastorno de duelo prolongado representa una reacción de duelo desadaptativa que solo puede diagnosticarse después de que hayan transcurrido al menos 12 meses (6 meses en los niños y adolescentes) desde la muerte de alguien con quien el doliente tenía una relación cercana (Criterio A). La persistente respuesta de duelo se caracteriza por intensa añoranza o nostalgia de la persona fallecida (a menudo con intenso dolor y llanto frecuente) o la inmersión en pensamientos o recuerdos del fallecido; en niños y adolescentes, esta rumiación puede centrarse en las circunstancias de la muerte. La intensa nostalgia/añoranza o la rumiación han estado presentes la mayoría de los días en un grado clínicamente significativo y casi todos los días durante al menos el último mes (Criterio B). Además, desde la muerte, al menos tres de los siguientes síntomas han estado presentes la mayoría de los días en un grado clínicamente significativo y casi todos los días durante al menos el último mes (Criterio C): alteración de la identidad (por ejemplo, sentir como si una parte de uno mismo hubiera muerto), un marcado sentido de incredulidad acerca de la muerte, evitación de los recordatorios de que la persona está muerta, dolor emocional intenso, dificultad para reintegrarse en las relaciones personales y las actividades, entumecimiento emocional, sentir que la vida no tiene sentido como resultado de la muerte o intensa soledad como consecuencia de la muerte. Los síntomas del trastorno de duelo prolongado deben producir un malestar o un deterioro clínicamente significativos en la vida social, la ocupacional u otras áreas importantes del funcionamiento (Criterio D). La naturaleza, duración y gravedad de la reacción de duelo deben superar claramente las normas sociales, culturales o religiosas esperadas en la cultura y el contexto del individuo (Criterio E). Aunque hay variaciones en cómo puede manifestarse el duelo, los síntomas del trastorno de duelo prolongado ocurren en ambos géneros y en diversos grupos sociales y culturales. Referencia: DSM-5-TR, Trastorno de duelo prolongado / Criterios diagnósticos / Características diagnósticas (pp. 322-324).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', 'Una mujer de 25 años con asma se pone extremadamente ansiosa cuando contrae una infección respiratoria superior. Se presenta en el servicio de urgencias con quejas de no poder respirar. Mientras está allí, comienza a hiperventilar y luego dice que se siente extremadamente mareada. Su hiperventilación le hace sentir fatigada y, cuando la evaluación médica indica que está reteniendo dióxido de carbono, se hace necesario ingresarla. La mujer niega cualquier otro síntoma más allá de la ansiedad. ¿Cuál es el diagnóstico más apropiado?', '["Trastorno de estrés agudo.", "Trastorno de ansiedad generalizada.", "Trastorno de adaptación con ansiedad.", "Factores psicológicos que influyen en otras afecciones médicas."]', 3, 'Entre los factores psicológicos que influyen en otras afecciones médicas, hay determinadas entidades psicológicas (por ejemplo, síntomas psicológicos, comportamientos, otros factores) que exacerban una dolencia médica. Estos factores psicológicos pueden precipitar, exacerbar o poner a una persona en riesgo de una enfermedad médica, o pueden empeorar una afección existente. En contraste, el trastorno de adaptación es una reacción al estresor (por ejemplo, tener una enfermedad médica). La característica esencial de los factores psicológicos que influyen en otras afecciones médicas es la presencia de uno o más factores psicológicos o conductuales clínicamente significativos que afectan negativamente a una dolencia médica al aumentar el riesgo de sufrimiento, muerte o discapacidad (Criterio B). Estos factores pueden afectar negativamente a la afección médica al influir en su curso o tratamiento, al constituir un factor de riesgo de salud bien establecido adicional, o al influir en la fisiopatología subyacente para precipitar o exacerbar los síntomas o llegar a necesitar atención médica. Estos factores psicológicos o conductuales son la angustia psicológica, los patrones de interacción interpersonal, los estilos de afrontamiento y los comportamientos de salud desadaptativos, como la negación de los síntomas o el incumplimiento de las recomendaciones médicas. Ejemplos clínicos comunes son la exacerbación del asma por ansiedad, la negación de la necesidad de tratamiento para el dolor torácico agudo y la manipulación de la insulina por parte de una persona con diabetes que desea perder peso. Referencia: DSM-5-TR, Trastornos de adaptación / Diagnóstico diferencial (Factores psicológicos que influyen en otras afecciones médicas) (p. 322); Trastornos de síntomas somáticos y relacionados / Factores psicológicos que influyen en otras afecciones médicas / Características diagnósticas (p. 365).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', '¿Cuántos síntomas del Criterio B deben estar presentes para el diagnóstico del trastorno de estrés agudo?', '["Uno.", "Tres.", "Cinco.", "Nueve."]', 3, 'Para el diagnóstico se requiere la presencia de nueve (o más) síntomas de cualquiera de las cinco categorías de intrusión, estado de ánimo negativo, disociación, evitación y excitación, que comienzan o empeoran después de que ocurrieran los eventos traumáticos. Referencia: DSM-5-TR, Trastorno de estrés agudo / Criterios diagnósticos (p. 314).'),
('DSM-5-TR', 'Trastornos relacionados con traumas y factores de estrés', 'Dos meses después de la muerte de su hijo, una mujer de 49 años acude en busca de psicoterapia. Informa que su hijo murió a raíz de un accidente de esquí durante un viaje que ella le regaló por su 17 cumpleaños. Está obsesionada con la muerte y se culpa por haberle regalado el viaje, pero no siente añoranza por su hijo. Aunque niega cualquier plan suicida explícito, describe tristeza y ansiedad relacionada con su muerte. No ha entrado en la habitación de su hijo desde su muerte y tiene problemas para relacionarse con su marido, sintiendo ira hacia él por haber permitido que su hijo fuera al viaje de esquí. Fue tratada con un inhibidor selectivo de la recaptación de serotonina a dosis completa durante 3 meses después de la muerte de su hijo, pero informa que el medicamento no tuvo ningún efecto sobre sus síntomas. ¿Cuál es el diagnóstico más apropiado?', '["Trastorno depresivo mayor.", "Duelo normal.", "Trastorno de duelo prolongado.", "Trastorno de adaptación."]', 3, 'La presencia de síntomas emocionales o conductuales en respuesta a un estresor identificable es la característica principal de los trastornos adaptativos (Criterio A). El estresor puede ser un hecho único (por ejemplo, la terminación de una relación romántica) o puede haber múltiples estresores (por ejemplo, dificultades empresariales marcadas y problemas matrimoniales). Los estresores pueden ser recurrentes (por ejemplo, asociados a las crisis empresariales estacionales o las relaciones sexuales insatisfactorias) o continuos (por ejemplo, una enfermedad dolorosa persistente con discapacidad creciente; vivir en un barrio con mucha delincuencia). Los estresores (por ejemplo, un desastre natural) pueden afectar a un solo individuo, a una familia entera o a un grupo o comunidad más grande. Algunos estresores pueden acompañara hitos específicos del desarrollo (por ejemplo, ir a la escuela, dejar el hogar paterno, regresar al hogar paterno, casarse, convertirse en padre, no lograr los objetivos ocupacionales, jubilarse). Los trastornos adaptativos pueden diagnosticarse después de la muerte de un ser querido cuando la intensidad, calidad o persistencia de las reacciones de duelo exceden lo que normalmente se esperaría teniendo en cuenta las normas culturales, religiosas o apropiadas para la edad, y la reacción de duelo no cumple los criterios del trastorno de duelo prolongado. Referencia: DSM-5-TR, Trastornos de adaptación / Características diagnósticas (p. 320).'),
('DSM-5-TR', 'Trastornos disociativos', '¿Cuál de los siguientes trastornos puede ser comórbido con el trastorno de identidad disociativo?', '["Trastorno bipolar.", "Esquizofrenia.", "Trastorno de estrés postraumático (TEPT).", "Trastorno facticio."]', 2, 'Los trastornos que pueden ser comórbidos con el trastorno de identidad disociativo incluyen el TEPT (la opción C es correcta), los trastornos depresivos, los trastornos relacionados con sustancias, los trastornos alimentarios y de la ingesta, el trastorno obsesivo-compulsivo, el trastorno de la personalidad antisocial y los otros trastornos de la personalidad especificados con rasgos evitativos, obsesivo-compulsivos o límites. El trastorno de identidad disociativo se diagnostica comúnmente de forma errónea como trastorno bipolar (la opción A es incorrecta). Las personas con trastorno de identidad disociativo pueden experimentar síntomas que pueden parecer superficialmente similares a los de la esquizofrenia y otros trastornos psicóticos (la opción B es incorrecta). En el trastorno facticio, las personas que simulan un trastorno de identidad disociativo generalmente no refieren los sutiles síntomas de intrusión característicos del trastorno (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de identidad disociativo / Diagnóstico diferencial (pp. 335-337); Comorbilidad (p. 337).'),
('DSM-5-TR', 'Trastornos disociativos', '¿Cuál de los siguientes se considera un trastorno disociativo?', '["Trastorno de estrés agudo.", "Trastorno de estrés postraumático (TEPT).", "Lesión cerebral traumática.", "Trastorno de despersonalización/desrealización."]', 3, 'Los trastornos disociativos incluyen el trastorno de identidad disociativo, la amnesia disociativa, el trastorno de despersonalización/desrealización (es correcta la opción D), el otro trastorno disociativo especificado y el trastorno disociativo no especificado. Los trastornos disociativos se encuentran frecuentemente después de una amplia variedad de experiencias psicológicamente traumáticas que producen secuelas psicológicas, en contraposición al impacto físico que puede causar una lesión cerebral traumática (la opción C es incorrecta). Los trastornos disociativos se colocan junto a, pero no forman parte de, los trastornos relacionados con traumas y factores de estrés, reflejando así la estrecha relación entre estas clases diagnósticas (las opciones A y B son incorrectas). Tanto el trastorno de estrés agudo como el TEPT incluyen síntomas disociativos. Referencia: DSM-5-TR, Introducción al capítulo (pp. 329-330).'),
('DSM-5-TR', 'Trastornos disociativos', '¿Cuál de las siguientes afirmaciones describe correctamente los adjetivos positivos y negativos cuando se aplican a los síntomas disociativos?', '["Los síntomas disociativos negativos implican pérdida de continuidad en la experiencia subjetiva.", "Los síntomas disociativos positivos incluyen amnesia.", "Los síntomas disociativos negativos se refieren a la incapacidad de acceder a la información o de controlar las funciones mentales de manera normal.", "Los síntomas disociativos negativos incluyen división de la identidad."]', 2, 'Los síntomas disociativos se experimentan como intrusiones no deseadas en la conciencia y el comportamiento, con pérdidas acompañantes de continuidad en la experiencia subjetiva (es decir, síntomas disociativos positivos [la opción A es incorrecta] como la división de la identidad [la opción D es incorrecta], la despersonalización y la desrealización) y / o incapacidad para acceder a la información o controlar las funciones mentales que normalmente son fácilmente accesibles o controlables (es decir, síntomas disociativos negativos [la opción C es correcta] como la amnesia [la opción B es incorrecta]). Referencia: DSM-5-TR, Introducción al capítulo (pp. 329-330).'),
('DSM-5-TR', 'Trastornos disociativos', '¿Cuál de las siguientes es una afirmación verdadera sobre el trastorno de despersonalización/desrealización?', '["La prevalencia a 12 meses del trastorno de despersonalización/desrealización se cree que es notablemente menor que la prevalencia de los síntomas transitorios de despersonalización/desrealización.", "La edad media de inicio del trastorno de despersonalización/desrealización es de 25 años.", "Durante las experiencias de despersonalización o desrealización, los individuos normalmente pierden la capacidad de poner a prueba la realidad.", "El abuso sexual es el trauma interpersonal infantil más común en los individuos con trastorno de despersonalización/desrealización."]', 0, 'Los síntomas transitorios de despersonalización/desrealización que duran horas o días son comunes en la población general. Se cree que la prevalencia a 12 meses del trastorno de despersonalización/desrealización es notablemente menor que la prevalencia de los síntomas transitorios. La edad media de inicio del trastorno de despersonalización/desrealización es de 16 años. Menos del 20% de los individuos experimentan el inicio después de los 20 años y solo el 5% después de los 25 años (la opción B es incorrecta). Según el Criterio B, durante las experiencias de despersonalización o desrealización, la capacidad de poner a prueba la realidad permanece intacta (la opción C es incorrecta). Existe una clara asociación entre el trastorno de despersonalización/desrealización y los traumas interpersonales infantiles en una parte sustancial de los individuos. En particular, el abuso emocional y el abandono emocional han sido los más fuertemente asociados con el trastorno la mayoría de las veces. El abuso sexual es un antecedente mucho menos común, aunque también puede encontrarse (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de despersonalización / desrealización / Criterios diagnósticos (p. 343); Prevalencia (p. 344); Desarrollo y curso (pp. 344-345); Factores de riesgo y pronóstico (p. 345).'),
('DSM-5-TR', 'Trastornos disociativos', '¿Cuál de las siguientes presentaciones de síntomas es la manifestación más común del Criterio A del trastorno de identidad disociativo sin posesión?', '["Estados de personalidad elaborados con diferentes nombres, vestuarios, peinados, escrituras y acentos.", "Inhibición abrupta egosintónica del habla y la acción.", "Alteraciones del sentido del yo y la agencia que el individuo experimenta como bajo su control.", "Experiencia del yo como múltiples estados simultáneamente superpuestos e interferentes."]', 3, 'La característica definitoria del trastorno de identidad disociativo es la presencia de dos o más estados de personalidad distintos o una experiencia de posesión (Criterio A). La elaboración de estados de personalidad disociativos con diferentes nombres, vestuarios, peinados, escrituras, acentos, etc., ocurre solo en una minoría de individuos con el trastorno de identidad disociativo sin posesión y no es esencial para el diagnóstico (la opción A es incorrecta). Los pensamientos y emociones pueden desaparecer inesperadamente, y el habla y las acciones se inhiben abruptamente. Estas experiencias se informan frecuentemente como egodistónicas (la opción B es incorrecta). Las alteraciones del sentido del yo y la agencia pueden ir acompañadas de la sensación de que las actitudes, emociones y comportamientos, incluso el propio cuerpo del individuo, no son "míos" o no están "bajo mi control" (la opción C es incorrecta). En general, el individuo con trastorno de identidad disociativo se experimenta a sí mismo como múltiples estados que se superponen e interfieren simultáneamente (la opción D es correcta). Referencia: DSM-5-TR, Trastorno de identidad disociativo / Criterios diagnósticos (p. 330); Características diagnósticas (pp. 331-332).'),
('DSM-5-TR', 'Trastornos disociativos', '¿Cuál de las siguientes afirmaciones caracteriza mejor el Criterio B (amnesia disociativa) del trastorno de identidad disociativo?', '["La amnesia disociativa normalmente no es aparente para los demás.", "La minimización o racionalización de la amnesia es común.", "La amnesia se limita a sucesos estresantes o traumáticos.", "Las fugas disociativas son poco comunes."]', 1, 'La amnesia disociativa (Criterio B) se manifiesta en varios dominios principales. Las fugas disociativas, con amnesia de haber viajado, son comunes (la opción D es incorrecta). La amnesia en los individuos con trastorno de identidad disociativo no se limita a los sucesos estresantes o traumáticos (la opción C es incorrecta). La amnesia disociativa puede ser aparente para los demás (la opción A es incorrecta). La minimización o racionalización de la amnesia es común (es correcta la opción B). Referencia: DSM-5-TR, Trastorno de identidad disociativo / Características diagnósticas (pp. 331-332).'),
('DSM-5-TR', 'Trastornos disociativos', '¿Cuál de las siguientes es el tipo más común de amnesia disociativa?', '["Amnesia continua.", "Amnesia irreversible.", "Amnesia localizada o selectiva.", "Amnesia generalizada."]', 2, 'La amnesia disociativa se conceptualiza como un déficit de recuperación de la memoria potencialmente reversible (la opción B es incorrecta). De esta manera, entre otras, se diferencia de las amnesias atribuibles a daño neurobiológico o toxicidad, que perjudican el almacenamiento o la recuperación de la memoria. El Criterio A señala que la amnesia disociativa consiste más a menudo en amnesia localizada o selectiva para uno o varios sucesos específicos, o amnesia generalizada para la identidad y la historia biográfica. Más comúnmente, los individuos con amnesia disociativa refieren amnesia localizada (incapacidad para recordar sucesos durante un período de tiempo circunscrito) y / o amnesia selectiva (en la que el individuo puede recordar algunos, pero no todos, los sucesos durante un período de tiempo circunscrito) (la opción C es correcta). La amnesia disociativa generalizada implica una pérdida completa de la memoria para la mayor parte o la totalidad de la historia de vida del individuo (la opción D es incorrecta). En la amnesia continua (es decir, amnesia disociativa anterógrada), el individuo olvida los sucesos nuevos a medida que ocurren. En general, el déficit de memoria de la amnesia disociativa es retrógrado (la opción A es incorrecta). Referencia: DSM-5-TR, Amnesia disociativa / Criterios diagnósticos (p. 337); Características diagnósticas (p. 338).'),
('DSM-5-TR', 'Trastornos disociativos', '¿Cuál de las siguientes presentaciones puede especificarse usando la designación de otro trastorno disociativo especificado?', '["Síntomas característicos de un trastorno disociativo que no cumplen los criterios completos de ninguno de los trastornos de la clase diagnóstica de los trastornos disociativos.", "Síndromes crónicos y recurrentes de síntomas disociativos mixtos.", "Presentaciones para las cuales hay información insuficiente para un diagnóstico más específico.", "El clínico elige no especificar la razón por la que no se cumplen los criterios de un trastorno disociativo específico."]', 1, 'Ejemplos de presentaciones que pueden especificarse usando la designación otro especificado incluyen: 1) síndromes crónicos y recurrentes de síntomas disociativos mixtos (la opción B es correcta), 2) alteración de la identidad debido a persuasión coercitiva prolongada e intensa, 3) reacciones disociativas agudas a sucesos estresantes y 4) trance disociativo. El trastorno disociativo no especificado se aplica a las presentaciones en que los síntomas característicos de un trastorno disociativo predominan pero no cumplen los criterios completos de ninguno de los trastornos de la clase diagnóstica de los trastornos disociativos (la opción A es incorrecta). La categoría de trastorno disociativo no especificado se utiliza en aquellas situaciones en las que el clínico elige no especificar la razón por la que no se cumplen los criterios de un trastorno disociativo específico (la opción C es incorrecta) e incluye presentaciones para las cuales hay información insuficiente para el diagnóstico más específico (la opción D es incorrecta). Referencia: DSM-5-TR, Otro trastorno disociativo especificado (pp. 347-348); Trastorno disociativo no especificado (p. 348).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Los trastornos somatomorfos del DSM-IV se denominan trastornos de síntomas somáticos y trastornos relacionados en el DSM-5-TR. ¿Cuál de las siguientes características define el diagnóstico principal de esta clase, el trastorno de síntomas somáticos?', '["Ausencia de explicación médica para los síntomas somáticos.", "Presentación inicial principalmente en la atención de salud mental, en lugar de en la médica general.", "Falta de comorbilidad médica.", "Síntomas somáticos angustiantes más pensamientos, sentimientos y comportamientos anormales en respuesta a estos síntomas."]', 3, 'El trastorno de síntomas somáticos basa el diagnóstico sobre la base de los síntomas y signos positivos (síntomas somáticos angustiantes más pensamientos, sentimientos y comportamientos anormales en respuesta a estos síntomas; es correcta la opción D), en lugar de la ausencia de una explicación médica para los síntomas somáticos (la opción A es incorrecta). Todos los trastornos de síntomas somáticos se caracterizan por la atención prominente que se presta a las preocupaciones somáticas y la presentación inicial principalmente a la atención médica general en lugar de la atención de salud mental (la opción B es incorrecta). Existe una considerable comorbilidad médica entre las personas con trastornos de síntomas somáticos y trastornos relacionados (la opción C es incorrecta). Referencia: DSM-5-TR, Introducción al capítulo (pp. 349-351).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'En el DSM-IV, a un paciente con alto nivel de ansiedad por tener una enfermedad y muchos síntomas somáticos asociados se le habría dado el diagnóstico de hipocondría. ¿Qué diagnóstico del DSM-5-TR se aplicaría a este paciente?', '["Factores psicológicos que influyen en otras afecciones médicas.", "Trastorno de ansiedad por enfermedad.", "Trastorno de síntomas somáticos.", "Trastorno de síntomas neurológicos funcionales."]', 2, 'El trastorno de síntomas somáticos y el trastorno de ansiedad por enfermedad ofrecen métodos más clínicamente útiles para caracterizar a las personas que en el pasado podrían haber sido consideradas para un diagnóstico de trastorno de somatización e hipocondría. Además, aproximadamente de dos tercios a tres cuartos de las personas previamente diagnosticadas de hipocondría se incluyen bajo el diagnóstico de trastorno de síntomas somáticos (la opción C es incorrecta). Sin embargo, del cuarto a un tercio restante de las personas con diagnóstico previo de hipocondría tienen mucha ansiedad en relación con la salud en ausencia de síntomas somáticos (la opción B es incorrecta) y muchos de los síntomas de estas personas no las calificarían para un diagnóstico de trastorno de ansiedad. El diagnóstico del D5M-5 de trastorno de ansiedad por enfermedad es para este último grupo de personas (la opción B es incorrecta). Los factores psicológicos que influyen en otras afecciones médicas tienen como característica esencial la presencia de uno o más factores psicológicos o conductuales clínicamente significativos que afectan adversamente a una afección médica al aumentar el riesgo de sufrimiento, muerte o discapacidad (la opción A es incorrecta). En el trastorno de síntomas neurológicos funcionales, la clave para el diagnóstico son los síntomas neurológicos que pueden demostrarse, con hallazgos positivos en el examen clínico, y son incompatibles con la fisiopatología reconocida (la opción D es incorrecta). Referencia: DSM-5-TR, Introducción al capítulo (pp. 349-351).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'En el DSM-III y el DSM-IV se necesitaba un gran número de síntomas somáticos para merecer el diagnóstico de trastorno de somatización. ¿Cuántos síntomas somáticos se necesitan para cumplir los criterios de síntomas del diagnóstico del DSM-5-TR de trastorno de síntomas somáticos?', '["Ninguno.", "Dos o más.", "Uno.", "Cualquier número de síntomas que estén presentes continuamente."]', 2, 'El diagnóstico de trastorno de síntomas somáticos requiere uno o más síntomas somáticos que sean angustiantes o resulten en la interrupción de la vida diaria (Criterio A; la opción C es correcta y la opción A es incorrecta). Aunque un síntoma somático puede no estar continuamente presente (la opción D es incorrecta), la presencia de síntomas es persistente (típicamente por más de 6 meses) (Criterio C). La gravedad del trastorno de síntomas somáticos puede especificarse por el número de criterios B cumplidos; en el trastorno de síntomas somáticos moderado están presentes dos o más criterios B (la opción B es incorrecta). Referencia: DSM-5-TR, Trastorno de síntomas somáticos / Criterios diagnósticos (p. 351); Características diagnósticas (pp. 351-352).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Después de un vuelo en avión, una mujer de 60 años con antecedentes de ansiedad crónica desarrolla tromboflebitis venosa profunda y una posterior embolia pulmonar. Al año siguiente se centra implacablemente en las sensaciones de dolor torácico pleurítico y busca repetidamente atención médica para este síntoma, con la preocupación de que se deba a embolias pulmonares recurrentes, a pesar de los resultados negativos de las pruebas. La revisión por sistemas revela la presencia de dolor de espalda crónico y múltiples consultas previas por síntomas de cistitis, con cultivos negativos. ¿Qué diagnóstico se ajusta mejor a este cuadro clínico?', '["Trastorno de ansiedad por enfermedad.", "Trastorno de pánico.", "Trastorno de ansiedad generalizada.", "Trastorno de síntomas somáticos."]', 3, 'Las personas con trastorno de síntomas somáticos suelen tener múltiples síntomas somáticos actuales que son angustiantes u ocasionan una alteración significativa de la vida diaria. Los síntomas pueden o no estar asociados con otra afección médica. Las personas con trastorno de síntomas somáticos tienden a tener niveles muy altos de preocupación por la enfermedad. Evalúan sus síntomas corporales como excesivamente amenazantes, dañinos o problemáticos y a menudo piensan lo peor sobre su salud, incluso cuando hay evidencia de lo contrario. A menudo hay un alto nivel de utilización de la atención médica, que rara vez alivia las preocupaciones del individuo. En consecuencia, el individuo puede buscar la atención de múltiples médicos para los mismos síntomas. Si el individuo tiene preocupaciones extensas sobre la salud pero no tiene o tiene mínimos síntomas somáticos, puede ser más apropiado considerar el trastorno de ansiedad por enfermedad (la opción A es incorrecta). En el trastorno de pánico, los síntomas somáticos y la ansiedad por la salud tienden a ocurrir en episodios agudos, mientras que en el trastorno de síntomas somáticos la ansiedad y los síntomas somáticos son más persistentes (la opción B es incorrecta). Las personas con trastorno de ansiedad generalizada se preocupan por múltiples hechos, situaciones o actividades, pudiendo solo uno de ellos implicar a la salud. El foco principal no suele recaer en los síntomas somáticos o el miedo a la enfermedad, como lo hace en el trastorno de síntomas somáticos (la opción C es incorrecta). Referencia: DSM-5-TR, Trastorno de síntomas somáticos / Características diagnósticas (pp. 351-352); Características asociadas (p. 352); Diagnóstico diferencial (pp. 355-356).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'El trastorno de ansiedad por enfermedad implica preocupación por tener o contraer una enfermedad grave. ¿Cómo de graves son los síntomas somáticos que lo acompañan?', '["Moderados.", "Graves.", "No hay síntomas somáticos presentes.", "Leves."]', 3, 'El trastorno de ansiedad por enfermedad implica preocupación por tener o contraer una enfermedad médica grave y no diagnosticada (Criterio A). Los síntomas somáticos no están presentes o, si lo están, solo son de intensidad leve (la opción D es correcta; las opciones A, B y C son incorrectas). Referencia: DSM-5-TR, Trastorno de ansiedad por enfermedad / Criterios diagnósticos (p. 357).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Durante varios años, una mujer de 50 años visita la consulta de su dermatólogo cada pocas semanas para ser evaluada por cáncer de piel, mostrándole al dermatólogo varias pecas, nevus y parches de piel seca. Ninguno de los hallazgos cutáneos ha sido nunca anormal y el dermatólogo le ha proporcionado repetidas garantías. La paciente no tiene dolor, picazón, sangrado ni otros síntomas somáticos. ¿Cuál es el diagnóstico más probable?', '["Trastorno de adaptación.", "Trastorno de ansiedad por enfermedad.", "Trastorno obsesivo-compulsivo (TOC).", "Trastorno de síntomas somáticos."]', 1, 'El trastorno de ansiedad por enfermedad implica preocupación por tener o contraer una enfermedad médica grave y no diagnosticada. Los síntomas somáticos no están presentes o, si lo están, solo son de intensidad leve (la opción B es correcta). La ansiedad relacionada con la salud es una respuesta normal a una enfermedad grave, y no un trastorno mental. Esta ansiedad por la salud no patológica está claramente relacionada con la dolencia médica y suele ser limitada en el tiempo. Si la ansiedad por la salud es lo suficientemente grave como para causar malestar clínicamente significativo o deterioro en una o más áreas importantes del funcionamiento, se puede diagnosticar un trastorno de adaptación (la opción A es incorrecta). Las personas con trastorno de ansiedad por enfermedad pueden tener pensamientos intrusivos sobre tener una enfermedad y también pueden tener comportamientos compulsivos asociados (por ejemplo, buscar que las tranquilicen). Sin embargo, en el trastorno de ansiedad por enfermedad, las preocupaciones suelen estar centradas en tener una enfermedad, mientras que en el TOC los pensamientos son intrusivos y suelen centrarse en los miedos a contraer una enfermedad en el futuro (la opción C es incorrecta). Tanto el trastorno de síntomas somáticos como el trastorno de ansiedad por enfermedad pueden caracterizarse por un alto nivel de ansiedad por la salud y comportamientos relacionados con la salud excesivos. Se diferencian por el hecho de que el trastorno de síntomas somáticos requiere la presencia de síntomas somáticos que son angustiantes u ocasionan una alteración significativa de la vida diaria, mientras que en el trastorno de ansiedad por enfermedad los síntomas somáticos no están presentes o, si lo están, solo son de intensidad leve (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de ansiedad por enfermedad / Características diagnósticas (pp. 357-358); Diagnóstico diferencial (pp. 359-360).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Un hombre de 45 años con antecedentes familiares de enfermedad coronaria de inicio temprano evita subir escaleras, rechaza el ejercicio y se abstiene de actividad sexual por miedo a sufrir un ataque al corazón. Frecuentemente se toma el pulso, lee extensamente sobre cardiología preventiva y prueba muchos suplementos alimenticios que supuestamente son buenos para el corazón. Cuando a veces nota algún dolor en el pecho, descansa en la cama durante 24 horas; sin embargo, no acude a los médicos por miedo a escuchar malas noticias. ¿Qué diagnóstico se ajusta mejor a este cuadro clínico?', '["Trastorno de ansiedad generalizada.", "Trastorno depresivo mayor.", "Trastorno de ansiedad por enfermedad.", "Otra afección médica."]', 2, 'En una minoría de casos de trastorno de ansiedad por enfermedad, los individuos están demasiado ansiosos como para buscar atención médica y evitan la atención sanitaria. La ansiedad conduce a la evitación desadaptativa de las situaciones (por ejemplo, visitar a familiares enfermos) o actividades (por ejemplo, el ejercicio) que estos individuos temen que pueden poner en peligro su salud (la opción C es correcta). La primera consideración diagnóstica diferencial es una afección médica subyacente. La presencia de una dolencia médica no descarta la posibilidad de un trastorno de ansiedad por enfermedad coexistente (la opción D es incorrecta). Si existe una afección médica, la ansiedad relacionada con la salud y las preocupaciones por la enfermedad son claramente desproporcionadas a su gravedad. En el trastorno de ansiedad generalizada, los individuos se preocupan por múltiples hechos, situaciones o actividades, pudiendo solo uno de ellos implicar a la salud (la opción A es incorrecta). En el trastorno de ansiedad por enfermedad, la ansiedad por la salud y los miedos son más persistentes y duraderos. Algunas personas con episodio depresivo mayor rumian sobre su salud y se preocupan excesivamente por la enfermedad. No se hace un diagnóstico separado de trastorno de ansiedad por enfermedad si estas preocupaciones ocurren solo durante los episodios depresivos mayores (la opción B es incorrecta). Si la preocupación excesiva por la enfermedad persiste después de la remisión de un episodio de trastorno depresivo mayor, se debe considerar el diagnóstico de trastorno de ansiedad por enfermedad. Referencia: DSM-5-TR, Trastorno de ansiedad por enfermedad / Características diagnósticas (pp. 357-358); Características asociadas (p. 358); Diagnóstico diferencial (pp. 359-360).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Una mujer de 25 años es hospitalizada para evaluar episodios presenciados que incluyen pérdida de conciencia, balanceo de la cabeza de un lado a otro y movimientos de pedaleo no sincronizados de brazos y piernas. Según el informe de la familia, los episodios ocurren varias veces al día y duran de 2 a 5 minutos. La electroencefalografía durante los episodios no revela ninguna actividad ictal. Inmediatamente después de una convulsión, el sensorio parece claro. ¿Cuál es el diagnóstico más probable?', '["Trastorno facticio.", "Simulación.", "Trastorno de síntomas somáticos.", "Trastorno de conversión (trastorno de síntomas neurológicos funcionales), con ataques o crisis comiciales."]', 3, 'Los criterios diagnósticos del trastorno de síntomas neurológicos funcionales incluyen uno o más síntomas de alteración de la función motora voluntaria o sensorial que causan angustia o deterioro clínicamente significativos en las áreas sociales, ocupacionales u otras áreas importantes del funcionamiento, o que justifican la atención médica. Estos síntomas son incompatibles con las afecciones neurológicas o médicas reconocidas y no pueden ser mejor explicados por otro trastorno mental. Los episodios de aparente falta de respuesta, con o sin movimientos de las extremidades, pueden parecerse a las convulsiones epilépticas, el síncope o el coma. El diagnóstico se basa en los hallazgos clínicos, que muestran evidencia clara de incompatibilidad con la patología neurológica reconocida (la opción D es correcta). El trastorno de síntomas neurológicos funcionales describe síntomas genuinamente experimentados que no son producidos intencionalmente (es decir, no son fingidos). Sin embargo, la evidencia definitiva de simulación (por ejemplo, una marcada discrepancia entre las actividades diarias reportadas y las observadas) sugeriría este trastorno si el objetivo aparente del individuo es obtener una recompensa externa obvia (la opción B es incorrecta) o un trastorno facticio en ausencia de tal recompensa (la opción A es incorrecta). El trastorno de síntomas neurológicos funcionales puede diagnosticarse además del trastorno de síntomas somáticos. La mayoría de los síntomas somáticos encontrados en el trastorno de síntomas somáticos no puede demostrarse que sean claramente incompatibles con la patología neurológica o médica reconocida, mientras que en el trastorno de síntomas neurológicos funcionales dicha incompatibilidad es requisito del diagnóstico. Referencia: DSM-5-TR, Trastorno de síntomas neurológicos funcionales (trastorno de conversión) / Criterios diagnósticos (pp. 360-361); Características diagnósticas (pp. 361-362); Diagnóstico diferencial (pp. 363-364).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', '¿Cuál de las siguientes presentaciones es más sugerente de un diagnóstico de trastorno de conversión (trastorno de síntomas neurológicos funcionales)?', '["Ausencia del signo de Hoover.", "Movimientos distónicos crónicos.", "Visión en túnel.", "Temblor con dirección y frecuencia compatibles."]', 2, 'Un campo visual tubular (es decir, la visión en túnel) con pruebas indicativas de incongruencia interna con la agudeza visual sugiere la presencia de síntomas visuales funcionales (la opción C es correcta). Ejemplos de hallazgos de la exploración que indican incompatibilidad con la patología neurológica reconocida son el signo de Hoover, en el que la debilidad de la extensión de la cadera vuelve a su fuerza normal con la flexión contralateral de la cadera contra resistencia (la opción A es incorrecta), o la incapacidad de copiar movimientos rítmicos simples debido al temblor funcional (la opción D es incorrecta). En la distonía funcional, los individuos suelen presentar un inicio súbito (la opción B es incorrecta). Referencia: DSM-5-TR, Trastorno de síntomas neurológicos funcionales (trastorno de conversión) / Características diagnósticas (pp. 361-362).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', '¿Por qué la belle indifférence (aparente falta de preocupación por el síntoma) no está se incluye como criterio diagnóstico del trastorno de conversión (trastorno de síntomas neurológicos funcionales)?', '["A menudo se asocia con síntomas disociativos.", "Tiene baja especificidad.", "Puede estar ausente en hasta el 50% de los individuos.", "Solo está presente al inicio del síntoma o durante los ataques."]', 1, 'Varias características asociadas pueden respaldar el diagnóstico del trastorno de síntomas neurológicos funcionales, aunque ninguna es específica. El fenómeno de la belle indifférence (es decir, la aparente falta de preocupación por la naturaleza o las implicaciones del síntoma) se ha asociado con el trastorno de síntomas neurológicos funcionales pero no es específico, por lo que no debe usarse para hacer el diagnóstico (la opción B es correcta). Aunque la evaluación del estrés y el trauma es importante, la belle indifférence puede estar ausente en hasta el 50% de los individuos (la opción C es incorrecta). El trastorno de síntomas neurológicos funcionales a menudo se asocia con síntomas disociativos (la opción A es incorrecta), particularmente al inicio del síntoma o durante los ataques (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de síntomas neurológicos funcionales (trastorno de conversión) / Características asociadas (p. 362).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Un hombre de 20 años se presenta quejándose de disminución de la agudeza visual en el ojo izquierdo en poco tiempo. Los exámenes físicos, neurológicos y de laboratorio son completamente normales, incluidas las pruebas de estereopsis, la prueba del empañamiento y la resonancia magnética cerebral. El resto de la historia es negativa excepto por la atención perseverante del paciente hacia la asimetría facial, con planes de someterse pronto a una cirugía plástica. ¿Cuál de los siguientes diagnósticos se sugiere?', '["Trastorno de síntomas somáticos y trastorno de pánico.", "Trastorno facticio y simulación.", "Trastorno dismórfico corporal y trastorno de conversión (trastorno de síntomas neurológicos funcionales).", "Trastorno depresivo."]', 2, 'La mayoría de los síntomas somáticos encontrados en el trastorno de síntomas somáticos no puede demostrarse que sean claramente incompatibles con la patología neurológica o médica reconocida, mientras que en el trastorno de síntomas neurológicos funcionales dicha incompatibilidad es necesaria para el diagnóstico (la opción A es incorrecta y la opción C es correcta). Las personas con trastorno dismórfico corporal están excesivamente preocupadas por un defecto percibido en su apariencia física (la opción C es correcta). El trastorno de síntomas neurológicos funcionales describe síntomas genuinamente experimentados que no son producidos intencionalmente (es decir, no son fingidos). Sin embargo, la evidencia (por ejemplo, una marcada discrepancia entre las actividades diarias reportadas y las observadas) sugeriría una simulación si el objetivo aparente del individuo es obtener una recompensa externa obvia, o un trastorno facticio en ausencia de tal recompensa (la opción B es incorrecta). En los trastornos depresivos, los individuos pueden informar de pesadez general de las extremidades, mientras que la debilidad del trastorno de síntomas neurológicos funcionales es más focal y prominente. Los trastornos depresivos también se diferencian por la presencia de síntomas depresivos centrales (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de síntomas neurológicos funcionales (trastorno de conversión) / Diagnóstico diferencial (pp. 363-364).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Un hombre de 50 años con hipertensión difícil de controlar admite "tomarse un descanso" periódicamente de los medicamentos porque lo criaron con la creencia de que las pastillas son malas y los remedios naturales son mejores, aunque es muy consciente de que su presión arterial puede volverse peligrosamente alta cuando no está tomando sus medicamentos. ¿Qué diagnóstico se ajusta mejor a este caso?', '["Trastorno de síntomas somáticos.", "Trastorno de ansiedad por enfermedad.", "Trastorno de adaptación.", "Factores psicológicos que influyen en otras afecciones médicas."]', 3, 'El diagnóstico de factores psicológicos que influyen en otras afecciones médicas se aplica cuando existe un síntoma o una afección médica (distinta de un trastorno mental) (Criterio A) y hay factores psicológicos o de comportamiento que afectan negativamente a dicha afección médica (Criterio B). Los factores psicológicos o de comportamiento afectan negativamente a la dolencia médica de una de las siguientes maneras: 1) existe una estrecha asociación temporal entre los factores psicológicos y el desarrollo, la exacerbación o la recuperación tardía de la afección médica; 2) los factores interfieren en el tratamiento de la afección médica (por ejemplo, mala adherencia); 3) los factores constituyen riesgos de salud adicionales bien establecidos para el individuo, o 4) los factores influyen en la fisiopatología subyacente, precipitando o exacerbando síntomas o haciendo necesaria la atención médica (la opción D es correcta). El trastorno de síntomas somáticos se caracteriza por una combinación de síntomas somáticos angustiantes y de pensamientos, sentimientos y comportamientos excesivos o desadaptativos en respuesta a estos síntomas o preocupaciones por la salud asociadas. El individuo puede o no tener una afección médica diagnosticable. En cambio, en los factores psicológicos que influyen en otras afecciones médicas los factores psicológicos afectan negativamente a una enfermedad; los pensamientos, sentimientos y comportamientos del individuo no son necesariamente excesivos (la opción A es incorrecta). El trastorno de ansiedad por enfermedad se caracteriza por mucha ansiedad ante la enfermedad, que es angustiante y/o disruptiva para la vida diaria, con síntomas somáticos mínimos. En los factores psicológicos que influyen en otras afecciones médicas, la ansiedad puede ser un factor psicológico relevante que afecte a una enfermedad, pero la preocupación clínica son los efectos adversos producidos sobre la afección médica (la opción B es incorrecta). Los síntomas psicológicos o de comportamiento anormales que se desarrollan en respuesta a una dolencia médica se codifican más adecuadamente como trastorno de adaptación (una respuesta psicológica clínicamente significativa a un factor estresante identificable); la opción C es incorrecta. Referencia: DSM-5-TR, Factores psicológicos que influyen en otras afecciones médicas / Criterios diagnósticos (pp. 364-365); Diagnóstico diferencial (pp. 366-367).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Un hombre de 60 años con cáncer de próstata tiene metástasis óseas que le causan dolor persistente. Está siendo tratado con medicamentos antiandrogénicos que causan sofocos. Aunque (según su propia evaluación) su dolor está bien controlado con analgésicos, afirma que no puede trabajar debido a sus síntomas. A pesar de la seguridad de que sus medicamentos están controlando la enfermedad metastásica, cada episodio de dolor le lleva a preocuparse de tener nuevas lesiones óseas y estar a punto de morir, y continuamente expresa temores sobre su muerte inminente a su esposa e hijos. ¿Qué diagnóstico se ajusta mejor a la presentación de este paciente?', '["Trastorno de pánico.", "Trastorno de ansiedad por enfermedad.", "Trastorno de síntomas somáticos.", "Factores psicológicos que influyen en otras afecciones médicas."]', 2, 'El diagnóstico de trastorno de síntomas somáticos requiere síntomas somáticos angustiantes o perjudiciales que pueden o no estar asociados a otra afección médica pero deben ir acompañados de pensamientos, sentimientos o comportamientos excesivos o desproporcionados relacionados con los síntomas somáticos, o de preocupaciones por la salud asociadas (la opción C es correcta). En cambio, el diagnóstico de factores psicológicos que influyen en otras afecciones médicas requiere la presencia de una dolencia médica, así como de factores psicológicos que afecten negativamente a su curso o interfieran en su tratamiento (la opción D es incorrecta). En el trastorno de pánico, los síntomas somáticos y la ansiedad por la salud tienden a ocurrir en episodios agudos, mientras que en el trastorno de síntomas somáticos la ansiedad y los síntomas somáticos son más persistentes (la opción A es incorrecta). Si el individuo tiene amplias preocupaciones sobre la salud pero presenta mínimos o nulos síntomas somáticos, puede ser más apropiado considerar el trastorno de ansiedad por enfermedad (la opción B es incorrecta). Referencia: DSM-5-TR, Trastorno de síntomas somáticos / Diagnóstico diferencial (pp. 355-356).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', '¿Cuál es la característica diagnóstica esencial del trastorno facticio?', '["Motivación para asumir el papel de enfermo.", "Falsificación de signos y síntomas médicos o psicológicos.", "Recompensas externas obvias.", "Ausencia de una afección médica preexistente."]', 1, 'La característica esencial del trastorno facticio es la falsificación de signos y síntomas médicos o psicológicos en el individuo o en otros relacionados con la falsificación identificada (la opción B es correcta). El diagnóstico de trastorno facticio enfatiza la identificación objetiva de la falsificación de signos y síntomas de enfermedad, y no las motivaciones individuales del falsificador (la opción A es incorrecta). El diagnóstico requiere demostrar que el individuo está realizando acciones subrepticias para tergiversar, simular o causar signos o síntomas de enfermedad o lesión incluso en ausencia de recompensas externas obvias (la opción C es incorrecta). Aunque puede haber una afección médica preexistente, el comportamiento engañoso o la inducción de lesiones asociadas al engaño hace que otros vean a estos individuos como más enfermos o discapacitados, lo que puede llevar a una intervención clínica excesiva (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno facticio / Características diagnósticas (p. 368).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Cuando una madre refiere de manera consciente y engañosa signos y síntomas de enfermedad en su hijo de edad preescolar, lo que lleva a la hospitalización del niño y a que lo sometan a numerosas pruebas y procedimientos, ¿qué diagnóstico se debe aplicar al niño?', '["Engaño para evitar responsabilidad legal.", "Déficits educativos o discapacidades.", "No se le hace ningún diagnóstico al niño.", "Trastorno facticio impuesto a otro."]', 2, 'Cuando un individuo falsifica una enfermedad en otro (por ejemplo, niños, adultos, mascotas), el diagnóstico es de trastorno facticio impuesto a otro. El perpetrador, no la víctima, recibe el diagnóstico (la opción C es correcta y la opción D es incorrecta). Las personas con trastorno facticio impuesto a otro a veces alegan falsamente la presencia de déficits educativos o discapacidades en sus hijos para exigir una atención especial, a menudo con considerable incomodidad para los docentes (la opción B es incorrecta). Los cuidadores que mienten sobre lesiones por maltrato en dependientes, únicamente para protegerse de la responsabilidad, no se diagnostican de trastorno facticio impuesto a otro porque la protección de la responsabilidad es una recompensa externa (la opción A es incorrecta). Referencia: DSM-5-TR, Trastorno facticio / Procedimientos de registro (p. 368); Características asociadas (p. 368); Diagnóstico diferencial (pp. 369-370).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Una mujer de 25 años con antecedentes de abuso de heroína intravenosa es admitida en el hospital con endocarditis infecciosa. Los cultivos de sangre son positivos para varias especies de hongos. La inspección de las pertenencias de la paciente revela jeringas y agujas ocultas, y una pequeña bolsa de tierra que, cuando se cultiva, produce las mismas especies de hongos. ¿Cuál de los siguientes diagnósticos se aplicaría?', '["Trastorno por consumo de opioides y trastorno de la personalidad límite.", "Trastorno por consumo de opioides y simulación.", "Trastorno por consumo de opioides y trastorno facticio.", "Simulación y trastorno de la personalidad límite."]', 2, 'La característica esencial del trastorno facticio es la falsificación de signos y síntomas médicos o psicológicos en el propio individuo o en otros relacionados con el engaño identificado. El diagnóstico requiere demostrar que el individuo lleva a cabo acciones subrepticias para tergiversar, simular o causar signos o síntomas de enfermedad o lesión incluso en ausencia de recompensas externas obvias. Los individuos con trastorno facticio pueden, por ejemplo, autolesionarse físicamente o inducirse una enfermedad o inducirla a otros (por ejemplo, inyectándose material fecal para producir un absceso o para inducir sepsis; la opción C es correcta). La simulación se diferencia del trastorno facticio por referir intencionadamente síntomas para obtener un beneficio personal (por ejemplo, dinero, tiempo libre del trabajo). Por el contrario, el diagnóstico de trastorno facticio requiere que la falsificación de la enfermedad no se explique completamente por recompensas externas (las opciones B y D son incorrectas). La autolesión física deliberada en ausencia de intención suicida también puede ocurrir en asociación con otros trastornos mentales, como el trastorno de la personalidad límite. El trastorno facticio requiere que la inducción de la lesión ocurra en asociación con el engaño (las opciones A y D son incorrectas). Referencia: DSM-5-TR, Trastorno facticio / Características diagnósticas (p. 368); Diagnóstico diferencial (pp. 369-370).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Después de encontrarse un bulto en el pecho, una mujer de 50 años con antecedentes familiares de cáncer de mama se siente abrumada por sentimientos de ansiedad. La consulta a un cirujano de mama, la mamografía y la biopsia muestran que el bulto es benigno. El cirujano le dice que no requiere tratamiento; sin embargo, ella sigue rumiando la posibilidad de que sea cáncer y sobre la cirugía, de la que saldrá desfigurada. Duerme inquieta y tiene problemas para concentrarse en el trabajo. Después de 6 semanas con estos síntomas, su médico de cabecera la deriva a una consulta psiquiátrica. Su historial médico y psiquiátrico es, por lo demás, negativo. ¿Qué diagnóstico se ajusta mejor a esta presentación?', '["Trastorno de síntomas somáticos.", "Trastorno de ansiedad por enfermedad.", "Trastorno de síntomas somáticos o relacionado no especificado.", "Otro trastorno de síntomas somáticos o relacionado especificado."]', 3, 'La categoría de otro trastorno de síntomas somáticos o relacionado especificado se aplica a las presentaciones en las que predominan síntomas característicos de un trastorno de síntomas somáticos o relacionado que causan malestar o deterioro clínicamente significativos en las áreas sociales, ocupacionales u otras áreas importantes del funcionamiento, pero sin cumplir los criterios completos de ninguno de los trastornos de la clase diagnóstica de los trastornos de síntomas somáticos y relacionados. Ejemplos serían un trastorno de síntomas somáticos breve o un trastorno de ansiedad por enfermedad breve con una duración de los síntomas inferior a 6 meses (la opción D es correcta). El Criterio C del trastorno de síntomas somáticos especifica que el estado sintomático es persistente (generalmente más de 6 meses) (la opción A es incorrecta). El Criterio E del trastorno de ansiedad por enfermedad especifica que la preocupación por la enfermedad ha estado presente durante al menos 6 meses (la opción B es incorrecta). La categoría de trastorno de síntomas somáticos o relacionado no especificado se aplica a las presentaciones en las que predominan síntomas característicos de un trastorno de síntomas somáticos o relacionado que causan malestar o deterioro clínicamente significativos en las áreas sociales, ocupacionales u otras áreas importantes del funcionamiento, pero sin cumplir los criterios completos de ninguno de los trastornos de la clase diagnóstica. La categoría de trastorno de síntomas somáticos o relacionado no especificado no debe usarse a menos que se produzcan situaciones decididamente inusuales en las que no haya suficiente información para hacer un diagnóstico más específico (la opción C es incorrecta). Referencia: DSM-5-TR, Otro trastorno de síntomas somáticos o relacionado especificado (p. 370).'),
('DSM-5-TR', 'Trastorno de síntomas somáticos y trastornos relacionados', 'Después de encontrarse un bulto en el pecho, una mujer de 53 años con antecedentes familiares de cáncer de mama se siente abrumada por sentimientos de ansiedad. La consulta a un cirujano de mama, la mamografía y la biopsia muestran que el bulto es benigno. El cirujano indica que no requiere tratamiento; sin embargo, ella sigue rumiando la posibilidad de que sea cáncer y sobre la cirugía, de la que saldrá desfigurada. Duerme inquieta y tiene problemas para concentrarse en el trabajo. Después de 6 semanas en este estado, su médico de cabecera le recomienda que consulte a un psiquiatra. En la evaluación inicial, la paciente llora durante toda la entrevista y está tan angustiada que el evaluador no puede obtener detalles de su historial médico y psiquiátrico más allá de revisar la "crisis" actual. ¿Qué diagnóstico se ajusta mejor a esta presentación?', '["Trastorno de síntomas somáticos.", "Trastorno de ansiedad por enfermedad.", "Trastorno de síntomas somáticos o relacionado no especificado.", "Otro trastorno de síntomas somáticos o relacionado especificado."]', 2, 'La categoría de trastorno de síntomas somáticos o relacionado no especificado se aplica a las presentaciones en las que predominan síntomas característicos de los trastornos de síntomas somáticos y trastornos relacionados que causan malestar o deterioro clínicamente significativos en las áreas sociales, ocupacionales u otras áreas importantes del funcionamiento, pero sin cumplir los criterios completos de ninguno de los trastornos de esta clase diagnóstica de los trastornos de síntomas somáticos y relacionados. La categoría de trastorno de síntomas somáticos o relacionado no especificado no debe usarse a menos que se produzcan situaciones decididamente inusuales en las que no haya suficiente información para realizar un diagnóstico más específico (la opción C es correcta). El Criterio C del trastorno de síntomas somáticos especifica que el estado sintomático es persistente (generalmente más de 6 meses); la opción A es incorrecta. El Criterio E del trastorno de ansiedad por enfermedad especifica que la preocupación por la enfermedad ha estado presente durante al menos 6 meses (la opción B es incorrecta). La categoría otro trastorno de síntomas somáticos o relacionado especificado se aplica a las presentaciones en las que predominan síntomas característicos de un trastorno de síntomas somáticos o relacionado que causan malestar o deterioro clínicamente significativos en las áreas sociales, ocupacionales u otras áreas importantes del funcionamiento, pero sin cumplir los criterios completos de ninguno de los trastornos de la clase diagnóstica (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de síntomas somáticos o relacionado no especificado (p. 370).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', 'Una mujer de 27 años embarazada, en su primer trimestre, acude a su cita de obstetricia y ginecología acompañada de su pareja. Esta informa al médico que la paciente ha estado comiendo objetos extraños, como trozos de papel y tela, durante los últimos 2 meses. La paciente admite este comportamiento, señalando que la perturba. Está molesta por haber perdido peso y niega cualquier deseo de hacerlo. ¿Cuál es el diagnóstico más apropiado?', '["Anorexia nerviosa.", "Trastorno de la conducta alimentaria y de la ingesta de alimentos no especificado.", "Pica.", "Trastorno facticio."]', 2, 'La característica esencial de la pica es la ingestión de una o más sustancias no nutritivas, no alimenticias, de manera persistente durante un período de al menos 1 mes (Criterio A), lo suficientemente grave como para requerir atención clínica. El término no alimenticio se incluye porque el diagnóstico de pica no se aplica a la ingestión de productos dietéticos de contenido nutricional mínimo. Normalmente no hay aversión a la comida en general. La ingestión de sustancias no nutritivas, no alimenticias, debe ser inadecuada para el desarrollo (Criterio B) y debe no formar parte de una práctica culturalmente aceptada o socialmente normativa (Criterio C). La pica se puede distinguir generalmente de los otros trastornos de la conducta alimentaria y de la ingesta de alimentos por el consumo de sustancias no nutritivas, no alimenticias. Sin embargo, es importante señalar que algunas presentaciones de anorexia nerviosa incluyen la ingestión de sustancias no nutritivas y no alimenticias, como pañuelos de papel, como forma de intentar controlar el apetito. En estos casos, cuando la ingestión de sustancias no nutritivas y no alimenticias se utiliza principalmente como medio de control del peso, la anorexia nerviosa debe ser el diagnóstico principal. Algunas personas con trastorno facticio pueden ingerir intencionalmente objetos extraños como parte del patrón de falsificación de síntomas físicos. En tales casos, hay un elemento de engaño que concuerda con la inducción deliberada de lesiones o enfermedades. Referencia: DSM-5-TR, Pica / Características diagnósticas (p. 372); Diagnóstico diferencial (p. 373).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', '¿Cuál de los siguientes es un diagnóstico comórbido común con el trastorno de rumiación?', '["Anorexia nerviosa.", "Discapacidad intelectual.", "Bulimia nerviosa.", "Trastorno de evitación/restricción de la ingesta de alimentos."]', 1, 'La característica esencial del trastorno de rumiación es la regurgitación repetida de alimentos que ocurre después de la alimentación o la ingesta durante un período de al menos 1 mes (Criterio A). Los alimentos previamente ingeridos, que pueden estar parcialmente digeridos, se traen a la boca sin náuseas aparentes, arcadas involuntarias o asco. La comida puede ser remasticada y luego expulsada de la boca o reingerida. La regurgitación en el trastorno de rumiación debe ser frecuente, ocurriendo al menos varias veces por semana, típicamente a diario. El comportamiento no se explica mejor por una afección gastrointestinal o médica asociada (por ejemplo, reflujo gastroesofágico, estenosis pilórica) (Criterio B) y no ocurre exclusivamente durante el curso de la anorexia nerviosa, la bulimia nerviosa, el trastorno de atracones o el trastorno de evitación/restricción de la ingesta de alimentos (Criterio C). Si los síntomas ocurren en el contexto de otro trastorno mental (por ejemplo, trastorno del desarrollo intelectual [discapacidad intelectual]), deben ser lo suficientemente graves como para requerir atención clínica adicional (Criterio D) y representar un aspecto principal de la presentación del individuo que requiera intervención. El trastorno puede diagnosticarse a lo largo de toda la vida, particularmente en los individuos que también tienen un trastorno del desarrollo intelectual. Referencia: DSM-5-TR, Trastorno de rumiación / Características diagnósticas (p. 374).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', '¿Cuál de las siguientes opciones distingue la anorexia nerviosa de la bulimia nerviosa?', '["Atracones.", "Miedo intenso a ganar peso.", "Peso corporal anormalmente bajo.", "Comportamientos compensatorios."]', 2, 'Las personas con bulimia nerviosa presentan episodios recurrentes de atracones, realizan comportamientos inapropiados para evitar el aumento de peso (por ejemplo, vómitos autoinducidos) y están excesivamente preocupadas por la forma y el peso de su cuerpo. Sin embargo, a diferencia de las personas con anorexia nerviosa, tipo con atracones/purgas, las personas con bulimia nerviosa mantienen un peso corporal en o por encima de un nivel mínimamente normal. Referencia: DSM-5-TR, Anorexia nerviosa / Diagnóstico diferencial (p. 387).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', '¿Cuál de las siguientes opciones distingue el trastorno de atracones de la bulimia nerviosa?', '["Comportamientos compensatorios.", "Frecuencia de los atracones.", "Cantidad de comida en los atracones.", "Dieta frecuente."]', 0, 'El trastorno de atracones tiene en común con la bulimia nerviosa los atracones recurrentes, pero se diferencia de esta última en algunos aspectos fundamentales. En términos de presentación clínica, el comportamiento compensatorio inapropiado recurrente (por ejemplo, purgas, ejercicio compulsivo) que se ve en la bulimia nerviosa está ausente en el trastorno de atracones. A diferencia de las personas con bulimia nerviosa, las personas con trastorno de atracones normalmente no muestran una restricción dietética marcada o sostenida, diseñada para influir en el peso y la forma del cuerpo, entre los episodios de atracones; sin embargo, pueden informar de frecuentes intentos de hacer dieta. Referencia: DSM-5-TR, Trastorno de atracones / Diagnóstico diferencial (p. 395).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', 'Según los criterios del DSM-5-TR, ¿cuál de las siguientes opciones impide el diagnóstico de trastorno de evitación/restricción de la ingesta de alimentos (TERIA)?', '["Un diagnóstico de anorexia nerviosa en la vida.", "Pérdida de peso significativa.", "Dependencia de la alimentación enteral.", "Imagen corporal distorsionada."]', 3, 'El TERIA reemplaza y amplía el diagnóstico del DSM-IV de trastorno de la alimentación de la infancia o la primera infancia para incluir a niños mayores, adolescentes y adultos. La característica principal del trastorno de evitación/restricción de la ingesta de alimentos es la evitación o restricción de la ingesta de alimentos que se asocia a una o más de las siguientes consecuencias: pérdida de peso significativa, deficiencia nutricional significativa (o impacto relacionado con la salud), dependencia de la alimentación enteral o suplementos nutricionales orales, o interferencia marcada en el funcionamiento psicosocial (Criterio A). El TERIA no incluye la evitación o restricción de la ingesta de alimentos relacionada con la falta de disponibilidad de alimentos (por ejemplo, inseguridad alimentaria) o con prácticas culturales (por ejemplo, ayuno religioso, dieta normal) (Criterio B). La perturbación no se explica mejor por una preocupación excesiva por el peso o la forma del cuerpo (Criterio C), ni por factores médicos concurrentes o trastornos mentales (Criterio D). Aunque el TERIA no debe ocurrir exclusivamente durante el curso de la bulimia o la anorexia nerviosa (Criterio C), esos diagnósticos no impiden diagnosticar un TERIA si es lo apropiado. Referencia: DSM-5-TR, Trastorno de evitación / restricción de la ingesta de alimentos / Características diagnósticas (pp. 376-377).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', '¿Qué patrón específico del trastorno de evitación/restricción de la ingesta de alimentos (TERIA) es más probable que aparezca durante la infancia?', '["TERIA basado en las características de los alimentos.", "TERIA relacionado con experiencias aversivas.", "TERIA con falta de interés por la comida.", "TERIA que afecta al funcionamiento social."]', 2, 'La evitación o restricción de la comida asociada a una ingesta insuficiente o falta de interés por comer se desarrolla más comúnmente en la infancia o la primera infancia y puede persistir en la edad adulta. Del mismo modo, la evitación basada en las características sensoriales de los alimentos tiende a surgir en la primera década de la vida, pero puede persistir en la edad adulta. La evitación relacionada con las consecuencias aversivas puede surgir a cualquier edad. La escasa literatura médica sobre los resultados a largo plazo sugiere que la evitación o restricción de alimentos basada en los aspectos sensoriales es relativamente estable y prolongada, pero cuando persiste en la edad adulta, dicha evitación/restricción puede acompañarse de un funcionamiento relativamente normal. Referencia: DSM-5-TR, Trastorno de evitación / restricción de la ingesta de alimentos / Desarrollo y curso (pp. 377-378).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', 'Una mujer de 45 años tuvo un episodio de asfixia hace 3 años después de comer ensalada. Desde ese momento ha tenido miedo de comer una amplia gama de alimentos, temiendo atragantarse. Este miedo ha afectado a su funcionalidad y a su capacidad de ir a restaurantes con amigos, y ha contribuido a su pérdida de peso. ¿Qué diagnóstico se ajusta mejor a este cuadro clínico?', '["Anorexia nerviosa.", "Trastorno de evitación/restricción de la ingesta de alimentos.", "Fobia específica.", "Trastorno de adaptación."]', 1, 'La evitación o restricción de la comida también puede representar una respuesta negativa condicionada, asociada a la ingesta de alimentos después, o en previsión de, una experiencia aversiva como la asfixia, una exploración traumática, generalmente del tracto gastrointestinal (por ejemplo, una esofagoscopia), o vómitos repetidos. Los términos disfagia funcional y globo histérico también se han utilizado para tales afecciones. La restricción de la ingesta de energía, en relación con los requerimientos, que conduce a un peso corporal significativamente bajo es una característica central de la anorexia nerviosa. Sin embargo, las personas con anorexia nerviosa también muestran miedo a ganar peso o a engordar, o un comportamiento persistente que interfiere en el aumento de peso, así como perturbaciones específicas de la percepción y la experiencia de su propio peso y forma corporal. Estas características no están presentes en el trastorno de evitación/restricción de la ingesta de alimentos. La fobia específica, otro tipo, incluye como ejemplo "situaciones que pueden llevar a la asfixia o al vómito", que pueden representar el desencadenante principal del miedo, la ansiedad o la evitación requeridos para el diagnóstico. Distinguir la fobia específica del trastorno de evitación/restricción de la ingesta de alimentos puede ser difícil cuando el miedo a la asfixia o al vómito conduce a la evitación de los alimentos. Aunque la evitación o restricción de la ingesta de alimentos secundaria a un miedo pronunciado a la asfixia o al vómito puede conceptualizarse como fobia específica, en las situaciones en que el problema de la alimentación se convierte en el foco principal de la atención clínica, el trastorno de evitación/restricción de la ingesta de alimentos es el diagnóstico apropiado. Referencia: DSM-5-TR, Trastorno de evitación / restricción de la ingesta de alimentos / Características diagnósticas (pp. 376-377); Diagnóstico diferencial (pp. 379-380).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', '¿Cuáles son los dos subtipos de anorexia nerviosa?', '["Tipo restrictivo y tipo con atracones/purgas.", "Tipo de ahorro de energía y tipo con atracones/purgas.", "Tipo de bajo contenido calórico/bajo en carbohidratos y tipo restrictivo.", "Tipo restrictivo y tipo de bajo peso."]', 0, 'Los especificadores de subtipo describen el principal modo de pérdida de peso utilizado durante los últimos 3 meses. En el subtipo restrictivo de la anorexia nerviosa, la pérdida de peso se logra principalmente a través de la dieta, el ayuno y/o el ejercicio excesivo; en el subtipo con atracones/purgas se logra a través de episodios recurrentes de atracones o conductas purgativas (es decir, vómitos autoinducidos o uso indebido de laxantes, diuréticos o enemas). La mayoría de las personas con el tipo de atracones/purgas de la anorexia nerviosa se dan atracones y se purgan mediante vómitos autoinducidos o el uso indebido de laxantes, diuréticos o enemas. Algunas personas con este subtipo de anorexia nerviosa no presentan atracones, pero sí se purgan regularmente después de ingerir pequeñas cantidades de alimentos. No es raro que se produzca un cruce entre los subtipos a lo largo del curso del trastorno; por lo tanto, la descripción del subtipo debe usarse para describir los síntomas actuales en lugar del curso longitudinal. Referencia: DSM-5-TR, Anorexia nerviosa / Criterios diagnósticos (p. 381); Subtipos (p. 382).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', '¿Cuál de las siguientes opciones es necesaria para el diagnóstico de anorexia nerviosa?', '["Incapacidad de ganar peso a pesar de una ingesta normal.", "Perturbación social, ocupacional o funcional.", "Comportamientos purgativos compensatorios.", "Imagen corporal distorsionada."]', 3, 'Hay tres características esenciales de la anorexia nerviosa: restricción persistente de la ingesta de energía, miedo intenso a ganar peso o a engordar o comportamiento persistente que interfiere en el aumento de peso, y alteración de la percepción del peso o la forma corporal. El individuo mantiene un peso corporal que está por debajo del nivel mínimamente normal para la edad, el sexo, la trayectoria del desarrollo y la salud física (Criterio A). El peso corporal de los individuos a menudo cumple este criterio después de una pérdida de peso significativa pero, entre los niños y adolescentes, puede haber alternativamente ausencia del aumento de peso esperado o incapacidad de mantener una trayectoria de desarrollo normal (es decir, mientras crecen en altura) en lugar de la pérdida de peso. La experiencia y la importancia del peso y la forma corporal están distorsionadas en estos individuos (Criterio C). Algunos individuos se perciben globalmente con sobrepeso. Otros se dan cuenta de que están delgados pero aun así les preocupa que ciertas partes del cuerpo, particularmente el abdomen, los glúteos y los muslos, estén "demasiado gordos". Pueden emplear varias técnicas para evaluar el tamaño corporal o el peso, como pesarse con frecuencia, medir obsesivamente las partes del cuerpo y mirarse persistentemente al espejo para comprobar las áreas de grasa que perciben. Referencia: DSM-5-TR, Anorexia nerviosa / Características diagnósticas (pp. 382-383).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', '¿Cuál de las siguientes anomalías de laboratorio se encuentra comúnmente en las personas con anorexia nerviosa?', '["Tiroxina (T4) elevada.", "Nitrógeno ureico en sangre (BUN) elevado.", "Densidad ósea elevada.", "Fosfato elevado."]', 1, 'La presencia de ciertas anomalías de laboratorio puede servir para aumentar la confianza en el diagnóstico. Las siguientes anomalías pueden observarse en la anorexia nerviosa: la leucopenia es común, con pérdida de todos los tipos de células pero, en general, con aparente linfocitosis; puede haber anemia leve, así como trombocitopenia y, rara vez, problemas de sangrado. La deshidratación puede reflejarse en un nivel elevado de BUN; la hipercolesterolemia es frecuente; los niveles de enzimas hepáticas pueden estar elevados; en ocasiones se observan hipomagnesemia, hipozinquemia, hipofosfatemia e hiperamilasemia. Los vómitos autoinducidos pueden producir alcalosis metabólica (bicarbonato sérico elevado), hipocloremia e hipopotasemia; el abuso de laxantes puede causar una leve acidosis metabólica; los niveles de T4 en el suero suelen estar en el rango normal bajo; los niveles de triyodotironina (T3) están disminuidos, mientras que los niveles de T3 inversa están elevados. Las mujeres tienen niveles bajos de estrógenos en el suero, mientras que los hombres tienen niveles séricos bajos de testosterona. La bradicardia sinusal es común y rara vez se observan arritmias. Se observa una prolongación significativa del intervalo QTc en algunas personas. La baja densidad mineral ósea, con áreas específicas de osteopenia u osteoporosis, se ve a menudo. El riesgo de fracturas está significativamente elevado. Electroencefalografía: Puede haber anomalías difusas que reflejen una encefalopatía metabólica debido a alteraciones hidroelectrolíticas significativas. A menudo hay una reducción significativa del gasto energético en reposo. Referencia: DSM-5-TR, Anorexia nerviosa / Marcadores diagnósticos (p. 385).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', '¿Cuál de los siguientes diagnósticos concurre habitualmente con la anorexia nerviosa?', '["Trastorno de depresión mayor.", "Trastorno de la personalidad narcisista.", "Esquizofrenia.", "Discapacidad intelectual."]', 0, 'Los trastornos bipolares, depresivos y de ansiedad suelen coexistir con la anorexia nerviosa. Muchos individuos con anorexia nerviosa informan de la presencia de un trastorno de ansiedad o de síntomas de ansiedad antes de iniciarse el trastorno alimentario. El trastorno obsesivo-compulsivo se describe en algunos individuos con anorexia nerviosa, especialmente en aquellos con el tipo restrictivo. El trastorno por consumo de alcohol y otros trastornos por consumo de sustancias también pueden acompañar a la anorexia nerviosa, especialmente entre los individuos con el tipo de atracones/purgas. Referencia: DSM-5-TR, Anorexia nerviosa / Comorbilidad (p. 387).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', '¿En qué período de desarrollo comienza más comúnmente la bulimia nerviosa?', '["Edad adulta media.", "Primera infancia.", "Adolescencia.", "Se distribuye por igual a lo largo del ciclo de vida."]', 2, 'La bulimia nerviosa comienza comúnmente en la adolescencia o la juventud. Es poco común que comience antes de la pubertad o después de los 40 años. La ingesta compulsiva a menudo comienza durante o algo después de un episodio de dieta para perder peso. Experimentar múltiples sucesos estresantes en la vida también puede precipitar el inicio de la bulimia nerviosa. El comportamiento alimentario perturbado persiste durante al menos varios años en un alto porcentaje en las muestras clínicas. El curso puede ser crónico o intermitente, con períodos de remisión que alternan con recaídas en la ingesta compulsiva. Sin embargo, a largo plazo los síntomas de muchas personas parecen disminuir con o sin tratamiento, aunque el tratamiento afecta claramente al resultado. Los períodos de remisión de más de 1 año se asocian a mejores resultados a largo plazo. Referencia: DSM-5-TR, Bulimia nerviosa / Desarrollo y curso (p. 390).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', '¿Cuál de los siguientes es un diagnóstico comórbido común en los pacientes con bulimia nerviosa?', '["Trastorno por consumo de estimulantes.", "Trastorno de la personalidad antisocial.", "Trastorno de la personalidad evitativa.", "Trastorno de atracones."]', 0, 'La comorbilidad con otros trastornos mentales es común en los individuos con bulimia nerviosa, experimentando la mayoría al menos un trastorno mental adicional y muchos de ellos múltiples comorbilidades. La comorbilidad no se limita a ningún subconjunto en particular, sino que implica una amplia gama de trastornos mentales. Hay una mayor frecuencia de síntomas depresivos (por ejemplo, baja autoestima) y de trastornos bipolares y depresivos (particularmente trastornos depresivos) en los individuos con bulimia nerviosa. En muchos individuos, la alteración del estado de ánimo comienza al mismo tiempo o algo después del desarrollo de la bulimia nerviosa y los individuos a menudo atribuyen sus alteraciones del ánimo a la bulimia nerviosa. Sin embargo, en algunos individuos la alteración del estado de ánimo precede claramente al desarrollo de la bulimia nerviosa. También puede haber una mayor frecuencia de síntomas de ansiedad (por ejemplo, miedo a las situaciones sociales) o de trastornos de ansiedad. Estas alteraciones del estado de ánimo y de ansiedad a menudo remiten después de un tratamiento efectivo de la bulimia nerviosa. La prevalencia de por vida del trastorno por consumo de sustancias, particularmente del trastorno por consumo de alcohol o del trastorno por consumo de estimulantes, es de al menos el 30% entre los individuos con bulimia nerviosa. El uso de estimulantes a menudo comienza con el fin de controlar el apetito y el peso. Un porcentaje sustancial de individuos con bulimia nerviosa también tienen características de personalidad que cumplen los criterios de uno o más trastornos de la personalidad, siendo el más frecuente el trastorno de la personalidad límite. Referencia: DSM-5-TR, Bulimia nerviosa / Comorbilidad (p. 392).'),
('DSM-5-TR', 'Trastornos de la conducta alimentaria y de la ingesta de alimentos', 'Para cumplir los criterios diagnósticos del trastorno de atracones, ¿cuál de las siguientes características describe con precisión un episodio de atracón?', '["Es independiente del contexto cultural.", "Puede durar hasta 6 horas.", "Ocurre al menos una vez a la semana durante 3 meses.", "Puede consistir en picar continuamente."]', 2, 'La característica esencial del trastorno de atracones es la recurrencia de episodios de atracones que deben ocurrir, de media, al menos una vez por semana durante 3 meses (Criterio D). El episodio de atracón se define como la ingestión, durante un período de tiempo discreto, de una cantidad de comida definitivamente mayor de la que comería la mayoría de la gente en un período de tiempo similar en circunstancias similares (Criterio A1). El contexto en el que se produce la ingesta puede afectar a la estimación de si la ingesta es excesiva por el clínico. Por ejemplo, una cantidad de alimentos que se pudiera considerar excesiva para una comida típica podría considerarse normal durante una celebración o una comida festiva. El período de tiempo discreto se refiere a un período limitado, generalmente inferior a las 2 horas. Un solo episodio de atracón no necesita limitarse a un solo lugar. Por ejemplo, un individuo puede comenzar el atracón en un restaurante y luego continuar comiendo al regresar a casa. El picoteo continuo de pequeñas cantidades de comida a lo largo del día no se consideraría un atracón. Referencia: DSM-5-TR, Trastorno de atracones / Características diagnósticas (pp. 393-394).'),
('DSM-5-TR', 'Trastornos de la excreción', 'Un niño de 7 años con retraso del desarrollo moderado presenta antecedentes crónicos de mojar la ropa durante el día, aproximadamente una vez por semana, incluso en la escuela. Ahora se niega a ir al colegio por miedo a mojar los pantalones y a que se rían de él sus compañeros de clase. ¿Cuál de las siguientes afirmaciones describe con precisión las opciones de diagnóstico de la enuresis en este caso?', '["No debería ser diagnosticado de enuresis porque la frecuencia es menor de dos veces por semana.", "Debería ser diagnosticado de enuresis porque la incontinencia produce deterioro funcional del rol apropiado para su edad.", "No debería ser diagnosticado de enuresis porque su edad mental probablemente sea menor de 5 años.", "Debería ser diagnosticado de enuresis, subtipo diurno únicamente."]', 2, 'El Criterio C requiere que el individuo sea de una edad en la que se pueda esperar razonablemente una continencia constante. Aunque esto normalmente ocurre a los 5 años, en el caso del retraso del desarrollo se considera la edad mental del niño. En este caso, es probable que el niño aún no haya alcanzado una edad mental de 5 años y no sea elegible para el diagnóstico, aunque tiene un malestar clínicamente significativo. El Criterio B requiere que la incontinencia sea clínicamente significativa, y esta condición puede cumplirse con el requisito de frecuencia/duración de dos veces a la semana durante 3 meses o por el hecho de que le causa un sufrimiento clínicamente significativo. En este caso se cumple la última condición (porque el niño tiene un sufrimiento clínicamente significativo), por lo que se cumple el Criterio B y no habría motivo para no hacer el diagnóstico. Aunque el público en general puede pensar que la nocturnidad de la incontinencia es un aspecto esencial, la enuresis puede presentarse como, y puede especificarse como, solo nocturna, solo diurna o nocturna y diurna (es decir, presentación combinada). Referencia: DSM-5-TR, Enuresis / Criterios diagnósticos (p. 399).'),
('DSM-5-TR', 'Trastornos de la excreción', '¿Qué es más común en los niños con enuresis?', '["Alta autoestima.", "Estar socialmente oprimido.", "Persistencia de la incontinencia urinaria en la edad adulta.", "Mayor edad."]', 1, 'Los niños y los miembros de grupos socialmente oprimidos pueden tener una mayor prevalencia de enuresis, como se ha encontrado en los niños afroamericanos en Estados Unidos y los niños turcos o marroquíes en los Países Bajos. La prevalencia de la enuresis nocturna en la comunidad disminuye con la edad; en varios entornos geográficos, incluidos Estados Unidos, Países Bajos y Hong Kong, el rango es de alrededor del 5-10% entre los niños de 5 años, del 3-5% entre los niños de 10 años y de alrededor del 1% entre las personas de 15 años o más. El grado de deterioro asociado a la enuresis está en función de la limitación de las actividades sociales del niño (por ejemplo, no poder ir de campamento o dormir fuera) o de su efecto sobre su autoestima, del grado de ostracismo social por parte de sus compañeros y de la ira, el castigo y el rechazo por parte de los cuidadores. La enuresis diurna es poco común después de los 9 años. Cuando la enuresis persiste hasta la adolescencia o la adultez, la incontinencia puede resolverse, pero la frecuencia urinaria generalmente persiste y la incontinencia puede reaparecer más tarde en la adultez en las mujeres. Referencia: DSM-5-TR, Enuresis / Prevalencia; Desarrollo y curso (pp. 400-401).'),
('DSM-5-TR', 'Trastornos de la excreción', '¿Qué se asocia con el subtipo de enuresis solo diurno?', '["Sexo masculino.", "Edad > 9 años.", "Enuresis monosintomática.", "Postergación de la micción, en la que la micción se pospone conscientemente debido a la renuencia social a usar el baño o a interrumpir una actividad de juego."]', 3, 'El subtipo de enuresis solo nocturna a veces se conoce como enuresis monosintomática. El subtipo de enuresis solo diurna cursa con incontinencia solo durante el día y también se conoce como incontinencia urinaria. Es más común en las mujeres y es poco común después de los 9 años. En la enuresis diurna, el niño pospone la micción hasta que ocurre la incontinencia, a veces debido a no querer usar el inodoro por ansiedad social o alguna preocupación con la escuela o la actividad de juego. El evento enurético ocurre más comúnmente a primera hora de la tarde en los días escolares y puede estar asociado a síntomas de comportamiento disruptivo. Referencia: DSM-5-TR, Enuresis / Características asociadas; Desarrollo y curso; Aspectos diagnósticos relacionados con el sexo y el género (pp. 400-401).'),
('DSM-5-TR', 'Trastornos de la excreción', '¿Cuál de las siguientes afirmaciones identifica correctamente una de las distinciones entre la enuresis primaria y la enuresis secundaria?', '["Los niños con enuresis secundaria tienen tasas más altas de comorbilidad psiquiátrica que los niños con enuresis primaria.", "La enuresis primaria tiene un inicio típico a los 10 años, mucho más tarde que el inicio de la enuresis secundaria.", "La enuresis primaria nunca va precedida de un período de continencia, mientras que la enuresis secundaria siempre va precedida de un período de continencia.", "A diferencia de la enuresis primaria, la enuresis secundaria tiende a persistir hasta la adolescencia tardía."]', 2, 'En la enuresis primaria, el individuo nunca ha alcanzado la continencia urinaria; en la enuresis secundaria, la incontinencia aparece después de un período de continencia estable. Por definición, la incontinencia primaria comienza cuando el niño alcanza la edad mental de 5 años. Antes de esto no se espera una continencia constante y la incontinencia de orina no se considera patológica. Después de los 5 años, el niño ha alcanzado la continencia y la ha perdido o nunca la ha desarrollado, en cuyo caso se debe considerar que el inicio es a los 5 años, independientemente de la edad de presentación. La incontinencia urinaria secundaria a otra afección médica no se diagnostica como enuresis porque el Criterio D lo excluye. La enuresis secundaria no se asocia con tasas más altas de comorbilidad psiquiátrica y ambas formas tienden a desaparecer en la adolescencia tardía (cuando las tasas de prevalencia se acercan al 1%). Referencia: DSM-5-TR, Enuresis / Desarrollo y curso (p. 400).'),
('DSM-5-TR', 'Trastornos de la excreción', '¿Cuál de las siguientes afirmaciones describe correctamente los factores relacionados con la etiología y/o el inicio de la enuresis?', '["Se ha demostrado que la enuresis es heredable, siendo al menos dos veces más probable que un niño tenga este diagnóstico si alguno de los padres lo ha tenido.", "El modo de entrenamiento para ir al baño o su negligencia puede afectar a las tasas de enuresis, como lo demuestran las altas tasas observadas en los orfanatos.", "En las niñas con enuresis, la enuresis nocturna es la forma más común.", "Las tasas de enuresis son mucho más altas en los países europeos que en los países en desarrollo."]', 1, 'La enuresis tiene orígenes etiológicos tanto en la genética como en los comportamientos aprendidos. Hay tasas muy altas de enuresis en los orfanatos y otras instituciones residenciales, probablemente relacionadas con el modo y el entorno en que se realiza el entrenamiento para ir al baño. La heredabilidad se ha demostrado en análisis de familias, gemelos y segregación. El riesgo relativo de tener un hijo que desarrolle enuresis es mayor para los padres anteriormente enuréticos (odds ratio de 10,1) que para las madres anteriormente enuréticas (odds ratio de 3,6). La enuresis nocturna es más común en los varones; la incontinencia diurna es más común en las mujeres. La enuresis se ha observado en diversos países europeos, africanos y asiáticos, así como en Estados Unidos. A nivel nacional, las tasas de prevalencia son notablemente similares y hay una gran similitud entre las trayectorias de desarrollo encontradas en los diferentes países. Referencia: DSM-5-TR, Enuresis / Factores de riesgo y pronóstico; Aspectos diagnósticos relacionados con la cultura; Aspectos diagnósticos relacionados con el sexo y el género (p. 401).'),
('DSM-5-TR', 'Trastornos de la excreción', 'Un niño de 4 años con retraso del desarrollo moderado presenta una historia de pasar accidentalmente heces a su ropa interior durante el día, aproximadamente una vez cada 2 semanas, incluso en la escuela. Ahora se niega a ir al colegio por miedo a ensuciar sus pantalones y ser ridiculizado por sus compañeros de clase. ¿Cuál de las siguientes afirmaciones describe con precisión las opciones de diagnóstico de la encopresis en este caso?', '["El diagnóstico de encopresis es incorrecto porque la frecuencia es menor de dos veces por semana.", "El diagnóstico de encopresis es incorrecto porque la incontinencia es involuntaria.", "El diagnóstico de encopresis es incorrecto porque la edad mental del paciente probablemente sea menor de 4 años.", "El diagnóstico de encopresis es correcto."]', 2, 'El Criterio C requiere que el individuo tenga una edad en la que se pueda esperar razonablemente una continencia constante. Aunque esto normalmente ocurre a los 4 años, en el caso de un retraso del desarrollo se considera la edad mental del niño. En este caso, es probable que el niño aún no haya alcanzado una edad mental de 4 años y no sea elegible para el diagnóstico aunque tenga un malestar clínicamente significativo. El Criterio B requiere que la incontinencia sea clínicamente significativa, y esta condición puede cumplirse con el requisito de frecuencia/duración de una vez al mes durante 3 meses. En este caso, el niño tiene suficiente frecuencia, por lo que se cumple el Criterio B y no habría motivo para no hacer el diagnóstico. La defecación puede ser voluntaria o involuntaria según el Criterio A. Referencia: DSM-5-TR, Encopresis / Criterios diagnósticos (p. 402).'),
('DSM-5-TR', 'Trastornos de la excreción', '¿Cuál de las siguientes afirmaciones sobre la encopresis es verdadera?', '["Cuando está presente el trastorno negativista desafiante o el trastorno de la conducta, no se puede diagnosticar la encopresis.", "Cuando está presente el estreñimiento, no se puede diagnosticar la encopresis.", "Las infecciones del tracto urinario pueden ser comórbidas con la encopresis.", "Aunque resulta embarazosa, la encopresis no tiene ningún efecto en la autoestima de los niños."]', 2, 'Las infecciones del tracto urinario son más comunes en los niños con encopresis. Los niños con encopresis a menudo presentan problemas significativos de autoestima. Cuando la defecación es involuntaria en lugar de intencional, a menudo está relacionada con el estreñimiento, la impactación y la retención con desbordamiento posterior. El untado de heces puede ser deliberado o accidental, debiéndose a que el niño trata de limpiar o esconder las heces que se pasaron involuntariamente. Cuando la incontinencia es claramente deliberada, también pueden estar presentes características del trastorno negativista desafiante o del trastorno de la conducta. Referencia: DSM-5-TR, Encopresis / Características diagnósticas y características asociadas (p. 403).'),
('DSM-5-TR', 'Trastornos de la excreción', '¿Cuál de las siguientes afirmaciones sobre el especificador de encopresis con estreñimiento e incontinencia por desbordamiento es precisa?', '["La encopresis con estreñimiento e incontinencia por desbordamiento a menudo es involuntaria.", "La encopresis con estreñimiento e incontinencia por desbordamiento generalmente cursa con heces bien formadas.", "No se puede diagnosticar la encopresis con estreñimiento e incontinencia por desbordamiento si el comportamiento se debe a una evitación psicológicamente motivada de la defecación.", "La encopresis con estreñimiento e incontinencia por desbordamiento rara vez se resuelve después del tratamiento del estreñimiento."]', 0, 'Cuando la defecación es involuntaria en lugar de intencional, a menudo está relacionada con el estreñimiento, la impactación y la retención con desbordamiento posterior. El estreñimiento puede desarrollarse por razones psicológicas (por ejemplo, ansiedad por defecar en un lugar particular o un patrón más general de comportamiento ansioso o negativista), lo que lleva a evitar la defecación. Las heces del subtipo con estreñimiento e incontinencia por desbordamiento están característicamente (pero no invariablemente) mal formadas y la fuga puede ser de infrecuente a continua, ocurriendo principalmente durante el día y raramente durante el sueño. Solo una parte de las heces se pasa durante el uso del inodoro y la incontinencia se resuelve después del tratamiento del estreñimiento. En el subtipo sin estreñimiento e incontinencia por desbordamiento, es probable que las heces sean de forma y consistencia normales, y el ensuciamiento es intermitente. Las heces pueden depositarse en un lugar prominente. Esto generalmente se asocia con la presencia del trastorno negativista desafiante o el trastorno de la conducta, o puede ser consecuencia de la masturbación anal. El manchado sin estreñimiento parece ser menos común que el manchado con estreñimiento. Referencia: DSM-5-TR, Encopresis / Subtipos; Características diagnósticas; Características asociadas (pp. 402-403).'),
('DSM-5-TR', 'Trastornos de la excreción', 'Cuando la enuresis persiste hasta la adolescencia o la adolescencia tardía, la incontinencia puede resolverse. ¿Qué más se sabe sobre la enuresis en esta población?', '["La frecuencia urinaria generalmente persiste con el tiempo.", "La forma diurna es más probable que persista hasta la adolescencia.", "Es muy poco probable que la incontinencia reaparezca más tarde en la edad adulta en las mujeres.", "Los problemas cognitivos y de comportamiento son menos probables."]', 0, 'Aunque la incontinencia diurna ocasional no es poco común en la infancia media, es sustancialmente más común en aquellos que también tienen otros problemas de salud mental coexistentes, incluidos los problemas cognitivos y de comportamiento. Cuando la enuresis persiste hasta la infancia tardía o la adolescencia, la incontinencia puede resolverse, pero la frecuencia urinaria generalmente persiste y la incontinencia puede reaparecer más tarde en la edad adulta en las mujeres. La enuresis diurna es poco común después de los 9 años. Referencia: DSM-5-TR, Enuresis / Desarrollo y curso (p. 400).'),
('DSM-5-TR', 'Trastornos de la excreción', '¿Cuáles son las comorbilidades asociadas con la enuresis nocturna?', '["Infecciones gastrointestinales.", "Síndrome de piernas inquietas.", "Depresión.", "Insomnio."]', 1, 'Los retrasos en el desarrollo, incluyendo los retrasos en el habla, el lenguaje, el aprendizaje y las habilidades motoras, están presentes en una parte de los niños con enuresis. El síndrome de piernas inquietas y las parasomnias como los trastornos de despertar del sueño de movimientos oculares no rápidos (tipos de sonambulismo y terror del sueño) están asociados con la enuresis nocturna. Además, existe una relación entre la enuresis nocturna y el ronquido fuerte o las apneas del sueño. Referencia: DSM-5-TR, Enuresis / Comorbilidad (p. 402).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', '¿Cuál de los siguientes es un criterio diagnóstico del trastorno de insomnio?', '["La dificultad para dormir se produce al menos una noche por semana.", "Una queja destacada de insatisfacción con la cantidad o calidad del sueño.", "La dificultad para dormir está presente durante al menos 6 meses.", "La dificultad para dormir puede estar relacionada con ocasiones insuficientes para dormir."]', 1, 'Los criterios diagnósticos del trastorno de insomnio incluyen la queja predominante de insatisfacción con la cantidad o calidad del sueño (la opción B es correcta). El Criterio C requiere que la dificultad para dormir se produzca al menos 3 noches por semana (la opción A es incorrecta). El Criterio D requiere que la dificultad para dormir esté presente durante al menos 3 meses (la opción C es incorrecta). El Criterio E requiere que la dificultad para dormir se produzca a pesar de tener suficientes oportunidades de dormir (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de insomnio / Criterios diagnósticos (pp. 409-410).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', '¿Cuál de las siguientes opciones se requiere para hacer un diagnóstico de trastorno de insomnio?', '["Ausencia de una afección médica coexistente.", "Dificultad para iniciar o mantener el sueño, o despertar temprano por la mañana con incapacidad de volver a dormir.", "Ausencia de un trastorno mental coexistente.", "Ausencia de un trastorno del sueño coexistente."]', 1, 'El Criterio A del diagnóstico de trastorno de insomnio requiere la presencia de insatisfacción con la cantidad o calidad del sueño, asociada con uno (o más) de los siguientes síntomas: 1) dificultad para iniciar el sueño; 2) dificultad para mantener el sueño, caracterizada por despertares frecuentes o problemas para volver a dormir después de dichos despertares; o 3) despertar temprano por la mañana con incapacidad de volver a dormir (la opción B es correcta). El diagnóstico de trastorno de insomnio se da ya sea que ocurra como una afección independiente o de manera comórbida con otro trastorno mental, una afección médica u otro trastorno del sueño (las opciones A, C y D son incorrectas). Referencia: DSM-5-TR, Trastorno de insomnio / Criterios diagnósticos (pp. 409-410).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', 'Un hombre de 80 años tiene antecedentes de infarto de miocardio y se sometió a una cirugía de bypass de la arteria coronaria hace 8 años. Juega al tenis tres veces a la semana, cuida de sus nietos dos tardes cada semana, disfruta generalmente de la vida y maneja todas sus actividades cotidianas de forma independiente; sin embargo, se queja de que se despierta excesivamente temprano. Se va a dormir a las 21:00 p.m. y duerme bien, con nocturia una vez por noche, pero se despierta a las 3:30, aunque le gustaría levantarse a las 5:00. No considera que la somnolencia diurna sea un problema. Su examen físico, estado mental y función cognitiva son normales. ¿Cuál es el diagnóstico más probable de trastorno del sueño-vigilia?', '["Trastorno de insomnio.", "Trastorno del ritmo circadiano de sueño-vigilia.", "Insomnio situacional/agudo.", "Variaciones normales del sueño (sin diagnóstico de trastorno del sueño-vigilia)."]', 3, 'La duración normal del sueño varía considerablemente entre las personas. Algunos individuos que requieren poco sueño ("dormidores cortos") pueden preocuparse por la duración del sueño (la opción D es correcta). Los dormidores cortos se diferencian de las personas con trastorno de insomnio por la falta de dificultad para conciliar o mantener el sueño y por la ausencia de los síntomas diurnos característicos (por ejemplo, fatiga, problemas de concentración, irritabilidad); la opción A es incorrecta. Las personas con trastorno del ritmo circadiano de sueño-vigilia del tipo de fase retardada refieren insomnio de inicio del sueño solo cuando intentan dormir en horarios socialmente normales, pero no se quejan de dificultad para conciliar el sueño o mantenerlo cuando sus horarios de acostarse y levantarse se retrasan y coinciden con su ritmo circadiano endógeno. Este patrón se observa particularmente entre los adolescentes y adultos jóvenes (la opción B es incorrecta). El insomnio situacional/agudo es una entidad que dura desde unos pocos días hasta varias semanas, a menudo asociada a estrés agudo debido a acontecimientos de la vida o a cambios en los horarios de sueño. Estos síntomas de insomnio agudo o a corto plazo también pueden producir malestar significativo e interferir en el funcionamiento social, personal y ocupacional (la opción C es incorrecta). Referencia: DSM-5-TR, Trastorno de insomnio / Diagnóstico diferencial (pp. 415-416).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', '¿Cuál de los siguientes síntomas es más probable que indique la presencia de un trastorno de hipersomnia?', '["Inercia del sueño.", "Sueño no restaurador.", "Somnolencia crónica.", "Prueba de latencia múltiple del sueño con latencia media del sueño < 10 minutos."]', 0, 'El trastorno de hipersomnia incluye síntomas de cantidad excesiva de sueño (por ejemplo, sueño nocturno prolongado, siestas largas), somnolencia e inercia del sueño (es decir, un período de rendimiento disminuido y vigilancia reducida después de despertar del sueño habitual o de una siesta). Alrededor del 40% de las personas con trastorno de hipersomnia pueden tener inercia del sueño, y este síntoma puede ayudar a diferenciar el trastorno de hipersomnia de otras causas de somnolencia (la opción A es correcta). Aproximadamente, el 80% de las personas con trastorno de hipersomnia refieren que su sueño no es restaurador, pero este síntoma es inespecífico y puede ocurrir en los trastornos que interrumpen el sueño, como la apnea obstructiva del sueño (la opción B es incorrecta). Al igual que en el trastorno de hipersomnia, las personas con narcolepsia tienen somnolencia crónica; la somnolencia crónica es también común en los trastornos del sueño relacionados con la respiración (la opción C es incorrecta). La prueba de latencia múltiple del sueño documenta la tendencia al sueño, generalmente indicada por valores de latencia media del sueño de <8 minutos. En el trastorno de hipersomnia, la latencia media del sueño es típicamente <10 minutos y frecuentemente de 8 minutos o menos. Desafortunadamente, la prueba de latencia múltiple del sueño tiene una escasa fiabilidad de prueba-reprueba y no distingue bien entre el trastorno de hipersomnia y la narcolepsia de tipo 2 (es incorrecta la opción D). Referencia: DSM-5-TR, Trastorno de hipersomnia / Características diagnósticas (p. 418); Características asociadas (p. 419); Marcadores diagnósticos (pp. 419-420); Diagnóstico diferencial (pp. 420-421).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', 'Un hombre obeso de 52 años se queja de somnolencia diurna y su pareja confirma que ronca, resopla y jadea durante el sueño nocturno. ¿Qué hallazgo polisomnográfico se requiere para confirmar el diagnóstico de apnea-hipopnea obstructiva del sueño?', '["No es necesario realizar una polisomnografía.", "Índice de apnea-hipopnea mayor de 30.", "Evidencia polisomnográfica de al menos cinco apneas o hipopneas obstructivas por hora de sueño.", "Evidencia polisomnográfica de 15 o más apneas y/o hipopneas obstructivas por hora de sueño."]', 2, 'El Criterio A de la apnea-hipopnea obstructiva del sueño requiere: 1) evidencia polisomnográfica (la opción A es incorrecta) de al menos cinco apneas o hipopneas obstructivas por hora de sueño con: a) alteraciones respiratorias nocturnas (ronquidos, resoplidos/jadeos o pausas respiratorias durante el sueño) (la opción C es correcta) o b) somnolencia diurna, fatiga o sueño no reparador a pesar de tener suficientes oportunidades para dormir, que no se explica mejor por otro trastorno mental (incluido otro trastorno del sueño) y no es atribuible a otra afección médica; o 2) evidencia polisomnográfica de 15 o más apneas y/o hipopneas obstructivas por hora de sueño independientemente de los síntomas acompañantes (la opción D es incorrecta). La gravedad de la enfermedad se mide por el recuento del número de apneas más hipopneas por hora de sueño (índice de apnea-hipopnea) mediante la polisomnografía u otra monitorización nocturna. Se considera que el trastorno es más grave cuando el índice de apnea-hipopnea es mayor de 30 (la opción B es incorrecta). Referencia: DSM-5-TR, Apnea-hipopnea obstructiva del sueño / Criterios diagnósticos (p. 429); Especificadores (pp. 429-430).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', 'El Criterio B de la narcolepsia requiere la presencia de cataplejia, deficiencia de hipocretina o anomalías características en la polisomnografía del sueño o en la prueba de latencia múltiple del sueño. ¿Cuál de las siguientes es una característica definitoria de la cataplejia?', '["Es repentina.", "Ocurre unilateralmente.", "Persiste durante horas.", "Va acompañada de hipertonía."]', 0, 'En las personas con narcolepsia de larga duración, la cataplejia se define como episodios breves (de segundos a minutos; la opción C es incorrecta) de pérdida repentina (la opción A es correcta) bilateral (la opción B es incorrecta) del tono muscular (la opción D es incorrecta) con mantenimiento de la conciencia, que son precipitados por la risa o las bromas. En los niños y en los individuos dentro de los primeros 6 meses desde el inicio, la cataplejia se define como muecas espontáneas o episodios de apertura de la mandíbula con empuje de la lengua o hipotonía global, sin desencadenantes emocionales obvios. Referencia: DSM-5-TR, Narcolepsia / Criterios diagnósticos (pp. 422-425).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', 'Una paciente de 68 años se queja de somnolencia diurna excesiva. La polisomnografía nocturna demuestra 10 episodios de apneas e hipopneas durante el sueño, causadas por la variabilidad del esfuerzo respiratorio. Los períodos de cese de la respiración duran más de 10 segundos. No hay alteraciones respiratorias nocturnas ni períodos sostenidos de desaturación de oxígeno. ¿Cuál es el diagnóstico apropiado del DSM-5-TR para esta persona?', '["Insomnio debido al consumo de sustancias.", "Hiperventilación relacionada con el sueño.", "Apnea-hipopnea obstructiva del sueño.", "Apnea central del sueño."]', 3, 'Los criterios diagnósticos de la apnea central del sueño son evidencia polisomnográfica de cinco o más episodios de apnea central por hora, no explicados por otro trastorno del sueño actual. La apnea central del sueño idiopática se caracteriza por episodios repetidos de apneas e hipopneas durante el sueño, causadas por la variabilidad del esfuerzo respiratorio pero sin evidencia de obstrucción de las vías respiratorias (la opción D es correcta). La apnea central del sueño se puede distinguir de la apnea-hipopnea obstructiva del sueño por la presencia de al menos cinco apneas centrales por hora de sueño. Las apneas centrales del sueño se registran cuando se producen períodos de cese de la respiración de más de 10 segundos. La apnea central del sueño puede coexistir con la apnea-hipopnea obstructiva del sueño, pero se considera que la apnea central del sueño predomina cuando los eventos respiratorios centrales son > 50% del número total de eventos respiratorios. Si no hay evidencia de alteración respiratoria nocturna, debe haber al menos 15 o más apneas y/o hipopneas obstructivas por hora de sueño, independientemente de los síntomas acompañantes, para hacer un diagnóstico de apnea-hipopnea obstructiva del sueño (la opción C es incorrecta). La apnea central del sueño comórbida con el consumo de opioides se atribuye a los efectos de los opioides sobre los generadores del ritmo respiratorio en la médula, así como a los efectos diferenciales sobre la conducción respiratoria hipóxica frente a la hipercápnica. Se puede distinguir del insomnio debido al consumo de drogas o sustancias por la evidencia polisomnográfica de apnea central del sueño (la opción A es incorrecta). La hipoventilación relacionada con el sueño típicamente muestra períodos más sostenidos de desaturación de oxígeno en lugar de los episodios periódicos vistos en la apnea-hipopnea obstructiva del sueño y la apnea central del sueño (la opción B es incorrecta). Referencia: DSM-5-TR, Apnea central del sueño / Criterios diagnósticos (pp. 435-436); Marcadores diagnósticos (p. 438); Diagnóstico diferencial (p. 438); Apnea-hipopnea obstructiva del sueño / Criterios diagnósticos (p. 429); Hipoventilación relacionada con el sueño / Diagnóstico diferencial (p. 442).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', '¿Cuál de los siguientes cambios metabólicos es la característica cardinal de la hipoventilación relacionada con el sueño?', '["Deficiencia de hipocretina.", "Hipoxemia.", "Hipercapnia.", "Diabetes."]', 2, 'La hipoventilación relacionada con el sueño se diagnostica utilizando la polisomnografía, que muestra hipoxemia e hipercapnia relacionadas con el sueño que no se explican mejor por otro trastorno del sueño relacionado con la respiración. La documentación de 1) niveles elevados de pCO2 arterial > 55 mmHg durante el sueño o 2) un aumento de > 10 mmHg en los niveles de pCO2 (a un nivel que también supera los 50 mmHg) durante el sueño en comparación con los valores supinos despiertos, en cada caso superando los 10 minutos de duración, es el patrón de oro para el diagnóstico (la opción C es correcta). Las disminuciones prolongadas y sostenidas de la saturación de oxígeno en ausencia de evidencia de obstrucción de las vías respiratorias superiores a menudo se utilizan como indicador de hipoventilación relacionada con el sueño. Sin embargo, este hallazgo no es específico; hay otras posibles causas de hipoxemia (la opción B es incorrecta). La hipocretina (orexina) es un neuropéptido; la deficiencia de hipocretina es una característica de la narcolepsia de tipo 1 (la opción A es incorrecta). La diabetes se asocia normalmente con la apnea obstructiva del sueño (la opción D es incorrecta). Referencia: DSM-5-TR, Hipoventilación relacionada con el sueño / Marcadores diagnósticos (pp. 441-442); Narcolepsia / Criterios diagnósticos (pp. 422-423); Subtipos (p. 423); Características diagnósticas (pp. 423-424).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', 'Un hombre de 51 años presenta síntomas de fatiga crónica. Durante las noches de los días laborables, tarda varias horas en conciliar el sueño, con dificultad posterior para levantarse e ir a trabajar por la mañana, y somnolencia durante las primeras horas de vigilia. Los fines de semana, se despierta más tarde por la mañana y siente menos fatiga y somnolencia. ¿Cuál de los siguientes es el diagnóstico correcto?', '["Trastorno del ritmo circadiano de sueño-vigilia, tipo de fase de sueño avanzada.", "Trastorno del ritmo circadiano de sueño-vigilia, tipo de sueño-vigilia irregular.", "Trastorno del ritmo circadiano de sueño-vigilia, tipo de sueño-vigilia no ajustado a las 24 horas.", "Trastorno del ritmo circadiano de sueño-vigilia, tipo de fase de sueño retrasada."]', 3, 'El trastorno del ritmo circadiano de sueño-vigilia, tipo de fase de sueño retrasada, se caracteriza por un retraso en el tiempo del período principal de sueño (generalmente más de 2 horas) en relación con el tiempo de sueño y despertar deseado, lo que provoca síntomas de insomnio y somnolencia excesiva. Cuando se les permite establecer su propio horario, las personas con el tipo de fase de sueño retrasada muestran una calidad y duración de sueño normales para su edad. Los síntomas de insomnio de inicio del sueño, dificultad para despertar por la mañana y somnolencia excesiva temprano en el día son prominentes (la opción D es correcta). El trastorno del ritmo circadiano de sueño-vigilia, tipo de fase de sueño avanzada, es un patrón de inicio del sueño y de hora de despertar antes de lo habitual, con incapacidad de permanecer despierto o dormido hasta los momentos de sueño o despertar deseados o convencionalmente aceptables (es incorrecta la opción A). El trastorno del ritmo circadiano de sueño-vigilia, tipo de sueño-vigilia irregular, se caracteriza por un patrón de sueño-vigilia temporalmente desorganizado, de modo que el horario de los períodos de sueño y vigilia es variable a lo largo del período de 24 horas (la opción B es incorrecta). El trastorno del ritmo circadiano de sueño-vigilia, tipo de sueño-vigilia no ajustado a las 24 horas, se caracteriza por un patrón de ciclos de sueño-vigilia que no está sincronizado con el entorno de 24 horas, con un desvío diario constante (generalmente a horarios cada vez más tardíos) de los momentos de inicio del sueño y de despertar (la opción C es incorrecta). Referencia: DSM-5-TR, Trastornos del ritmo circadiano de sueño-vigilia / Criterios diagnósticos (pp. 443-444); Tipo de fase de sueño retrasada / Características diagnósticas (p. 444).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', 'Una mujer de 67 años se queja de insomnio. No tiene problemas para conciliar el sueño entre las 22:00 y 23:00, pero después de 1-2 horas se despierta durante varias horas en medio de la noche, vuelve a dormir durante 2-4 horas a primera hora de la mañana y luego se echa una siesta tres o cuatro veces al día durante 1-3 horas cada vez. Tiene antecedentes familiares de demencia. En el examen parece fatigada y presenta déficits de la memoria a corto plazo, el cálculo y la abstracción. ¿Cuál es el diagnóstico más probable?', '["Trastorno neurocognitivo mayor.", "Trastorno del ritmo circadiano de sueño-vigilia, tipo de sueño-vigilia irregular.", "Trastorno de insomnio.", "Trastorno de depresión mayor."]', 1, 'El trastorno del ritmo circadiano de sueño-vigilia, tipo de sueño-vigilia irregular, se caracteriza por la falta de un ritmo circadiano de sueño-vigilia discernible. El diagnóstico del tipo de sueño-vigilia irregular se basa principalmente en una historia de síntomas de insomnio por la noche (durante el período habitual de sueño) y somnolencia excesiva (siestas) durante el día. No hay un período principal de sueño, y los períodos de sueño y vigilia a lo largo de las 24 horas están fragmentados en al menos tres períodos durante el día de 24 horas. El período de sueño más largo suele ocurrir entre las 2:00 y las 6:00, y generalmente es < 4 horas (la opción B es correcta). El tipo de sueño-vigilia irregular a menudo es comórbido con los trastornos neurodegenerativos y del desarrollo neurológico, como el trastorno neurocognitivo mayor, el trastorno del desarrollo intelectual (discapacidad intelectual) y la lesión cerebral traumática (la opción A es incorrecta). Se debe prestar especial atención para descartar otros trastornos del sueño-vigilia (p. ej., trastorno de insomnio), otros trastornos mentales (p. ej., trastornos depresivos, trastornos bipolares) y las afecciones médicas capaces de causar despertar temprano en la mañana (las opciones C y D son incorrectas). Referencia: DSM-5-TR, Trastornos del ritmo circadiano de sueño-vigilia / Tipo de sueño-vigilia irregular / Características diagnósticas (p. 447), Comorbilidad (p. 448); Tipo de fase de sueño avanzada / Diagnóstico diferencial (p. 447).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', 'Tras una lesión cerebral traumática que le produce ceguera, un hombre de 50 años desarrolla somnolencia diurna creciente y decreciente que interfiere en la actividad diurna. La actigrafía seriada (un método para medir los ciclos de actividad/reposo humanos) demuestra que el momento de inicio del período principal de sueño ocurre progresivamente más tarde día tras día, con duración normal del período principal de sueño. ¿Cuál es el diagnóstico más probable?', '["Trastorno depresivo mayor.", "Trastorno del ritmo circadiano de sueño-vigilia, tipo de fase de sueño retrasada.", "Trastorno del ritmo circadiano de sueño-vigilia, tipo de sueño-vigilia no ajustado a 24 horas.", "Trastorno neurodegenerativo."]', 2, 'El trastorno del ritmo circadiano de sueño-vigilia, tipo de sueño-vigilia no ajustado a las 24 horas, es más común entre las personas ciegas o con discapacidad visual y que tienen una percepción de luz disminuida. El patrón de los ciclos de sueño-vigilia no está sincronizado con el entorno de 24 horas, con un desvío diario constante (generalmente a horarios cada vez más tardíos) de los momentos de inicio del sueño y de despertar (la opción C es correcta). En las personas con visión, el tipo de sueño-vigilia no ajustado a las 24 horas debe diferenciarse del tipo de fase de sueño retrasada porque las personas con el tipo de fase de sueño retrasada pueden mostrar un retraso progresivo similar del período de sueño durante varios días (la opción B es incorrecta). Los trastornos depresivos pueden causar desregulación circadiana y síntomas similares (es incorrecta la opción A). El tipo de sueño-vigilia irregular a menudo es comórbido con trastornos neurodegenerativos y del desarrollo neurológico (la opción D es incorrecta). Referencia: DSM-5-TR, Trastornos del ritmo circadiano de sueño-vigilia / Criterios diagnósticos (pp. 443-444); Tipo de sueño-vigilia no ajustado a 24 horas / Características diagnósticas (pp. 448-449), Diagnóstico diferencial (p. 450).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', 'Una enfermera de urgencias de 50 años se queja de somnolencia en el trabajo que interfiere en su capacidad de funcionamiento. La historia es notable por un cambio reciente del turno de día, de 7:00 a 16:00,al turno de noche, de 23:00 a 8:00. Los síntomas incluyen dificultad para dormir por las mañanas en casa, poca energía para las actividades recreativas o las tareas domésticas por la tarde y sentirse agotada a mitad del turno de noche. ¿Cuál es el diagnóstico más probable?', '["Variación normal del sueño con el trabajo por turnos.", "Trastorno del ritmo circadiano de sueño-vigilia, tipo de turnos laborales.", "Trastorno de insomnio.", "Narcolepsia."]', 1, 'El diagnóstico de trastorno del ritmo circadiano de sueño-vigilia, tipo de turnos laborales, se basa principalmente en la historia de que la persona trabaja fuera de la ventana diurna normal de 8:00 a 18:00 (particularmente por la noche) de manera regularmente programada (es decir, no en horas extras). Destacan los síntomas de somnolencia excesiva en el trabajo y el sueño alterado en casa de manera persistente. La presencia de ambos síntomas generalmente se requiere para el diagnóstico del tipo de turnos laborales (la opción B es correcta). El diagnóstico del tipo de turnos laborales, en contraposición a las dificultades normales del trabajo por turnos, depende en cierta medida de la gravedad de los síntomas y/o el nivel de malestar experimentado por el individuo (la opción A es incorrecta). La presencia de síntomas del tipo de turnos laborales, incluso cuando el individuo puede vivir en una rutina diurna durante varias semanas a la vez, puede sugerir la presencia de otros trastornos del sueño, como la apnea del sueño, el insomnio y la narcolepsia, que deben descartarse (las opciones C y D son incorrectas). Referencia: DSM-5-TR, Trastornos del ritmo circadiano de sueño-vigilia / Tipo de turnos laborales; Características diagnósticas (p. 450); Diagnóstico diferencial (p. 451).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', 'Una adolescente de 14 años se despierta por las mañanas con un recuerdo claro de sueños muy aterradores. Una vez despierta, está normalmente alerta y orientada, pero los sueños son una fuente persistente de angustia. Sus padres informan de murmullos o gemidos ocasionales, pero no de hablar o moverse durante el período antes de despertar. Otros aspectos pertinentes incluyen antecedentes de haber estado sin hogar en una serie de alojamientos temporales durante 1 año a lo largo de su infancia. ¿Cuál es el diagnóstico más probable?', '["Trastorno de terrores nocturnos.", "Trastorno del comportamiento del sueño REM.", "Trastorno de pesadillas.", "Trastorno de estrés postraumático (TEPT)."]', 2, 'El trastorno de pesadillas se caracteriza por la repetición de sueños extendidos, extremadamente disfóricos y bien recordados que generalmente implican esfuerzos para evitar amenazas a la supervivencia, la seguridad o la integridad física, y que generalmente ocurren durante la segunda mitad del período principal de sueño. Al despertar de los sueños disfóricos, el individuo afectado se orienta y se alerta rápidamente (la opción C es correcta). Tanto el trastorno de pesadillas como el trastorno de terrores nocturnos incluyen despertares totales o parciales con miedo y activación autonómica, pero los dos trastornos pueden diferenciarse fácilmente. Las pesadillas típicamente ocurren más tarde en la noche, durante el sueño REM, y producen sueños vívidos, parecidos a un relato y claramente recordados, leve excitación autonómica y despertares completos. Los terrores nocturnos típicamente surgen en el primer tercio de la noche durante el sueño profundo no REM (especialmente durante el sueño de fase 3, ahora llamado sueño N3) y se producen ya sea sin recuerdo del sueño o con imágenes sin calidad de relato elaborado (la opción A es incorrecta). La presencia de actividad vocal y motora compleja durante los sueños aterradores debe provocar una evaluación adicional del trastorno del comportamiento del sueño REM, que ocurre más típicamente en hombres de mediana edad tardía en adelante, pero también puede afectar a las mujeres. Aunque las pesadillas son típicamente características del trastorno del comportamiento del sueño REM, a diferencia del trastorno de pesadillas, el trastorno del comportamiento del sueño REM se asocia a la actuación física del sueño, que puede causar lesiones nocturnas. Si las pesadillas preceden al trastorno del comportamiento del sueño REM y requieren atención clínica independiente, se puede dar un diagnóstico adicional de trastorno de pesadillas (la opción B es incorrecta). Las pesadillas en que el contenido o el afecto del sueño están relacionados con un suceso traumático pueden formar parte del TEPT o del trastorno de estrés agudo (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno de pesadillas / Criterios diagnósticos (p. 457); Diagnóstico diferencial (pp. 460-461).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', '¿Cuál de las siguientes opciones es un tipo de trastorno de despertar del sueño de movimientos oculares rápidos (REM)?', '["Sonambulismo.", "Terrores nocturnos.", "Trastorno de pesadillas.", "Despertares confusos."]', 2, 'Tanto el trastorno de pesadillas como el trastorno de terrores nocturnos incluyen despertares totales o parciales con miedo y activación autonómica, pero los dos trastornos pueden diferenciarse fácilmente. Las pesadillas típicamente ocurren más tarde en la noche, durante el sueño REM, y producen sueños vívidos, parecidos a un relato y claramente recordados, leve excitación autonómica y despertares completos. Los terrores nocturnos típicamente surgen en el primer tercio de la noche durante el sueño profundo no REM (NREM) (sobre todo durante el sueño de fase 3, ahora llamado sueño N3) y se producen ya sea sin recuerdo del sueño o con imágenes sin calidad de relato elaborado (la opción C es correcta y la opción B es incorrecta). Los despertares confusos, el sonambulismo y los terrores nocturnos pueden confundirse fácilmente con el trastorno del comportamiento del sueño REM. Surgen del sueño NREM y, por lo tanto, tienden a ocurrir en la primera parte del período de sueño (las opciones A y D son incorrectas). Referencia: DSM-5-TR, Trastorno de pesadillas / Diagnóstico diferencial (pp. 460-461); Trastorno del comportamiento del sueño REM / Diagnóstico diferencial (p. 463).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', '¿Cuál de las siguientes opciones es una subcategoría específica del trastorno del despertar del sueño no REM, tipo sonambulismo?', '["Terrores nocturnos.", "Comportamiento sexual relacionado con el sueño (sexsomnia).", "Síndrome con solapamiento de parasomnia.", "Síndrome de ingesta nocturna."]', 1, 'Los criterios diagnósticos de los trastornos del despertar del sueño no REM especifican dos tipos: sonambulismo y terrores nocturnos. El tipo de sonambulismo se especifica aún más como comportamiento sexual relacionado con el sueño (sexsomnia) o como ingestión de alimentos relacionada con el sueño (la opción B es correcta y la opción A es incorrecta). El síndrome de solapamiento con parasomnia cursa con características clínicas y polisomnográficas tanto de sonambulismo como de trastorno del comportamiento del sueño REM (la opción C es incorrecta). A diferencia de la forma de ingestión de alimentos relacionada con el sueño del sonambulismo, que se caracteriza por episodios recurrentes de comer durante los despertares incompletos del sueño, se considera que el síndrome de ingesta nocturna es una anomalía del ritmo circadiano de la hora de las comidas, con un inicio normal del sueño circadiano, en la que el individuo se despierta en medio de la noche y come en exceso (la opción D es incorrecta). Referencia: DSM-5-TR, Trastornos del despertar del sueño no REM / Criterios diagnósticos (p. 452).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', '¿Cuál es la anomalía clave de la fisiología del sueño en el trastorno del comportamiento del sueño REM?', '["Actividad electromiográfica periódica infrecuente en las extremidades durante el sueño no REM (NREM).", "Aumento uniforme de la actividad muscular en todos los grupos musculares.", "Parálisis del sueño.", "Sueño REM sin atonía."]', 3, 'El trastorno del comportamiento del sueño REM se caracteriza por episodios repetidos de activación durante el sueño, asociados a vocalizaciones y/o comportamientos motores complejos. La presencia de sueño REM sin atonía durante una polisomnografía es un requisito para el diagnóstico del trastorno del comportamiento del sueño REM. Los hallazgos de laboratorio asociados de la polisomnografía indican una actividad electromiográfica tónica y/o fásica aumentada durante el sueño REM, que normalmente se asocia a atonía muscular. La actividad muscular aumentada afecta de manera variable a diferentes grupos musculares (la opción B es incorrecta). Entre otros hallazgos polisomnográficos se puede encontrar una actividad electromiográfica periódica y aperiódica de las extremidades muy frecuente durante el sueño NREM (la opción A es incorrecta). En el trastorno de pesadillas, si las pesadillas ocurren durante los períodos de sueño REM al inicio del sueño (hipnagógicos), la emoción disfórica está frecuentemente acompañada de un despertar y de incapacidad de moverse voluntariamente (parálisis del sueño; la opción C es incorrecta). Referencia: DSM-5-TR, Trastorno del comportamiento del sueño REM / Características diagnósticas (pp. 461-462); Marcadores diagnósticos (p. 463); Trastorno de pesadillas / Características diagnósticas (p. 458).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', '¿Cuál de las siguientes entidades se asocia comúnmente al trastorno del comportamiento del sueño REM?', '["Narcolepsia.", "Sinucleinopatías.", "Trastorno de convulsiones.", "Trastornos disociativos."]', 1, 'En los individuos con trastorno del comportamiento del sueño REM idiopático, el riesgo de desarrollar una enfermedad neurodegenerativa definida, más a menudo una sinucleinopatía (es decir, enfermedad de Parkinson, trastorno neurocognitivo mayor o leve con cuerpos de Lewy o atrofia multisistémica) es aproximadamente del 75% dentro de los 10-15 años siguientes al diagnóstico, con un riesgo anualizado de aproximadamente el 6-7 % anual (la opción B es correcta). El trastorno del comportamiento del sueño REM está presente concurrentemente en aproximadamente el 30% de los pacientes con narcolepsia (la opción A es incorrecta). Las convulsiones nocturnas pueden imitar el trastorno del comportamiento del sueño REM, pero los comportamientos característicos de las convulsiones nocturnas son generalmente estereotipados (la opción C es incorrecta). A diferencia de prácticamente todas las demás parasomnias, que surgen precipitadamente del sueño no REM o REM, los comportamientos disociativos psicogénicos surgen de un período de vigilia bien definido durante el período de sueño (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno del comportamiento del sueño REM / Desarrollo y curso (p. 462); Diagnóstico diferencial (pp. 463-464); Comorbilidad (p. 464).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', '¿Cuál de las siguientes clases de medicamentos psicotrópicos puede provocar sueño REM sin atonía y trastorno del comportamiento del sueño REM?', '["Inhibidores selectivos de la recaptación de serotonina (ISRS).", "Opioides.", "Benzodiacepinas.", "Estimulantes."]', 0, 'Muchos medicamentos ampliamente recetados, como los antidepresivos tricíclicos, los ISRS y los inhibidores de la recaptación de serotonina-norepinefrina, pueden producir signos polisomnográficos de sueño REM sin atonía y un trastorno franco del comportamiento del sueño REM (la opción A es correcta). Durante el consumo agudo a corto plazo, los opioides pueden producir un aumento de la somnolencia y de la profundidad subjetiva del sueño, y reducir el sueño REM y el sueño de ondas lentas (la opción B es incorrecta). Los sedantes, hipnóticos y ansiolíticos (por ejemplo, los agonistas del receptor de benzodiacepinas) tienen efectos similares a los opioides sobre el sueño (la opción C es incorrecta). Durante la intoxicación aguda, los estimulantes reducen la cantidad total de sueño, aumentan la latencia del sueño y las perturbaciones de la continuidad del sueño, y disminuyen el sueño REM (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno del comportamiento del sueño REM / Diagnóstico diferencial (p. 463); Trastorno del sueño inducido por sustancias / medicamentos / Características asociadas (p. 471).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', 'Un niño de 10 años es remitido para evaluar su dificultad de permanecer sentado en la escuela, lo que está interfiriendo en su rendimiento académico. Se queja de una sensación desagradable de "hormigueo" en las piernas durante los últimos 3 meses y de la necesidad de mover las piernas cuando está sentado quieto, todo lo cual se alivia con el movimiento. Este síntoma está presente la mayor parte del día, pero menos cuando hace deporte después de la escuela o está viendo la televisión por la noche, y generalmente no ocurre en la cama por la noche. ¿Qué aspecto de esta presentación clínica descarta un diagnóstico de síndrome de piernas inquietas (SPI)?', '["La necesidad de mover las piernas se alivia parcial o totalmente con el movimiento.", "La necesidad de mover las piernas comienza o empeora durante los períodos de descanso o inactividad.", "Los síntomas han persistido solo durante 3 meses.", "La necesidad de mover las piernas es peor durante el día que por la noche."]', 3, 'El Criterio A del SPI especifica que deben estar presentes todos los siguientes puntos: 1) la necesidad de mover las piernas comienza o empeora durante los períodos de descanso o inactividad (la opción B es incorrecta); 2) la necesidad de mover las piernas se alivia parcial o totalmente con el movimiento (la opción A es incorrecta); 3) la necesidad de mover las piernas es peor por la tarde o por la noche que durante el día, o solo ocurre por la tarde o por la noche (la opción D es correcta). El Criterio B especifica que los síntomas del Criterio A deben ocurrir al menos tres veces por semana y haber persistido durante al menos 3 meses (la opción C es incorrecta). Referencia: DSM-5-TR, Síndrome de piernas inquietas / Criterios diagnósticos (pp. 464-465).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', 'Una paciente embarazada de 28 años refiere inquietud y dificultad para conciliar el sueño al inicio del período de sueño, así como fatiga diurna. No ha habido cambios en su horario de sueño-trabajo. ¿Qué trastorno del sueño sugiere el inicio de estos síntomas en el tercer trimestre del embarazo?', '["Calambres nocturnos en las piernas.", "Narcolepsia.", "Síndrome de piernas inquietas (SPI).", "Apnea obstructiva del sueño."]', 2, 'La prevalencia del SPI durante el embarazo es de dos a tres veces mayor que en la población general. El SPI asociado con el embarazo alcanza su punto máximo durante el tercer trimestre y mejora o se resuelve en la mayoría de los casos poco después del parto (la opción C es correcta). A diferencia del SPI, los calambres nocturnos en las piernas no suelen manifestarse con el deseo de mover las extremidades ni hay movimientos frecuentes de las extremidades (la opción A es incorrecta). Puede haber una asociación entre el SPI y otros trastornos del sueño, incluidos la narcolepsia y la apnea obstructiva del sueño (las opciones B y D son incorrectas). Referencia: DSM-5-TR, Síndrome de piernas inquietas / Aspectos diagnósticos relacionados con el sexo y el género (pp. 466-467); Diagnóstico diferencial (p. 467).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', '¿Cuál de los siguientes trastornos del sueño se asocia al consumo crónico de opioides?', '["Aumento de la somnolencia.", "Insomnio.", "Aumento del tiempo total de sueño.", "Aumento del sueño REM y del sueño de ondas lentas."]', 1, 'Los opioides pueden producir un aumento de la somnolencia y de la profundidad subjetiva del sueño, y reducir el sueño REM y el sueño de ondas lentas durante su uso agudo a corto plazo. Con la administración continua se desarrolla tolerancia a los efectos sedantes de los opioides y hay quejas de insomnio (la opción B es correcta). Los estudios polisomnográficos demuestran una reducción de la eficiencia del sueño y del tiempo total de sueño (la opción C es incorrecta), con reducción del sueño de ondas lentas y posiblemente del sueño REM (la opción D es incorrecta). En consonancia con sus efectos depresores respiratorios, los opioides exacerban la apnea obstructiva del sueño. También se observa la aparición de apnea del sueño central, especialmente con el uso crónico de opioides de acción prolongada. Referencia: DSM-5-TR, Trastorno del sueño inducido por sustancias / medicamentos / Características asociadas (pp. 471-472).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', '¿Cuál de las siguientes sustancias se asocia con las parasomnias?', '["Anfetaminas.", "Zolpidem.", "Cannabis.", "Cafeína."]', 1, 'Las parasomnias (sonambulismo e ingestión relacionada con el sueño) se han asociado con el uso de agonistas del receptor de benzodiacepinas, especialmente cuando estos medicamentos se toman en dosis altas y cuando se combinan con otros medicamentos sedantes. El zolpidem es un agonista del receptor de benzodiacepinas más reciente (la opción B es correcta). Los trastornos del sueño inducidos por sustancias de tipo anfetamínico y otros estimulantes se caracterizan por insomnio durante la intoxicación y somnolencia excesiva durante la abstinencia (la opción A es incorrecta). La administración aguda de cannabis puede acortar la latencia del sueño, aunque también ocurren efectos de despertar con incrementos en la latencia del sueño. En los usuarios crónicos, se desarrolla tolerancia a los efectos inductores del sueño y potenciadores del sueño de ondas lentas (la opción C es incorrecta). La cafeína consumida en dosis bajas a moderadas durante las horas de la mañana generalmente no produce ningún efecto significativo en el sueño nocturno en las personas con sueño normal o con insomnio. La cafeína puede producir insomnio de manera dependiente de la dosis y del tiempo, especialmente cuando se consumen dosis mayores más tarde en el día o durante las horas de la noche. Se ha observado prolongación de la latencia del sueño, reducción del sueño de ondas lentas, aumento de los despertares nocturno y reducción de la duración del sueño. Algunas personas, especialmente las que consumen grandes cantidades, pueden presentar somnolencia diurna y problemas de rendimiento relacionados con la abstinencia (la opción D es incorrecta). Referencia: DSM-5-TR, Trastorno del sueño inducido por sustancias / medicamentos / Características asociadas (pp. 471-472).'),
('DSM-5-TR', 'Trastornos del sueño-vigilia', 'Una profesora universitaria de 56 años se queja de tener dificultad para dormir más de 5 horas por noche durante las últimas semanas, con somnolencia diurna asociada. El despertar ocurre 1 o 2 horas antes de su hora prevista de despertar por la mañana, con sueño inquieto y frecuentes despertares hasta que llega el momento de levantarse. No hay insomnio inicial ni estado de ánimo deprimido. Atribuye los problemas de sueño a pensamientos intrusivos que surgen, después de un despertar inicial momentáneo, sobre la necesidad de completar un proyecto académico atrasado. ¿Cuál es el diagnóstico más apropiado?', '["Trastorno de insomnio no especificado.", "Otro trastorno de insomnio especificado (sueño restringido no reparador).", "Trastorno de insomnio.", "Otro trastorno de insomnio especificado (trastorno de insomnio a corto plazo)."]', 3, 'La categoría de otro trastorno de insomnio especificado se aplica a las presentaciones en las que predominan los síntomas característicos del trastorno de insomnio que causan malestar o deterioro clínicamente significativos en las áreas sociales, ocupacionales u otras áreas importantes del funcionamiento, pero no cumplen los criterios completos del trastorno de insomnio o de cualquiera de los trastornos de la clase diagnóstica de los trastornos del sueño-vigilia. La categoría de otro trastorno de insomnio especificado se utiliza en aquellas situaciones en las que el clínico elige comunicar la razón específica por la que la presentación no cumple los criterios del trastorno de insomnio ni de ningún trastorno específico del sueño-vigilia. Este caso en particular es un ejemplo de trastorno de insomnio a corto plazo (duración menor a 3 meses; la opción D es correcta). En el ejemplo de "sueño restringido no reparador" de la categoría de otro especificado, la queja predominante es el sueño no restaurador no acompañado de otros síntomas de sueño como la dificultad para conciliar el sueño o permanecer dormido (la opción B es incorrecta). La categoría de trastorno de insomnio no especificado se utiliza en las situaciones en las que el clínico elige no especificar la razón por la que no se cumplen los criterios del trastorno de insomnio o de otro trastorno especificado del sueño-vigilia e incluye las presentaciones en las que hay información insuficiente para hacer un diagnóstico más específico (la opción A es incorrecta). La dificultad para dormir debe estar presente durante al menos 3 meses para hacer el diagnóstico de trastorno de insomnio (la opción C es incorrecta). Referencia: DSM-5-TR, Otro trastorno de insomnio especificado (p. 475); Trastorno de insomnio no especificado (p. 475); Trastorno de insomnio / Criterios diagnósticos (pp. 409-410).'),
('DSM-5-TR', 'Disfunciones sexuales', '¿Cuál de las siguientes opciones es necesaria para el diagnóstico del trastorno del interés/excitación sexual femenino?', '["La alteración ha estado presente desde que la persona se volvió sexualmente activa.", "Al menos tres manifestaciones de falta o reducción significativa del interés/excitación sexual.", "Los síntomas no se limitan a ciertos tipos de estimulación, situación o pareja.", "Los síntomas han persistido durante un mínimo de aproximadamente 6 semanas."]', 1, 'Para que se cumplan los criterios del trastorno del interés/excitación sexual femenino debe haber falta o reducción significativa del interés/excitación sexual, manifestada por al menos tres de los siguientes: 1) ausencia o reducción del interés por la actividad sexual; 2) ausencia o reducción de pensamientos o fantasías sexuales/eróticos; 3) ausencia o reducción de la iniciación de la actividad sexual y generalmente no receptiva a los intentos de iniciarla de la pareja; 4) ausencia o reducción de la excitación/placer sexual durante la actividad sexual en casi todas o todas (aproximadamente, 75-100 %) las relaciones sexuales (en contextos situacionales identificados o, si es generalizado, en todos los contextos); 5) ausencia o reducción del interés/excitación sexual en respuesta a cualquier señal sexual/erótica interna o externa (por ejemplo, escrita, verbal, visual); 6) ausencia o reducción de las sensaciones genitales o no genitales durante la actividad sexual en casi todas o todas (aproximadamente, 75-100 %) las relaciones sexuales (en contextos situacionales identificados o, si es generalizado, en todos los contextos) (la opción B es correcta). El diagnóstico del trastorno del interés/excitación sexual femenino requiere una duración mínima de los síntomas de aproximadamente 6 meses como reflejo de que los síntomas deben ser un problema persistente (la opción D es incorrecta). Existen especificadores para indicar si el problema es de por vida (la alteración ha estado presente desde que el individuo se volvió sexualmente activo) o adquirido (la alteración comenzó después de un período de funcionamiento sexual relativamente normal (la opción A es incorrecta). También existen especificadores para señalar si es generalizado (no se limita a ciertos tipos de estimulación, situaciones o parejas) o situacional (solo ocurre con ciertos tipos de estimulación, situaciones o parejas (la opción C es incorrecta). Referencia: DSM-5-TR, Trastorno del interés / excitación sexual femenino / Criterios diagnósticos (p. 489) / Características diagnósticas (pp. 489-490).'),
('DSM-5-TR', 'Disfunciones sexuales', '¿Cuál de los siguientes es un subtipo de disfunción sexual en el DSM-5-TR?', '["De por vida.", "Secundaria a una afección médica.", "Debida a violencia de la pareja.", "Debida a un trastorno de ansiedad."]', 0, 'Los subtipos se utilizan para designar el inicio del problema. De por vida se refiere a un problema sexual que ha estado presente desde las primeras experiencias sexuales (la opción A es correcta) y adquirido se aplica a los trastornos sexuales que se desarrollan después de un período de funcionamiento sexual relativamente normal. Si la disfunción sexual es atribuible a otra afección médica (por ejemplo, neuropatía periférica), la persona no recibiría un diagnóstico psiquiátrico (la opción B es incorrecta). Si un estrés marcado en la relación, la violencia de la pareja o factores de estrés significativos explican mejor las dificultades sexuales, entonces no se hace el diagnóstico de disfunción sexual, aunque puede consignarse un código Z apropiado para el problema de relación o el factor de estrés (la opción C es incorrecta). Si la disfunción sexual es explicada en su mayoría por otro trastorno mental no sexual (por ejemplo, trastorno depresivo o bipolar, trastorno de ansiedad, trastorno de estrés postraumático, trastorno psicótico), entonces solo se debe hacer el diagnóstico del otro trastorno mental (la opción D es incorrecta). Referencia: DSM-5-TR, Introducción al capítulo (pp. 477-478).'),
('DSM-5-TR', 'Disfunciones sexuales', 'Un hombre de 65 años presenta dificultad para lograr la erección debido a una diabetes y enfermedad vascular grave (previamente diagnosticada en el DSM-IV como disfunción sexual debida a... [indicar la afección médica general] [codificada como 607.84 Trastorno eréctil masculino debido a diabetes mellitus]). ¿Cuál es el diagnóstico correcto del DSM-5-TR para esta presentación?', '["Disfunción sexual debida a una afección médica general.", "Trastorno eréctil.", "Disfunción eréctil.", "Sin diagnóstico psiquiátrico."]', 3, 'El diagnóstico de disfunción sexual requiere descartar los problemas que se explican mejor por una dolencia médica. Si la disfunción sexual es atribuible a otra afección médica (por ejemplo, neuropatía periférica), la persona no recibiría un diagnóstico psiquiátrico (la opción A es incorrecta y la opción D es correcta). El Criterio D del trastorno eréctil especifica que la disfunción sexual no se explica mejor por un trastorno mental no sexual o como consecuencia de una tensión marcada en la relación u otros factores de estrés significativos y no es atribuible a los efectos de una sustancia/medicamento o a otra afección médica (la opción B es incorrecta). Disfunción eréctil es un término descriptivo ampliamente utilizado (incluido en la CIE-10) que se refiere a la dificultad de lograr y mantener una erección (la opción C es incorrecta). Referencia: DSM-5-TR, Introducción al capítulo (pp. 477-478); Trastorno eréctil / Criterios diagnósticos (pp. 481-482); Características diagnósticas (p. 482).'),
('DSM-5-TR', 'Disfunciones sexuales', 'Un hombre de 35 años con diabetes de aparición reciente presenta una historia de 6 meses de incapacidad de mantener una erección. La disfunción eréctil comenzó repentinamente 1 mes después de que lo despidieran de su trabajo. La glucosa sérica está bien controlada con medicación hipoglucemiante oral. ¿Cuál es el diagnóstico apropiado del DSM-5-TR?', '["Sin diagnóstico psiquiátrico.", "Trastorno eréctil.", "Disfunción sexual inducida por sustancias/medicamentos.", "Trastorno de depresión mayor."]', 1, 'La característica esencial del trastorno eréctil es una marcada dificultad para lograr o mantener una erección o una marcada disminución de la rigidez eréctil en todas o casi todas las ocasiones de actividad sexual (Criterio A) que ha persistido durante al menos 6 meses (Criterio B) y que causa malestar clínicamente significativo en el individuo (Criterio C) (la opción B es correcta). El aspecto más difícil del diagnóstico diferencial del trastorno eréctil es descartar los problemas eréctiles que se explican completamente por factores médicos. Tales casos no recibirían un diagnóstico de trastorno mental (la opción A es incorrecta). La distinción entre el trastorno eréctil como trastorno mental y la disfunción eréctil como resultado de otra afección médica suele ser poco clara y muchos casos tendrán etiologías biológicas y psiquiátricas complejas e interactivas. Si el individuo tiene más de 40-50 años y/o presenta problemas médicos concomitantes, el diagnóstico diferencial debe incluir las etiologías médicas, especialmente la enfermedad vascular. La presencia de una enfermedad orgánica conocida por causar problemas eréctiles no confirma una relación causal. Por ejemplo, un individuo con diabetes mellitus puede desarrollar un trastorno eréctil en respuesta al estrés psicológico. En general, la disfunción eréctil debida a factores orgánicos es generalizada y aparece gradualmente. Una excepción serían los problemas eréctiles después de una lesión traumática de la inervación nerviosa de los órganos genitales (por ejemplo, lesión de la médula espinal). Los problemas eréctiles que son situacionales e inconstantes y que tienen un inicio agudo después de un acontecimiento estresante en la vida suelen deberse a razones psicológicas. Un inicio de disfunción eréctil que coincide con el comienzo del consumo de una sustancia/medicamento y disminuye con la interrupción o descenso de la dosis de la sustancia/medicamento sugiere una disfunción sexual inducida por sustancias/medicamentos, que debería diagnosticarse en lugar del trastorno eréctil (la opción C es incorrecta). El trastorno de depresión mayor y el trastorno eréctil están estrechamente asociados, y puede ocurrir que el trastorno eréctil acompañe a un trastorno depresivo grave. Si las dificultades eréctiles se explican mejor por otro trastorno mental, como la depresión mayor, entonces no se haría un diagnóstico de trastorno eréctil (es incorrecta la opción D). Referencia: DSM-5-TR, Trastorno eréctil / Características diagnósticas (p. 482) / Diagnóstico diferencial (pp. 484-485).'),
('DSM-5-TR', 'Disfunciones sexuales', '¿Cuál de los siguientes factores debe tenerse en cuenta durante la evaluación y el diagnóstico de una disfunción sexual?', '["Solo los factores biológicos.", "Factores relacionados solo con el paciente, y no con su pareja.", "Factores culturales o religiosos.", "El sexo específico asignado al individuo al nacer."]', 2, 'Varios factores deben considerarse durante la evaluación y el diagnóstico de una disfunción sexual porque pueden ser relevantes para la etiología o el tratamiento y pueden contribuir, en diversos grados, en diferentes individuos: 1) factores de la pareja (por ejemplo, problemas sexuales de la pareja, estado de salud de la pareja; la opción B es incorrecta); 2) factores de la relación (por ejemplo, mala comunicación; discrepancias en el deseo de actividad sexual); 3) factores de vulnerabilidad individual (por ejemplo, mala imagen corporal, historial de abuso sexual o emocional), comorbilidad psiquiátrica (por ejemplo, depresión, ansiedad) o factores estresantes (por ejemplo, pérdida de empleo, duelo); 4) factores culturales/religiosos (por ejemplo, inhibiciones relacionadas con prohibiciones contra la actividad sexual o el placer, actitudes hacia la sexualidad; la opción C es correcta), y 5) factores médicos relevantes para el pronóstico, el curso o el tratamiento. La respuesta sexual tiene una base biológica necesaria, pero generalmente se experimenta en un contexto intrapersonal, interpersonal y cultural. Por lo tanto, la función sexual implica una compleja interacción entre factores biológicos, socioculturales y psicológicos (la opción A es incorrecta). Referencia: DSM-5-TR, Introducción al capítulo (pp. 477-478).'),
('DSM-5-TR', 'Disfunciones sexuales', 'Una mujer de 30 años llega a la consulta y dice que solo ha ido porque su madre le rogó que fuera. Cuenta que, aunque tiene una buena red social con amigos de ambos sexos, nunca ha sentido excitación sexual ante hombres o mujeres, no tiene fantasías eróticas y tiene poco interés por la actividad sexual. Ha encontrado a otras personas con las mismas ideas, y ella y sus amigos se aceptan a sí mismos como asexuales. ¿Cuál es el diagnóstico apropiado, si lo hay?', '["Trastorno del interés/excitación sexual femenino.", "Otra disfunción sexual especificada.", "Sin diagnóstico porque no tiene el número mínimo de síntomas requeridos para el trastorno del interés/excitación sexual femenino.", "Sin diagnóstico porque no presenta malestar o deterioro clínicamente significativos."]', 3, 'Esta paciente tiene tres de los seis posibles indicadores del Criterio A, que es el número mínimo necesario (la opción C es incorrecta): 1) ausencia o reducción del interés en la actividad sexual, 2) ausencia o reducción de pensamientos o fantasías sexuales/eróticas, 3) ausencia o reducción de la iniciación de la actividad sexual y típicamente no receptiva a los intentos de iniciarla por la pareja, 4) ausencia o reducción de la excitación o el placer sexuales durante la actividad sexual en casi todas o todas (aproximadamente, 75-100 %) las relaciones sexuales (en contextos situacionales identificados o, si es generalizado, en todos los contextos), 5) ausencia o reducción del interés/excitación sexual en respuesta a cualquier señal sexual/erótica interna o externa (por ejemplo, escrita, verbal, visual) y 6) ausencia o reducción de las sensaciones genitales o no genitales durante la actividad sexual en casi todas o todas (aproximadamente, 75-100 %) las relaciones sexuales (en contextos situacionales identificados o, si es generalizado, en todos los contextos). Sin embargo, el Criterio C especifica que los diferentes síntomas del Criterio A causan malestar clínicamente significativo en el individuo (la opción D es correcta). Otra disfunción sexual especificada se aplica a las presentaciones en las que predominan síntomas característicos de una disfunción sexual que causan malestar clínicamente significativo en el individuo, pero no cumplen con los criterios completos de ninguno de los trastornos de la clase diagnóstica de las disfunciones sexuales (la opción B es incorrecta). Referencia: DSM-5-TR, Trastorno del interés / excitación sexual femenino / Criterios diagnósticos (p. 489) / Otra disfunción sexual especificada (p. 509).'),
('DSM-5-TR', 'Disfunciones sexuales', '¿Cuál de los siguientes síntomas o condiciones descartaría el diagnóstico de trastorno eréctil?', '["Presencia de diabetes mellitus.", "Marcada disminución de la rigidez eréctil.", "Presencia del trastorno por consumo de alcohol.", "Presencia de síntomas durante menos de 3 meses."]', 3, 'Una marcada disminución de la rigidez eréctil es uno de los tres síntomas del Criterio A (se requiere al menos uno) que debe experimentarse en casi todas o todas (aproximadamente, 75-100%) las ocasiones de actividad sexual (la opción B es incorrecta). El Criterio B especifica que los síntomas del Criterio A han persistido durante un mínimo de aproximadamente 6 meses (la opción D es correcta). La presencia de diabetes mellitus en sí misma no descarta el trastorno eréctil; los problemas eréctiles que se explican totalmente por factores médicos no recibirían un diagnóstico de trastorno mental (la opción A es incorrecta). De manera similar, la mera presencia de un trastorno por consumo de alcohol no descarta la posibilidad de un trastorno eréctil separado y concurrente. Sin embargo, el inicio de la disfunción eréctil que coincide con el comienzo del consumo de una sustancia/medicamento y que disminuye con la interrupción o bajada de la dosis de dicha sustancia/medicamento sugiere una disfunción sexual inducida por sustancias/medicamentos, que debería diagnosticarse en lugar del trastorno eréctil (la opción C es incorrecta). Referencia: DSM-5-TR, Trastorno eréctil / Criterios diagnósticos (pp. 481-482); Diagnóstico diferencial (pp. 484-485).'),
('DSM-5-TR', 'Disfunciones sexuales', '¿Cuál de las siguientes es una característica distintiva de la eyaculación prematura (precoz) frente a la eyaculación retardada?', '["Los síntomas han estado presentes durante al menos 6 meses.", "Los síntomas deben experimentarse durante la actividad sexual en pareja.", "Los síntomas causan malestar clínicamente significativo en el individuo.", "La gravedad se basa en el nivel de angustia experimentado por el individuo."]', 3, 'El Criterio A tanto de la eyaculación prematura (precoz) como de la eyaculación retardada especifica que los síntomas ocurren durante la actividad sexual en pareja (la opción B es incorrecta). Ambos diagnósticos requieren la presencia de malestar clínicamente significativo (Criterio C). Del mismo modo, el Criterio B de ambos diagnósticos requiere que los síntomas hayan estado presentes durante al menos 6 meses (la opción A es incorrecta). En la eyaculación retardada, la gravedad actual se basa en el nivel de angustia a causa de los síntomas. En la eyaculación prematura (precoz), la gravedad actual se basa en el tiempo que se tarda en eyacular después de iniciar la actividad sexual (la opción D es correcta). Referencia: DSM-5-TR, Eyaculación retardada / Criterios diagnósticos (pp. 478-479); Eyaculación prematura (precoz) / Criterios diagnósticos (pp. 501-502).'),
('DSM-5-TR', 'Disfunciones sexuales', '¿Cuál de los siguientes medicamentos es más probable que cause disfunción sexual?', '["Bupropión.", "Lamotrigina.", "Citalopram.", "Nefazodona."]', 2, 'El efecto secundario más comúnmente reportado de los medicamentos antidepresivos es la dificultad para tener orgasmos o para la eyaculación en los hombres y la excitación en las mujeres. Ciertos agentes (es decir, bupropión, mirtazapina, nefazodona y vilazodona) parecen tener menores tasas de efectos secundarios sexuales que otros antidepresivos (las opciones A y D son incorrectas). Existen diferencias en la incidencia de efectos secundarios sexuales entre algunos antidepresivos serotoninérgicos y adrenérgico-serotoninérgicos combinados, teniendo medicamentos como citalopram, fluoxetina, fluvoxamina, paroxetina, sertralina y venlafaxina las tasas más altas de disfunción sexual (la opción C es correcta). Aunque los efectos de los estabilizadores del estado de ánimo sobre la función sexual no están claros, es posible que el litio y los anticonvulsivos, con la posible excepción de la lamotrigina, tengan efectos adversos sobre el deseo sexual (la opción B es incorrecta). Referencia: DSM-5-TR, Disfunción sexual inducida por sustancias / medicamentos / Características asociadas (p. 507) / Prevalencia (pp. 507-508).'),
('DSM-5-TR', 'Disfunciones sexuales', '¿Cuál de las siguientes afecciones se diagnosticaría correctamente como otra disfunción sexual especificada?', '["Disfunción sexual inducida por sustancias/medicamentos.", "Aversión sexual.", "Eyaculación retardada.", "Trastorno del interés/excitación sexual femenino."]', 1, 'Las opciones A, C y D son disfunciones sexuales diagnosticables, cada una con su propio conjunto específico de criterios. Otra disfunción sexual especificada se aplica a las presentaciones en que predominan los síntomas característicos de una disfunción sexual, que causan malestar clínicamente significativo en el individuo pero no cumplen los criterios completos de ninguno de los trastornos de la clase diagnóstica de las disfunciones sexuales. La categoría de otra disfunción sexual especificada se utiliza en aquellas situaciones en las que el clínico elige comunicar la razón específica por la que la presentación no cumple los criterios de ninguna disfunción sexual específica. Esto se hace registrando "otra disfunción sexual especificada", seguido de la razón específica (por ejemplo, "aversión sexual"; la opción B es correcta). Referencia: DSM-5-TR, Otra disfunción sexual especificada (p. 509).'),
('DSM-5-TR', 'Disforia de género', '¿Cuál de las siguientes opciones debe estar presente para que un niño cumpla los criterios diagnósticos de disforia de género?', '["Trastorno de desarrollo sexual concurrente.", "Fuerte deseo de ser del otro género o insistencia en que uno es del otro género (o algún género alternativo diferente del género asignado).", "Fuerte rechazo de la propia anatomía sexual.", "Fuerte deseo de poseer las características sexuales primarias y/o secundarias propias del género experimentado."]', 1, 'Para la disforia de género en los niños, el Criterio A es una incongruencia marcada entre el género experimentado/expresado y el género asignado, de al menos 6 meses de duración, manifestada por al menos seis de los siguientes criterios (uno de los cuales debe ser el Criterio A1): 1) un fuerte deseo de ser del otro género o insistencia en que uno es del otro género (o algún género alternativo diferente del género asignado; la opción B es correcta); 2) en los niños varones (género asignado), clara preferencia por el travestismo o por imitar la ropa femenina; en las niñas (género asignado), clara preferencia por vestir solo ropa masculina típica y fuerte resistencia a vestir ropa femenina típica; 3) clara preferencia por los roles de género cruzado en los juegos de fantasía o de rol; 4) clara preferencia por los juguetes, juegos o actividades típicamente utilizados o realizados por el otro género; 5) clara preferencia por los compañeros de juego del otro género; 6) en los niños varones (género asignado), claro rechazo de los juguetes, juegos y actividades típicamente masculinos y clara evitación del juego brusco; en las niñas (género asignado), fuerte rechazo de los juguetes, juegos y actividades típicamente femeninos; 7) fuerte rechazo de la propia anatomía sexual (la opción C es incorrecta); 8) fuerte deseo de poseer las características sexuales primarias y /o secundarias propias del género experimentado (la opción D es incorrecta). Existe un especificador para indicar si también hay un trastorno/variante del desarrollo sexual (la opción A es incorrecta). Referencia: DSM-5-TR, Disforia de género / Criterios diagnósticos (pp. 512-5153).'),
('DSM-5-TR', 'Disforia de género', '¿Cuál de las siguientes afirmaciones sobre el diagnóstico de disforia de género en adolescentes y adultos es verdadera?', '["El especificador postransición se utiliza para indicar que el individuo ha pasado (o se está preparando para pasar) por al menos un procedimiento médico o régimen de tratamiento de afirmación de género.", "Para poder recibir el diagnóstico, el individuo debe estar buscando algún tipo de tratamiento de reasignación de sexo.", "Para poder recibir el diagnóstico, el individuo debe tener un fuerte deseo de ser de un género diferente o debe insistir en que es de otro género.", "Para poder recibir el diagnóstico, el individuo debe tener asociado un trastorno del desarrollo sexual."]', 0, 'En los criterios diagnósticos de la disforia de género en los adolescentes y los adultos, el especificador postransición se utiliza para identificar a las personas que han pasado (o se están preparando para pasar) por al menos un procedimiento médico o régimen de tratamiento de afirmación de género, a saber, un tratamiento hormonal de afirmación de género o una cirugía de reasignación de género que confirme el género experimentado (la opción A es correcta). A diferencia del caso de los niños, un adolescente o adulto no necesita tener un fuerte deseo de ser de un género diferente o insistir en que es de otro género para cumplir los requisitos diagnósticos de la disforia de género. Referencia: DSM-5-TR, Disforia de género / Criterios diagnósticos (pp. 512-513); Especificadores (p. 5153).'),
('DSM-5-TR', 'Disforia de género', '¿Cómo se determina el género de una persona?', '["Los factores biológicos contribuyen, en interacción con factores sociales y psicológicos, al desarrollo del género.", "El género se determina al nacer.", "El género se determina oficialmente (y a veces legalmente) cuando un individuo cambia de género.", "El género se determina por procedimientos médicos que alinean las características físicas de un individuo con su género experimentado."]', 0, 'Género se usa para denotar el rol vivido público, sociocultural (y usualmente legalmente reconocido) como niño o niña, hombre o mujer, u otro género. Se considera que los factores biológicos contribuyen, en interacción con factores sociales y psicológicos, al desarrollo del género (la opción A es correcta). Asignación de género se refiere a la asignación como masculino o femenino. Esto usualmente ocurre al nacer sobre la base del sexo fenotípico y, por lo tanto, produce el género asignado al nacer, históricamente referido como sexo biológico o, más recientemente, género natal (la opción B es incorrecta). Reasignación de género denota un cambio oficial (y a veces legal) de género (la opción C es incorrecta). Los tratamientos de afirmación de género son procedimientos médicos (hormonas, cirugías o ambas) que tienen como objetivo alinear las características físicas de un individuo con su género experimentado (la opción D es incorrecta). Referencia: DSM-5-TR, Introducción al capítulo (pp. 511-512).'),
('DSM-5-TR', 'Disforia de género', '¿Qué diagnóstico del DSM-5-TR ha reemplazado al anterior diagnóstico del DSM-IV de trastorno de identidad de género?', '["Género atípico.", "Trastorno travestista.", "Disforia de género.", "No conformidad con los roles de género."]', 2, 'Disforia de género, como término descriptivo general, se refiere a la angustia que puede acompañar a la incongruencia entre el género experimentado o expresado y el género asignado. Aunque no todos los individuos experimentan angustia por la incongruencia, muchos se angustian si no pueden acceder a las intervenciones físicas deseadas mediante hormonas y/o cirugía. El término actual es más descriptivo que el término anterior del DSM-IV, trastorno de identidad de género, y se centra en la disforia, no en la identidad per se, como problema clínico (la opción C es correcta). Género atípico se refiere a las características somáticas o comportamientos que no son típicos (en sentido estadístico) de los individuos con el mismo género asignado en una sociedad y época histórica dadas; no conforme con el género, variante de género y diverso de género son términos no diagnósticos alternativos (las opciones A y D son incorrectas). La disforia de género debe distinguirse de la simple no conformidad con el comportamiento estereotípico de los roles de género por el fuerte deseo de ser de un género distinto al asignado, y por la extensión y la generalidad de las actividades e intereses variantes de género (la opción D es incorrecta). El trastorno de travestismo se diagnostica en adolescentes y adultos masculinos heterosexuales (o bisexuales) (raramente en mujeres) para quienes vestirse con ropa de mujer genera excitación sexual y causa angustia y/o deterioro sin poner en duda su género asignado. Ocasionalmente se acompaña de disforia de género (la opción B es incorrecta). A un individuo con trastorno de travestismo que también tiene disforia de género clínicamente significativa se le pueden dar ambos diagnósticos. En algunos casos de disforia de género de inicio pospuberal en individuos de asignación masculina al nacer que se sienten atraídos por las mujeres, el travestismo con excitación sexual es un precursor del diagnóstico de disforia de género. Referencia: DSM-5-TR, Introducción al capítulo (pp. 511-512); Disforia de género / Diagnóstico diferencial (pp. 519-520).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', 'Un niño de 7 años se ha mostrado extremadamente terco y desafiante durante el último año. Este comportamiento se ve principalmente en casa y normalmente no implica ninguna inestabilidad del estado de ánimo significativa ni ira, aunque ocasionalmente puede ser rencoroso y vengativo. Estos síntomas han afectado a la relación con sus hermanos de manera extremadamente negativa y, más recientemente, este comportamiento se ha visto con sus compañeros y ha comenzado a afectar a sus amistades. Sus padres tienen un estilo de crianza algo hostil. ¿Cuál de las siguientes afirmaciones sobre el diagnóstico del trastorno negativista desafiante (TND) es correcta para este paciente?', '["El niño no reúne los requisitos del diagnóstico de TND porque sus síntomas carecen de componente anímico significativo.", "El niño puede reunir los requisitos del diagnóstico de TND, a pesar de carecer de un estado de ánimo negativo persistente, si cumple los otros criterios sintomáticos.", "El niño no reúne los requisitos del diagnóstico de TND porque sus síntomas se limitan principalmente al entorno del hogar.", "El niño no reúne los requisitos del diagnóstico de TND porque sus síntomas no han estado presentes durante un período de tiempo suficiente."]', 1, 'Según el DSM-5-TR, no es raro que las personas con TND muestren las características comportamentales del trastorno sin problemas de estado de ánimo negativo. Los síntomas del TND pueden estar confinados a un solo entorno, y este es con gran frecuencia el hogar. Las personas que muestran suficientes síntomas para alcanzar el umbral diagnóstico, incluso si es solamente en casa, pueden estar significativamente afectadas en su funcionamiento social. Debido a que estos comportamientos son comunes entre hermanos, deben observarse durante las interacciones con personas que no sean los hermanos. Además, debido a que los síntomas del trastorno suelen ser más evidentes en las interacciones con los adultos o compañeros que el individuo conoce bien, es posible que no sean evidentes durante un examen clínico. En los niños menores de 5 años, el comportamiento debe ocurrir la mayoría de los días durante un período de al menos 6 meses. En las personas de 5 años o más, el comportamiento debe producirse al menos una vez por semana durante al menos 6 meses, a menos que se indique lo contrario. Referencia: DSM-5-TR, Trastorno negativista desafiante / Criterios diagnósticos (pp. 522-523).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', 'Un niño de 3 años ha tenido rabietas graves, aproximadamente semanales, durante un período de 6 meses. Las rabietas se caracterizan por ira y comportamiento desafiante, rebatiendo el niño las instrucciones de sus padres. Las rabietas suelen ir precedidas de algún cambio en la rutina, de fatiga o de hambre, y rara vez incluyen agresión o destrucción de objetos. El niño se comporta generalmente bien en la guardería y durante los períodos entre rabietas. ¿Cuál de los siguientes es el diagnóstico más apropiado?', '["Trastorno negativista desafiante (TND).", "Trastorno explosivo intermitente (TEI).", "Trastorno de desregulación disruptiva del estado de ánimo (TDDEA).", "Ninguna de las anteriores."]', 3, 'El Criterio A del TND requiere un patrón de estado de ánimo enojado/irritable, de comportamiento discutidor/desafiante y de rencor que dure al menos 6 meses, demostrado por al menos cuatro síntomas de cualquiera de las siguientes categorías y exhibidos durante la interacción con al menos un individuo que no es un hermano: * Estado de ánimo enojado/irritable: 1. Pierde los estribos. 2. Está susceptible o se enfada fácilmente con los demás. 3. Está enojado y resentido. * Comportamiento discutidor/desafiante: 4. Discute directamente con las figuras de autoridad o los adultos. 5. Desafía activamente o se niega a cumplir las solicitudes de las figuras de autoridad o los adultos, o bien las normas. 6. Molesta a las personas a propósito. 7. Culpa a los demás de sus errores o mal comportamiento. * Rencor: 8. Se ha mostrado rencoroso o vengativo al menos dos veces en los últimos 6 meses. Las rabietas en un niño de preescolar se considerarían un síntoma de TND solo si ocurrieran en la mayoría de los días durante los últimos 6 meses, si ocurrieran con al menos otros tres síntomas del trastorno y si las rabietas contribuyeran a una perturbación significativa asociada al trastorno (por ejemplo, llevaron a la destrucción de objetos, a que se pidiera al niño que abandonara el preescolar). En este caso, las rabietas del niño son el único síntoma; por lo tanto, no cumplirían el Criterio A. Aunque las rabietas del niño han ocurrido al menos semanalmente durante un período de 6 meses, el DSM-5-TR señala específicamente que, en un niño menor de 5 años, el comportamiento que cumple el Criterio A solo puede considerarse un síntoma de TND si ocurre en la mayoría de los días durante los últimos 6 meses. Finalmente, las rabietas no parecen causar malestar o deterioro funcional significativos (Criterio B) y podrían ser de naturaleza evolutiva. No se debe dar un diagnóstico de TEI a los individuos menores de 6 años o con nivel de desarrollo equivalente. El diagnóstico de TODEA no debe hacerse por primera vez antes de los 6 años ni después de los 18 años. En el caso del TDDEA, las rabietas deben ocurrir con frecuencia (es decir, una media de tres o más veces por semana; Criterio C) durante al menos 1 año y deben ser inapropiadas para la etapa de desarrollo (Criterio B). La irritabilidad aguda del TDDEA consiste en un estado de ánimo crónico irritable o enojado que está presente entre las rabietas graves. Este estado de ánimo irritable o enojado debe ser característico del niño, debe estar presente la mayor parte del día, casi todos los días, y debe ser observable por los demás en el entorno del niño (Criterio D). Referencia: DSM-5-TR, Trastorno negativista desafiante / Criterios diagnósticos (pp. 522-523) y Diagnóstico diferencial (pp. 525-526).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', 'Los criterios diagnósticos del trastorno negativista desafiante (TND) incluyen especificadores para indicar la gravedad del trastorno, manifestada por la omnipresencia de los síntomas en diferentes entornos y relaciones. ¿Cuál de los siguientes especificadores sería apropiado para un niño de 11 años que cumple los síntomas del Criterio A en casa y en la escuela?', '["Leve.", "Moderado.", "Grave.", "Información insuficiente."]', 1, 'El especificador leve requiere que los síntomas se limiten a un entorno, el especificador moderado requiere que los síntomas estén presentes en al menos dos entornos y el especificador grave requiere que los síntomas estén presentes en al menos tres entornos. Referencia: DSM-5-TR, Trastorno negativista desafiante / Criterios diagnósticos; Especificadores (pp. 522-523).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', 'Un adolescente de 13 años que anteriormente se comportaba bien comienza a mostrar un comportamiento extremadamente desafiante y oposicionista, con rencor, durante los últimos 8 meses. Está enojado, discute y se niega a aceptar la responsabilidad de su comportamiento, lo que está afectando significativamente a su vida en casa y en la escuela. ¿Qué aspecto de esta presentación se ajusta mal a un diagnóstico de trastorno negativista desafiante (TND)?', '["Falta de remordimiento.", "Duración de los síntomas.", "Edad de inicio.", "Síntomas en múltiples entornos."]', 2, 'Los primeros síntomas de TND suelen aparecer durante los años preescolares y rara vez después de la adolescencia temprana. El TND es un diagnóstico poco probable si el inicio es en la adolescencia, después de una infancia marcada por un comportamiento complaciente. Los factores de estrés ambiental y familiar pueden asociarse a manifestaciones que exteriorizan la desregulación emocional. Pueden manifestarse como rabietas y comportamiento oposicionista en los niños y como comportamientos agresivos en los adolescentes. La asociación temporal con un factor de estrés y la duración de los síntomas de menos de 6 meses después de la resolución del factor de estrés pueden ayudar a distinguir el trastorno de adaptación del TND. En este caso, el inicio relativamente tardío sugiere un trastorno del estado de ánimo, un trastorno de adaptación (a un factor de estrés no descrito en el caso) o un trastorno por consumo de sustancias. Para contar en el diagnóstico de un episodio depresivo mayor, un síntoma debe ser nuevo o haber empeorado claramente en comparación con el estado previo al episodio del individuo. Muchas personas refieren o exhiben un aumento de la irritabilidad (por ejemplo, ira persistente, tendencia a responder a los sucesos con arrebatos de ira o culpando a otros, sensación exagerada de frustración por asuntos menores). En los niños y adolescentes puede desarrollarse un estado de ánimo irritable o malhumorado en lugar de un estado de ánimo triste o abatido. Referencia: DSM-5-TR, Trastorno negativista desafiante / Desarrollo y curso (p. 524).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', '¿Cuál es un factor de riesgo asociado con el trastorno negativista desafiante (TND)?', '["Mayor reactividad al cortisol.", "Ser acosado.", "Crianza permisiva.", "Baja reactividad emocional."]', 1, 'Los niños con TND tienen mayor riesgo tanto de acosar a sus compañeros como de ser acosados por ellos. Aunque se han identificado una serie de marcadores neurobiológicos (por ejemplo, menor frecuencia cardíaca y reactividad de la conductancia de la piel; reducción de la reactividad basal al cortisol; anomalías en la corteza prefrontal y la amígdala) en asociación con el TND, no se pueden usar diagnósticamente porque la gran mayoría de los estudios no han separado a los niños con TND de aquellos con trastorno de conducta. Por lo tanto, no está claro si existen marcadores específicos para el TND. Las prácticas de crianza duras, incoherentes o negligentes predicen aumentos de los síntomas, y las manifestaciones del trastorno a lo largo del desarrollo parecen similares. Los factores temperamentales relacionados con problemas de la regulación emocional (por ejemplo, altos niveles de reactividad emocional, baja tolerancia a la frustración) se han mostrado predictivos del trastorno. Referencia: DSM-5-TR, Trastorno negativista desafiante / Desarrollo y curso; Factores de riesgo y pronóstico (pp. 524-525).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', 'Un chico de 16 años con una larga historia de comportamiento desafiante hacia las figuras de autoridad también tiene antecedentes de agresión a sus compañeros (se mete en peleas en la escuela), sus padres y objetos (golpea las paredes, rompe puertas). Miente con frecuencia. Recientemente ha comenzado a robar mercancías de las tiendas locales, y dinero y joyas de sus padres. No parece irritado o deprimido de manera generalizada, no tiene trastornos del sueño y niega haber tenido síntomas psicóticos. ¿Cuál es el diagnóstico más probable?', '["Trastorno negativista desafiante (TND).", "Trastorno de la conducta.", "Trastorno de déficit de atención/hiperactividad (TDAH).", "Trastorno de desregulación disruptiva del estado de ánimo (TDDEA)."]', 1, 'Este chico muestra agresiones a personas, destrucción de propiedades y engaño o robo, todos parte del Criterio A del trastorno de la conducta en el DSM-5-TR. Los individuos con TND no suelen ser agresivos hacia las personas o los animales y generalmente no destruyen propiedades ni exhiben patrones de comportamiento que conlleven robo o engaño. Además, las personas con TND tienen problemas de desregulación emocional como característica más prominente y generalizada de su presentación. No hay suficiente información en este caso para establecer un diagnóstico de TDAH. Aunque los niños con TDAH a menudo exhiben un comportamiento hiperactivo e impulsivo que puede ser disruptivo, este comportamiento por sí solo no viola las normas sociales ni los derechos de los demás. La falta de un trastorno del estado de ánimo generalizado argumenta en contra del diagnóstico de TDDEA. Referencia: DSM-5-TR, Trastorno de la conducta / Criterios diagnósticos (pp. 530-531).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', 'Un chico de 15 años tiene antecedentes de comportamiento violento episódico que es desproporcionado con respecto al hecho desencadenante. Durante un episodio típico, que se intensifica rápidamente, se enfada extremadamente, golpea las paredes o rompe los muebles en casa. No parece haber ningún propósito o beneficio específico asociado con los arrebatos y en el plazo de 30 minutos se tranquiliza y "vuelve a la normalidad", estado que no se asocia a ningún trastorno del estado de ánimo predominante. ¿Qué diagnóstico se ajusta mejor a este cuadro clínico?', '["Trastorno bipolar.", "Trastorno de desregulación disruptiva del estado de ánimo (TDDEA).", "Trastorno explosivo intermitente (TEI).", "Trastorno de déficit de atención/hiperactividad (TDAH)."]', 2, 'La presentación de este adolescente es característica del TEI. El hecho de que no haya trastorno del estado de ánimo entre los episodios argumenta en contra del trastorno bipolar o el TDDEA. A diferencia del TEI, el TDDEA se caracteriza por un estado de ánimo negativo persistente la mayor parte del día, casi todos los días, entre los arrebatos de agresión impulsiva. La agresión en el TEI es impulsiva y el TDAH puede ser comórbido con el TEI, pero los síntomas del TDAH distintos de la impulsividad (inatención e inquietud) no se describen en este caso. Referencia: DSM-5-TR, Trastorno explosivo intermitente / Criterios diagnósticos (p. 527).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', '¿Cuál de los siguientes no es un factor de riesgo del trastorno explosivo intermitente (TEI)?', '["Parientes de primer grado con TEI.", "Separación de los miembros de la familia en poblaciones de refugiados.", "Trastorno de la personalidad esquizotípica.", "Trastorno de la personalidad límite."]', 2, 'Según el DSM-5-TR, los parientes de primer grado de los individuos con TEI tienen mayor riesgo de tener también el trastorno, que tiene un fuerte componente genético en la agresión impulsiva. Las personas con trastorno de la personalidad antisocial o trastorno de la personalidad límite y aquellas que tienen antecedentes de trastornos con comportamientos disruptivos (por ejemplo, TDAH, trastorno de la conducta, trastorno negativista desafiante) tienen mayor riesgo de tener un TEI comórbido. El desplazamiento a largo plazo del hogar y la separación de los miembros de la familia son factores de riesgo en algunos entornos de las poblaciones de refugiados. Referencia: DSM-5-TR, Trastorno explosivo intermitente / Factores de riesgo y pronóstico; Comorbilidad (p. 529).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', '¿Cuál de los siguientes marcadores biológicos está asociado con el trastorno explosivo intermitente (TEI)?', '["Anormalidades serotoninérgicas en el sistema límbico y la corteza orbitofrontal.", "Respuestas reducidas de la amígdala a los estímulos de ira durante la resonancia magnética funcional (£MRI).", "Anormalidades de la función adrenal.", "Aumento de las catecolaminas urinarias."]', 0, 'La investigación neurobiológica respalda la presencia de anomalías serotoninérgicas, a nivel global y en el cerebro, específicamente en áreas del sistema límbico (cíngulo anterior) y la corteza orbitofrontal de los individuos con TEI. Las respuestas de la amígdala a los estímulos de la ira durante la resonancia magnética funcional son mayores en los individuos con TEI que en los individuos sanos. No hay evidencia actual de anomalías de la función adrenal ni de alteración de las catecolaminas urinarias. Referencia: DSM-5-TR, Trastorno explosivo intermitente / Características asociadas (p. 528).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', '¿Cuál de las siguientes afirmaciones sobre el diagnóstico diferencial del trastorno explosivo intermitente (TEI) es falsa?', '["En los niños, el diagnóstico de TEI se puede hacer en el contexto de un trastorno de adaptación.", "A diferencia del TEI, el trastorno de desregulación disruptiva del estado de ánimo se caracteriza por un estado de ánimo negativo persistente (es decir, irritabilidad, ira) la mayor parte del día, casi todos los días, entre los arrebatos de agresión impulsiva.", "El nivel de agresividad impulsiva en los individuos con trastorno de la personalidad antisocial o trastorno de la personalidad límite es menor que en los individuos con TEI", "La agresión en el trastorno negativista desafiante se caracteriza típicamente por berrinches y discusiones verbales con las figuras de autoridad, mientras que los arrebatos de agresión impulsiva del TEI responden a una gama más amplia de provocaciones e incluyen la agresión física."]', 0, 'El DSM-5-TR estipula que, en los niños de 6 a 18 años, el comportamiento agresivo que ocurre como parte de un trastorno de adaptación no debe tenerse en cuenta para el diagnóstico de TEI. Referencia: DSM-5-TR, Trastorno explosivo intermitente / Criterios diagnósticos; Características diagnósticas (pp. 527-528).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', 'Un adolescente de 17 años con antecedentes de intimidación e iniciación de peleas con bates y cuchillos también ha robado, ha provocado incendios, ha destruido propiedades, ha irrumpido en casas y ha "engañado" a otros. ¿Qué categoría del Criterio A del trastorno de la conducta no se cumple en este caso?', '["Agresión a personas y animales.", "Destrucción de la propiedad.", "Engaño o robo.", "Violaciones graves de las reglas."]', 3, 'La característica esencial del trastorno de la conducta es un patrón de comportamiento repetitivo y persistente en el que se violan los derechos básicos de los demás o las normas sociales o reglas importantes para la edad (Criterio A). Estos comportamientos se dividen en cuatro grupos principales: conducta agresiva que causa o amenaza con daño físico a otras personas o animales (Criterios A1-A7); conducta no agresiva que causa pérdida o daños de objetos (Criterios A8-A9); engaño o robo (Criterios A10-A12), y violaciones graves de las reglas (Criterios A13-A15). Las violaciones graves de las reglas, según el DSM-5-TR, incluyen lo siguiente: a menudo trasnocha fuera de casa a pesar de las prohibiciones de los padres, comenzando antes de los 13 años; ha huido de casa al menos dos veces mientras vivía en el hogar de los padres o los sustitutos parentales, o una sola vez pero sin regresar durante un largo período; y a menudo se ausenta de la escuela, comenzando antes de los 13 años. Referencia: DSM-5-TR, Trastorno de la conducta / Características diagnósticas (pp. 533).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', 'Una adolescente de 15 años con historial de crueldad hacia los animales, robo, absentismo escolar y huida de casa no muestra remordimientos cuando la atrapan ni cuando se le hace saber cómo afectan estos comportamientos a su familia. Ignora los sentimientos de los demás y parece no importarle que su conducta esté comprometiendo su rendimiento escolar. El comportamiento ha estado presente durante más de 1 año y en múltiples relaciones y entornos. ¿Cuál de los siguientes componentes del especificador con emociones prosociales limitadas está ausente en este cuadro clínico?', '["Falta de remordimiento o culpa.", "Insensible-falta de empatía.", "Despreocupada por el rendimiento.", "Afecto superficial o deficiente."]', 3, 'El afecto superficial o deficiente se define en el DSM-5-TR como "no expresa sentimientos ni muestra emociones a los demás, excepto de maneras que parecen frívolas, insinceras o superficiales (por ejemplo, las acciones contradicen la emoción mostrada; puede encender o apagar emociones rápidamente) o cuando las expresiones emocionales se utilizan para obtener beneficios (por ejemplo, emociones mostradas para manipular o intimidar a otros)". No se proporciona suficiente información en este caso como para indicar si esta paciente tiene o no un afecto superficial o deficiente. Referencia: DSM-5-TR, Trastorno de la conducta / Criterios diagnósticos (pp. 530-532).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', '¿Cuál de las siguientes opciones no se califica de comportamiento agresivo bajo las definiciones del Criterio A del diagnóstico del trastorno de la conducta?', '["Ciberacoso.", "Forzar a alguien a realizar una actividad sexual.", "Robar enfrentándose a la víctima.", "Agresión en el contexto de un trastorno del estado de ánimo."]', 3, 'La irritabilidad, la agresión y los problemas de conducta pueden ocurrir en niños o adolescentes con trastorno depresivo mayor, trastorno bipolar o trastorno de desregulación disruptiva del estado de ánimo. Basándose en su curso, los problemas de comportamiento asociados con estos trastornos del estado de ánimo generalmente se pueden distinguir del patrón de problemas de conducta observado en el trastorno de la conducta. Específicamente, las personas con trastorno de la conducta mostrarán niveles sustanciales de problemas de conducta agresiva o no agresiva durante los períodos en los que no hay alteración del estado de ánimo, ya sea históricamente (es decir, un historial de problemas de conducta que precede al inicio de la alteración del estado de ánimo) o concurrentemente (es decir, problemas de conducta que son premeditados y no ocurren durante períodos de intensa excitación emocional). En aquellos casos en los que se cumplen los criterios del trastorno de la conducta y de un trastorno del estado de ánimo se pueden dar ambos diagnósticos. El Criterio A del trastorno de la conducta, la agresión a personas y animales, incluye lo siguiente: 1) a menudo intimida, amenaza o acosa a otros; 2) a menudo inicia peleas físicas; 3) ha utilizado un arma que puede causar daños físicos graves a otros (por ejemplo, bate, ladrillo, botella rota, cuchillo, pistola); 4) ha sido físicamente cruel con personas; 5) ha sido físicamente cruel con animales; 6) ha robado enfrentándose a la víctima (por ejemplo, atraco, robo de bolsos, extorsión, robo a mano armada), y 7) ha forzado a alguien a realizar una actividad sexual. Referencia: DSM-5-TR, Trastorno de la conducta / Criterios diagnósticos (pp. 530-532); Diagnóstico diferencial (p. 536).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', 'Una adolescente de 16 años que ha empezado a faltar a la escuela al menos tres veces a la semana este año se muestra discutidora con sus profesores y padres. Los padres recuerdan muchos berrinches debido a que no conseguía lo que quería cuando estaba en edad preescolar. Recientemente ha estado incumpliendo el horario de salidas y volviendo a casa intoxicada alrededor de las 2:00. Hubo un tiempo el año pasado en el que estuvo desaparecida durante 2 semanas. ¿Cuál de los síntomas de esta paciente es un síntoma del trastorno de conducta?', '["Absentismo escolar.", "Berrinches durante la edad preescolar.", "Fuga durante un período prolongado.", "Incumplir el horario de salidas."]', 2, 'El Criterio A14 del DSM-5-TR para el trastorno de la conducta especifica fugarse una vez si es por un período prolongado o durante la noche al menos dos veces. El absentismo escolar de la paciente y la transgresión del horario de salidas comenzaron este año; el DSM-5-TR especifica que, en el trastorno de la conducta, este comportamiento necesita comenzar antes de los 13 años. En un niño en edad preescolar, los berrinches y su frecuencia se consideran en el diagnóstico del trastorno negativista desafiante, pero no en el trastorno de la conducta. Referencia: DSM-5-TR, Trastorno de la conducta / Características diagnósticas (p. 533).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', 'Comparados con los individuos con trastorno de la conducta de inicio en la infancia, ¿qué es más probable que tengan los pacientes con trastorno de la conducta de inicio en la adolescencia?', '["Trastorno negativista desafiante (TND).", "Trastorno de déficit de atención/hiperactividad (TDAH).", "Síntomas persistentes en la edad adulta.", "Relaciones con pares normativas."]', 3, 'En el trastorno de la conducta de inicio en la infancia, los individuos suelen ser hombres, frecuentemente muestran agresividad física hacia otros, tienen malas relaciones con sus pares, pueden haber tenido TND durante la primera infancia y generalmente presentan síntomas que cumplen los criterios completos del trastorno de la conducta antes de la pubertad. Muchos niños con este subtipo también tienen TDAH concurrente u otros problemas del neurodesarrollo. Los individuos con el tipo de inicio en la infancia tienen más probabilidades de tener un trastorno de la conducta persistente en la edad adulta que aquellos con trastorno de conducta de inicio en la adolescencia. En comparación con los individuos con trastorno de la conducta de inicio en la infancia, los individuos con trastorno de la conducta de inicio en la adolescencia son menos propensos a mostrar comportamientos agresivos y tienden a tener relaciones más normativas con sus pares (aunque a menudo muestran problemas de conducta en compañía de otros). Estos individuos son menos propensos a tener un trastorno de la conducta que persista en la edad adulta. Referencia: DSM-5-TR, Trastorno de la conducta / Subtipos (p. 532).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', '¿Qué es más común en los individuos que cumplen los criterios del especificador con emociones prosociales limitadas del trastorno de la conducta?', '["Rasgos de personalidad como evitación de riesgos, temor y extrema sensibilidad al castigo.", "Participar en una agresión impulsiva.", "Un indicador de gravedad leve.", "Subtipo de trastorno de la conducta de inicio en la infancia."]', 3, 'Para merecer el especificador con emociones prosociales limitadas, el individuo debe haber mostrado al menos dos de las características enumeradas—falta de remordimiento o culpa, insensibilidad/falta de empatía, indiferencia sobre el rendimiento y afecto superficial o deficiente de manera persistente durante al menos 12 meses y en múltiples relaciones y contextos. Estas características deben reflejar el patrón típico de funcionamiento interpersonal y emocional del individuo durante este período, y no solo episodios ocasionales en algunas situaciones. Una minoría de individuos con trastorno de la conducta exhiben características que merecen este especificador. Los indicadores de este especificador son aquellos que a menudo se han etiquetado como rasgos insensibles y desalmados en la investigación. Otras características de la personalidad, como la búsqueda de emociones, la falta de miedo y la insensibilidad al castigo, también pueden distinguir a los individuos con las características descritas en el especificador. Estos individuos pueden ser más propensos que otros con trastorno de la conducta a participar en agresiones planeadas para obtener ganancias instrumentales. Los individuos con trastorno de la conducta de cualquier subtipo o cualquier nivel de gravedad pueden tener características que reúnan los requisitos del especificador con emociones prosociales limitadas, aunque los individuos con este especificador son más propensos a tener el tipo de inicio en la infancia y un especificador de gravedad aguda. Referencia: DSM-5-TR, Trastorno de la conducta / Criterios diagnósticos; Especificadores (pp. 531-533).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', 'Al comparar poblaciones, ¿qué población se asocia a una mayor prevalencia del trastorno de la conducta?', '["Estados Unidos en comparación con otros países occidentales.", "Adolescentes socialmente oprimidos en comparación con los adolescentes socialmente privilegiados.", "Mujeres en comparación con hombres.", "Niños en comparación con adolescentes."]', 1, 'Las tasas de prevalencia poblacional de 1 año oscilan entre el 2 y más del 10%, con una mediana del 4%, en Estados Unidos y otros países mayoritariamente de altos ingresos. La prevalencia del trastorno de la conducta en las muestras mayoritariamente occidentales parece ser bastante uniforme en varios países. La prevalencia del trastorno de la conducta de inicio en la adolescencia se asocia más frecuentemente a factores de estrés psicosocial (por ejemplo, ser miembro de un grupo étnico socialmente oprimido que sufre discriminación). Las tasas de prevalencia aumentan desde la infancia hasta la adolescencia y son más altas entre los hombres que entre las mujeres. Referencia: DSM-5-TR, Trastorno de la conducta / Especificadores (pp. 532-533); Prevalencia (p. 534).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', '¿Cuál de las siguientes afirmaciones sobre el inicio y el curso evolutivo del trastorno de la conducta es verdadera?', '["El inicio puede ocurrir incluso en los años preescolares.", "La edad de inicio no tiene ninguna relación con el curso evolutivo del trastorno.", "El trastorno negativista desafiante generalmente no es un precursor del tipo de trastorno de la conducta de inicio en la infancia.", "El inicio es común después de los 16 años."]', 0, 'El inicio del trastorno de la conducta generalmente ocurre en el período desde la infancia media hasta la adolescencia media, aunque los síntomas pueden aparecer en los años preescolares. Los individuos con el tipo de inicio en la adolescencia y aquellos con síntomas menos frecuentes y más leves tienden a tener una mayor probabilidad de tener éxito (desde un punto de vista social y ocupacional) como adultos. El trastorno negativista desafiante es un precursor común del trastorno de la conducta de inicio en la infancia. Referencia: DSM-5-TR, Trastorno de la conducta / Desarrollo y curso (p. 534).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', '¿Cuál de los siguientes es un factor de riesgo para el desarrollo del trastorno de la conducta?', '["Coeficiente intelectual verbal superior al promedio.", "Tamaño de la familia pequeño.", "Estado de refugiado.", "Historial parental de trastorno de déficit de atención/hiperactividad (TDAH)."]', 3, 'El trastorno de la conducta parece ser más común en los hijos de padres biológicos con trastorno por consumo masivo de alcohol, trastornos depresivos y bipolares o esquizofrenia, o padres biológicos con historial de TDAH o trastorno de la conducta. Los factores de riesgo temperamentales incluyen un temperamento infantil difícil y no controlado y una inteligencia inferior a la media, particularmente con respecto al coeficiente intelectual verbal. Los factores de riesgo a nivel familiar incluyen el rechazo y la negligencia parental, las prácticas de crianza incoherentes, la disciplina severa, el maltrato físico o sexual, la falta de supervisión, la vida institucional temprana, los cambios frecuentes de cuidadores, el tamaño grande de la familia, la criminalidad parental y ciertos tipos de psicopatología familiar (por ejemplo, trastornos relacionados con sustancias). Los factores de riesgo a nivel comunitario incluyen el rechazo de los pares, la asociación con un grupo de pares delincuentes, la desventaja del vecindario y la exposición a la violencia. La migración parental es un factor de riesgo tanto para los niños que se quedan en el país de origen como para aquellos que migraron con sus padres, siendo los problemas de conducta atribuibles a los procesos de aculturación. Sin embargo, los inmigrantes de primera generación y los refugiados a menudo tienen menos problemas de conducta que sus pares. Referencia: DSM-5-TR, Trastorno de la conducta / Factores de riesgo y pronóstico (pp. 534-535).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', '¿Qué no es un factor de riesgo o pronóstico asociado al trastorno de la conducta?', '["Hermano biológico con trastorno de la conducta.", "Baja conductancia de la piel.", "Padre adoptivo con trastorno de la conducta.", "Aumento del condicionamiento autonómico del miedo."]', 3, 'La reducción del condicionamiento autonómico del miedo, particularmente la baja conductancia de la piel, está bien documentada en los individuos con trastorno de la conducta; sin embargo, este hallazgo no es diagnóstico del trastorno. El riesgo del trastorno de la conducta se incrementa en los niños con un padre biológico o adoptivo o un hermano con trastorno de la conducta. Se han observado reiteradamente diferencias estructurales y funcionales en las áreas cerebrales asociadas con la regulación del afecto y el procesamiento del afecto, particularmente las conexiones frontotemporales-límbicas que comportan la corteza prefrontal ventral del cerebro y la amígdala, en los individuos con trastorno de la conducta. La persistencia es más probable en los individuos con comportamientos que cumplen los criterios del subtipo de inicio en la infancia y merecen el especificador con emociones prosociales limitadas. El riesgo de que el trastorno de la conducta persista también se incrementa si hay un trastorno de déficit de atención /hiperactividad coexistente y por el abuso de sustancias. Referencia: DSM-5-TR, Trastorno de la conducta / Factores de riesgo y pronóstico (pp. 534-535).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', '¿Cuál de las siguientes afirmaciones ayuda a distinguir el trastorno de la conducta del trastorno negativista desafiante (TND)?', '["El trastorno de la conducta es más probable que implique agresión hacia otras personas.", "El TND es más probable que implique conflictos con los padres.", "El trastorno de la conducta es más probable que implique un estado de ánimo enojado o irritable.", "El diagnóstico de trastorno de la conducta reemplaza y excluye al diagnóstico de TND."]', 0, 'El trastorno de la conducta y el TND están relacionados con síntomas que ponen al individuo en conflicto con adultos y otras figuras de autoridad (por ejemplo, padres, maestros, supervisores de trabajo). Los comportamientos del TND son típicamente de naturaleza menos grave comparados con los del trastorno de la conducta y no incluyen la agresión a personas o animales, la destrucción de objetos ni el patrón de robo o engaño. Además, el TND incluye problemas de desregulación emocional (es decir, estado de ánimo enojado e irritable) que no están incluidos en la definición del trastorno de la conducta. Cuando se cumplen los criterios de ambos, TND y trastorno de la conducta, se pueden dar los dos diagnósticos. Referencia: DSM-5-TR, Trastorno de la conducta / Diagnóstico diferencial (pp. 536-537).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', '¿Cuál de los siguientes trastornos comórbidos no se asocia a la piromanía?', '["Trastorno de la personalidad antisocial.", "Trastornos por consumo de sustancias.", "Trastorno obsesivo-compulsivo.", "Trastorno de juego."]', 2, 'Parece haber una alta concurrencia de los trastornos por consumo de sustancias, el trastorno de juego, los trastornos depresivos y bipolares, y otros trastornos disruptivos, del control de los impulsos y de la conducta con la piromanía. El encendido de fuegos en los menores también puede estar asociado con el trastorno de la conducta o el trastorno de déficit de atención/hiperactividad. Aunque la provocación de incendios por niños y adolescentes en Estados Unidos es un problema importante, el diagnóstico real de piromanía es raro. Referencia: DSM-5-TR, Piromanía / Diagnóstico diferencial (p. 539).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', 'Un estudiante de 15 años de una escuela privada, sin historial psiquiátrico conocido, ha sido sorprendido robando los portátiles y teléfonos móviles de otros estudiantes a pesar de que proviene de una familia adinerada y sus padres continúan comprándole los últimos dispositivos electrónicos para tratar de disuadirlo de robar. ¿Cuál de las siguientes opciones aumentaría la sospecha clínica de que el paciente puede tener cleptomanía?', '["Es reiteradamente incapaz de resistir los impulsos de robar objetos que no son necesarios ni para su uso personal ni por su valor monetario.", "Es reiteradamente incapaz de resistir los impulsos de robar objetos durante períodos de desconexión o aburrimiento.", "Experimenta una tensión creciente antes de cometer el robo, pero no experimenta alivio, placer o gratificación mientras lo comete.", "Tiene un amplio historial familiar de trastorno de la personalidad antisocial y trastorno de la conducta."]', 0, 'La cleptomanía se define por la incapacidad recurrente de resistir los impulsos de robar objetos, incluso cuando estos no son necesarios para uso personal ni tienen especial valor monetario (Criterio A). El individuo experimenta una sensación creciente de tensión antes del acto (Criterio B) y luego obtiene placer o gratificación al cometer el robo (Criterio C). El acto no se realiza en respuesta a la ira o la venganza, y el robo que ocurre en la cleptomanía no se explica mejor por el trastorno de la conducta, un episodio maníaco o el trastorno de la personalidad antisocial (Criterio E). Parece haber una mayor tasa de trastornos por consumo de alcohol entre los familiares de primer grado de los individuos con cleptomanía que entre la población general. Referencia: DSM-5-TR, Cleptomanía / Criterios diagnósticos (p. 539), Factores de riesgo y pronóstico (p. 540).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', '¿Cuál de las siguientes afirmaciones sobre la cleptomanía es falsa?', '["La prevalencia de la cleptomanía en la población general es generalmente muy baja y el trastorno es más frecuente entre las mujeres.", "Los familiares de primer grado de los individuos con cleptomanía pueden tener tasas más altas de trastorno obsesivo-compulsivo y/o trastornos por consumo de sustancias que la población general.", "La cleptomanía puede ocurrir en un episodio maníaco como respuesta a un delirio o alucinación.", "Los individuos con cleptomanía generalmente no planean previamente sus robos."]', 2, 'La cleptomanía debe distinguirse del robo intencional o inadvertido que puede ocurrir durante un episodio maníaco, en respuesta a delirios o alucinaciones (por ejemplo, en la esquizofrenia) o como resultado de un trastorno neurocognitivo mayor. La característica clave de la cleptomanía es la incapacidad recurrente de resistir los impulsos de robar objetos, incluso cuando no son necesarios, y el individuo es consciente de que el acto no tiene sentido. Referencia: DSM-5-TR, Cleptomanía / Características diagnósticas (p. 539), Prevalencia (p. 540), Diagnóstico diferencial (pp. 540-541).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', '¿Qué diagnóstico se asocia a un mayor riesgo de ideación y comportamiento suicida?', '["Trastorno explosivo intermitente (TEI).", "Cleptomanía.", "Trastorno negativista desafiante (TND).", "Todos los anteriores."]', 3, 'Un estudio de 1.460 voluntarios de investigación encontró que el TEI comórbido con el trastorno de estrés postraumático se asociaba a una tasa marcadamente elevada de intentos de suicidio durante la vida. El TND se ha asociado con un mayor riesgo de intentos de suicidio, incluso después de controlar los trastornos comórbidos. La cleptomanía se ha asociado a un mayor riesgo de intentos de suicidio. Referencia: DSM-5-TR, Trastorno negativista desafiante / Características asociadas (p. 524), Trastorno explosivo intermitente / Asociación a pensamientos o conductas suicidas (p. 529); Cleptomanía / Asociación a pensamientos o conductas suicidas (p. 540).'),
('DSM-5-TR', 'Trastornos disruptivos, del control de los impulsos y de la conducta', 'Un niño de 12 años con antecedentes de discusiones verbales con sus padres y maestros fue cruel con la mascota de la familia, un hámster, hace 3 meses. El mes pasado robó la tarjeta de crédito de su madre para comprar videojuegos y ropa. Lo llevan a la sala de urgencias después de que la policía lo recogiera por haber iniciado un incendio en uno de los callejones cerca del edificio de apartamentos de sus padres. ¿Qué información indicaría que esto podría deberse a una piromanía, en lugar de a un trastorno de la conducta?', '["Quemó la ropa que había robado para evitar ser descubierto.", "Está intoxicado y oye voces que le ordenaban iniciar el incendio.", "Practicó iniciando fuegos más pequeños en la escuela y en casa, y guardó las cenizas.", "Inició el incendio a propósito."]', 2, 'La característica esencial de la piromanía es la presencia de múltiples episodios de incendios provocados de forma deliberada y premeditada (Criterio A). Existe fascinación, interés, curiosidad o atracción hacia el fuego y sus contextos situacionales (por ejemplo, parafernalia, usos, consecuencias) (Criterio C). El inicio del fuego no se provoca para ocultar una actividad delictiva, para expresar ira o venganza, ni en respuesta a un delirio o alucinación (Criterio E). El inicio del fuego no se debe a deterioro del juicio. El inicio del fuego puede ser deliberado tanto en el trastorno de la conducta como en la piromanía. Referencia: DSM-5-TR, Piromanía / Criterios diagnósticos y Características diagnósticas (pp. 537-538).')
) as v(curso, tema, pregunta, opciones, correcta, explicacion)
where not exists (
  select 1 from public.preguntas p
  where p.curso = v.curso and p.pregunta = v.pregunta and p.opciones = v.opciones::jsonb
);
